/**
 * External dependencies
 */
import { useDispatch, useSelect } from '@wordpress/data';
import { useCallback, useEffect } from '@wordpress/element';
import { __unstableMotion as motion, Popover } from '@wordpress/components';

/**
 * Internal dependencies
 */
import './style.scss';
import SiteSpecLanding from '@components/site-spec-landing';
import OnboardingBuildingView from '@components/onboarding/building-view';
import { store as aiStore } from '@store';
import useBuildSiteTool from '@ai/assistants/spec/tools/build-site/use-build-site-tool';
import useSpecProcessor from '@hooks/use-spec-processor';
import log from '@utils/log-debug';
import { removeUrlParam } from '@utils/url-params';
// Removed useChat import - setStoreConversation functionality may need to be added to store if needed

export default function Onboarding() {
	const { setHeaderSectionIsReady, setBigSkyPendingSpec, setIsBuildingSite } =
		useDispatch( aiStore );
	const { buildSiteTask } = useBuildSiteTool();
	const {
		isBuildingSite,
		isEditorIframeLoaded,
		pendingSpec,
		isProcessingSpec,
		isCiab,
	} = useSelect( ( select ) => ( {
		apiKey: select( aiStore ).getApiKey(),
		sessionId: select( aiStore ).getSessionId(),
		isBuildingSite: select( aiStore ).getIsBuildingSite(),
		isEditorIframeLoaded: select( aiStore ).getIsEditorIframeLoaded(),
		pendingSpec: select( aiStore ).getBigSkyPendingSpec(),
		isProcessingSpec: select( aiStore ).getIsProcessingSpec(),
		isCiab: select( aiStore ).getIsCiab(),
	} ) );

	const searchParams = new URLSearchParams( window.location.search );
	const passedSpec = searchParams.get( 'spec_id' ) || '';

	// Use the spec processor hook to handle spec processing
	useSpecProcessor( passedSpec );

	// Wait for canvas to be ready before triggering build
	// console.log(`isEditorIframeLoaded: ${isEditorIframeLoaded}, pendingSpec: ${pendingSpec}, isBuildingSite: ${isBuildingSite}`); // Debug log
	useEffect( () => {
		if (
			isEditorIframeLoaded &&
			pendingSpec &&
			! isBuildingSite &&
			! isProcessingSpec
		) {
			setIsBuildingSite( true );

			( async () => {
				try {
					setHeaderSectionIsReady( false );
					await buildSiteTask( pendingSpec, isCiab );
					log.info( 'Build site triggered' );
					// Clean up
					setBigSkyPendingSpec( null );

					// Remove the spec parameter from URL after successful build
					removeUrlParam( 'spec_id' );
				} catch ( error ) {
					log.error( 'Error triggering build:', error );
					setIsBuildingSite( false );
				}
			} )();
		}
	}, [
		isEditorIframeLoaded,
		setHeaderSectionIsReady,
		setIsBuildingSite,
		setBigSkyPendingSpec,
		pendingSpec,
		isBuildingSite,
		buildSiteTask,
		isProcessingSpec,
		isCiab,
	] );

	const getOnboardingView = useCallback( () => {
		if ( isBuildingSite || isProcessingSpec || passedSpec ) {
			return <OnboardingBuildingView isCiab={ isCiab } />;
		}

		return <SiteSpecLanding key="site-spec-landing-view" />;
	}, [ isBuildingSite, isProcessingSpec, passedSpec, isCiab ] );

	return (
		<Popover className="big-sky-onboarding" resize={ false }>
			<motion.div
				className="big-sky-onboarding__content big-sky-onboarding__content--glow"
				key="onboarding-content"
			>
				{ getOnboardingView() }
			</motion.div>
		</Popover>
	);
}
