import log from '@utils/log-debug';

/**
 * Removes a query parameter from the current URL without reloading page
 *
 * @param {string} paramName - The parameter name to remove
 */
export const removeUrlParam = ( paramName ) => {
	const newUrl = new URL( window.location );
	newUrl.searchParams.delete( paramName );
	window.history.replaceState( {}, '', newUrl );
	log.info( `URL parameter '${ paramName }' removed` );
};

// Matches the `source` value Calypso's launch-big-sky step sets when the user
// arrived via woocommerce.com/start/#hosts and purchased an eCommerce plan
// (see Automattic/wp-calypso `launch-big-sky/index.tsx`). Same signal the
// SiteSpecAgent uses to inject store-flavored onboarding instructions.
export const WOO_HOSTING_SOLUTIONS_SOURCE = 'woo-hosting-solutions';

/**
 * Whether the current page was reached via the Woo hosting solutions onboarding flow.
 *
 * Detected by `source=woo-hosting-solutions` on the site-editor URL, which
 * Calypso's launch-big-sky step sets when the user came from the
 * woo-hosting-solutions stepper.
 *
 * @return {boolean} True when the source param matches.
 */
export const isWooHostingFlow = () => {
	if ( typeof window === 'undefined' ) {
		return false;
	}
	const params = new URLSearchParams( window.location.search );
	return params.get( 'source' ) === WOO_HOSTING_SOLUTIONS_SOURCE;
};
