/**
 * WordPress dependencies
 */
import { useSelect } from '@wordpress/data';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';

export default function useIsThinking() {
	const { isThinking, pendingToolCallbacks } = useSelect( ( select ) => ( {
		isThinking: select( aiStore ).getIsThinking(),
		pendingToolCallbacks: select( aiStore ).getPendingToolCallbacks(),
	} ) );

	return {
		isThinking: isThinking || pendingToolCallbacks > 0,
	};
}
