/**
 * External dependencies
 */
import { WPCOMJetpackAIChatModel } from './chat-model.js';

/**
 * Internal dependencies
 */
import { requestJetpackToken } from '@utils/request-jetpack-token.ts';
import log from '@utils/log-debug.js';
import { INTERNAL_VISION_MODELS } from '@utils/constants';

let currentChatMessageModel = null;

export const runChatCompletion =
	(
		model,
		messages = [],
		tools,
		temperature = 0.1,
		response_format = 'text',
		retry = false
	) =>
	async ( { select, dispatch } ) => {
		const jetpackToken = await requestJetpackToken( ! retry );
		if ( ! jetpackToken ) {
			return;
		}
		const params = {
			model,
			messages,
			stream: false,
			temperature,
			session_id: select.getSessionId(),
		};

		if ( tools ) {
			params.tools = tools;

			if ( model === select.getAdvancedChatModel() ) {
				params.parallel_tool_calls = false;
			}
		}

		if ( response_format ) {
			params.response_format = response_format;
		}

		const isDevMode = window.bigSkyInitialState?.isDevMode ?? false;

		const ChatModelClass = WPCOMJetpackAIChatModel;
		const chatModel = new ChatModelClass( {
			apiKey: jetpackToken.token,
			feature: isDevMode ? 'big-sky-dev' : 'big-sky',
			sessionId: select.getSessionId(),
		} );

		currentChatMessageModel = chatModel;

		try {
			const response = await chatModel.call( params );
			return response;
		} catch ( e ) {
			// Temporary fix to reset the agent conversation history in case of a quota exceeded error.
			setTimeout( () => {
				dispatch.resetConversation();
			}, 1000 );
			if ( e.name === 'AbortError' ) {
				throw e;
			}
			// retry once with a new token
			if ( ! retry ) {
				try {
					return await dispatch.runChatCompletion(
						model,
						messages,
						tools,
						temperature,
						response_format,
						true
					);
				} catch ( retryError ) {
					if ( model !== INTERNAL_VISION_MODELS.LLAMA3_11B ) {
						dispatch.setError(
							'OpenAI error: ' + retryError.message
						);
					}
					throw retryError;
				}
			}

			if ( model !== INTERNAL_VISION_MODELS.LLAMA3_11B ) {
				dispatch.setError( 'OpenAI error: ' + e );
			}
			throw e;
		}
	};

export const generateImage =
	( {
		model,
		prompt,
		n = 1,
		size,
		response_format = 'url',
		output_format = 'png',
		output_compression = 90,
		doRetry = true,
		quality = 'low',
		remove_background = true,
		image = null,
		background = 'auto',
	} ) =>
	async ( { select, dispatch } ) => {
		try {
			const jetpackToken = await requestJetpackToken();
			if ( ! jetpackToken ) {
				return;
			}
			const imageGenerationUrl =
				'https://public-api.wordpress.com/wpcom/v2/jetpack-ai-image';

			const isDevMode = window.bigSkyInitialState?.isDevMode ?? false;

			const params = {
				model,
				prompt,
				n,
				size,
				response_format,
				remove_background,
				output_format,
				output_compression,
				feature: isDevMode ? 'big-sky-dev' : 'big-sky',
				session_id: select.getSessionId(),
				quality,
				background,
			};

			let requestBody;
			const headers = {
				Authorization: `Bearer ${ jetpackToken.token }`,
			};

			if ( image && image instanceof File ) {
				// Use FormData for image editing - the API expects file uploads as multipart/form-data
				const formData = new FormData();
				Object.entries( params ).forEach( ( [ key, value ] ) => {
					if ( value !== undefined ) {
						formData.append( key, value );
					}
				} );
				formData.append( 'image', image );

				requestBody = formData;
				// Don't set Content-Type for FormData, let the browser set it with boundary
			} else {
				// Use JSON for regular image generation
				requestBody = JSON.stringify( params );
				headers[ 'Content-Type' ] = 'application/json';
			}

			const request = await fetch( imageGenerationUrl, {
				method: 'POST',
				headers,
				body: requestBody,
			} );

			if ( request.status >= 300 ) {
				// retry once with a new token
				if ( doRetry ) {
					return dispatch.generateImage( {
						model,
						prompt,
						n,
						size,
						response_format,
						output_format,
						output_compression,
						doRetry: false,
						quality,
						image,
						background,
					} );
				}

				log.error( 'Error calling Image Generation API:', request );
				return null;
			}
			const response = await request.json();

			return response;
		} catch ( e ) {
			// retry once with a new token
			if ( doRetry ) {
				return dispatch.generateImage( {
					model,
					prompt,
					n,
					size,
					response_format,
					output_format,
					output_compression,
					doRetry: false,
					quality,
					image,
					background,
				} );
			}

			log.error( 'Error calling Image Generation API:', e );
			return null;
		}
	};

export const getCurrentChatMessageModel = () => currentChatMessageModel;
