/**
 * WordPress dependencies
 */
import { store as coreStore } from '@wordpress/core-data';
import { dispatch, select, useSelect } from '@wordpress/data';
import { __ } from '@wordpress/i18n';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import { hasSiteBuildMessages } from '@components/site-build-progress/group-messages';
import { isWooHostingFlow } from '@utils/url-params';
import { recordTracksEvent } from '@utils/tracks';

// Localized in big-sky.php as `admin_url( 'admin.php?page=wc-admin' )`. Falls
// back to the canonical default if the global isn't present (tests, dev).
const getWcAdminUrl = () =>
	window?.bigSkyInitialState?.wcAdminUrl ||
	'/wp-admin/admin.php?page=wc-admin';

/**
 * Synchronously clear all dirty entity records so Gutenberg's
 * `UnsavedChangesWarning` (which re-reads `__experimentalGetDirtyEntityRecords`
 * inside its `beforeunload` handler) sees nothing dirty and skips the prompt.
 *
 * After a reload on `ai-step=edit`, editor initialization re-dirties entities
 * (commonly `globalStyles` or the page record) before the user touches
 * anything. Clicking "Complete setup" is an intentional abandon, so dropping
 * those edits is correct.
 *
 * Uses `discardEditedEntityRecord` if the runtime exposes it (newer Gutenberg).
 * Otherwise falls back to writing each edited key back to its raw saved value.
 * The fallback matters because:
 *   1. `@wordpress/core-data@7.36` (the externalized version on Jurassic
 *      Ninja) does not export `discardEditedEntityRecord`.
 *   2. `editEntityRecord`'s internal "is this a no-op?" check deep-equals
 *      against `getRawEntityRecord`, NOT `getEntityRecord` — for entities
 *      like `wp_template` those return different shapes (parsed blocks vs.
 *      raw HTML), so passing values from `getEntityRecord` re-dirties
 *      instead of clearing. Read raw values explicitly.
 *
 * Each per-record op is wrapped so a failure on one entity (e.g. unloaded
 * entity config) doesn't abort the rest.
 */
function clearDirtyEntityRecords() {
	const coreSelect = select( coreStore );
	const coreDispatch = dispatch( coreStore );
	const dirty = coreSelect.__experimentalGetDirtyEntityRecords?.() ?? [];
	const canDiscard =
		typeof coreDispatch.discardEditedEntityRecord === 'function';

	dirty.forEach( ( { kind, name, key } ) => {
		try {
			if ( canDiscard ) {
				coreDispatch.discardEditedEntityRecord( kind, name, key );
				return;
			}
			const raw = coreSelect.getRawEntityRecord( kind, name, key );
			const edits = coreSelect.getEntityRecordEdits( kind, name, key );
			if ( ! raw || ! edits ) return;
			const revert = {};
			Object.keys( edits ).forEach( ( editedKey ) => {
				revert[ editedKey ] = raw[ editedKey ];
			} );
			coreDispatch.editEntityRecord( kind, name, key, revert );
		} catch {
			// Best-effort: if a record's config isn't loaded or the API
			// call throws, fall through and let the rest of the loop run.
		}
	} );
}

/**
 * "Complete setup" exit link shown in the dock footer for users in the Woo
 * hosting solutions onboarding flow, once their AI-built site is ready.
 *
 * Without this link, those users would be stuck — the surrounding flow hides
 * the Gutenberg toolbar, so the dock is the only navigation surface.
 *
 * @return {JSX.Element|null} The link, or null when not applicable.
 */
export default function CompleteSetupButton() {
	const { hasCompletedMessages, aiStep, isBuildingSite } = useSelect(
		( reactiveSelect ) => {
			const ai = reactiveSelect( aiStore );
			return {
				hasCompletedMessages: hasSiteBuildMessages( ai.getMessages() ),
				aiStep: ai.getAiStep(),
				isBuildingSite: ai.getIsBuildingSite(),
			};
		},
		[]
	);

	// Show the button if the store has a completion message (normal flow) OR
	// if we're already in the post-spec edit step (page reload). The spec
	// builder always advances to ai-step=edit on completion, so the step is a
	// reliable signal that the build is done.
	//
	// Suppress while a build is still in progress: hasSiteBuildMessages flips
	// true on the first completed step (e.g. compose_layouts), not the final
	// one, so without this gate the exit link would surface mid-build and
	// invite users to bail before their site is finished.
	const isReady =
		! isBuildingSite && ( hasCompletedMessages || aiStep === 'edit' );

	if ( ! isReady || ! isWooHostingFlow() ) {
		return null;
	}

	const handleClick = () => {
		recordTracksEvent( 'big_sky_complete_setup_click', {
			destination: 'wc-admin',
		} );
		clearDirtyEntityRecords();
		window.location.assign( getWcAdminUrl() );
	};

	return (
		<button
			type="button"
			className="big-sky__complete-setup-button"
			onClick={ handleClick }
		>
			{ /* translators: button label that exits Big Sky onboarding into wp-admin */ }
			{ __( 'Complete setup', 'big-sky' ) }
			<span aria-hidden="true"> →</span>
		</button>
	);
}
