import type { Suggestion } from '@automattic/agenttic-ui';
import { useDispatch, useSelect } from '@wordpress/data';
import { store as blockEditorStore } from '@wordpress/block-editor';
import { useCallback, useEffect, useRef, useState } from '@wordpress/element';
import { store as aiStore } from '@store';

// Import pure suggestion logic and types
import {
	type BlockContext,
	filterSuggestionsForTheme,
	getEmptyViewSuggestions,
	getSuggestions,
} from './suggestions-data';

// Re-export for backwards compatibility
export { type BlockContext, getEmptyViewSuggestions, getSuggestions };

/**
 * Hook to get suggestions for the currently selected block with local state management
 * @param count the count of suggestions to return. If 0, all matching suggestions will be returned.
 * @return object containing suggestions array and clearSuggestions method
 */
export const useSuggestions = ( count: number = 3 ) => {
	const [ currentSuggestions, setCurrentSuggestions ] = useState<
		Suggestion[]
	>( [] );

	const { selectedBlock, suppressSuggestions } = useSelect( ( select ) => {
		return {
			selectedBlock: (
				select( blockEditorStore ) as any
			 ).getSelectedBlock(),
			suppressSuggestions: (
				select( aiStore ) as any
			 ).getSuppressSuggestions(),
		};
	}, [] );

	const { setSuppressSuggestions } = useDispatch( aiStore ) as any;

	const prevSelectedBlockRef = useRef( selectedBlock );

	const clearSuggestions = useCallback( () => {
		setCurrentSuggestions( [] );
	}, [] );

	// Clear suppression when selectedBlock changes (user interaction)
	useEffect( () => {
		const hasSelectionChanged =
			prevSelectedBlockRef.current !== selectedBlock;
		prevSelectedBlockRef.current = selectedBlock;

		if ( ! hasSelectionChanged ) {
			return;
		}

		if ( ! selectedBlock ) {
			setSuppressSuggestions( true );
		} else if ( suppressSuggestions ) {
			setSuppressSuggestions( false );
		}
	}, [ selectedBlock, suppressSuggestions, setSuppressSuggestions ] );

	useEffect( () => {
		// Don't show suggestions if suppressed
		if ( suppressSuggestions || ! selectedBlock ) {
			setCurrentSuggestions( [] );
			return;
		}

		const newSuggestions = getSuggestions( selectedBlock, count );
		const filteredSuggestions = filterSuggestionsForTheme( newSuggestions );
		setCurrentSuggestions( filteredSuggestions );
	}, [ selectedBlock, count, suppressSuggestions ] );

	// On mount, start with empty suggestions
	useEffect( () => {
		setCurrentSuggestions( [] );
	}, [] );

	return {
		suggestions: currentSuggestions,
		clearSuggestions,
	};
};
