/**
 * WordPress dependencies
 */
import { store as blockEditorStore } from '@wordpress/block-editor';
import { store as coreStore } from '@wordpress/core-data';
import { useDispatch, useSelect } from '@wordpress/data';
import { useCallback } from '@wordpress/element';
import { store as editorStore } from '@wordpress/editor';
import { doAction } from '@wordpress/hooks';

/**
 * Internal dependencies
 */
import useBlocks from '@hooks/use-blocks';
import usePages from '@hooks/use-pages';
import useTemplateParts from '@hooks/use-template-parts';
import useSiteMetadata from '@hooks/use-site-metadata';
import useStyles from '@hooks/use-styles';
import useVariations from '@hooks/use-variations';
import { store as aiStore } from '@store';
import { TemplatePartSlug } from '@utils/template-parts';

export default function useCheckpoint() {
	const {
		getLastEditorState,
		getEditedEntityRecord,
		getMessages,
		getCheckpoint,
	} = useSelect( ( select ) => {
		const ai = select( aiStore );
		const core = select( coreStore );

		return {
			getLastEditorState: ai.getLastEditorState,
			getEditedEntityRecord: core.getEditedEntityRecord,
			getMessages: ai.getMessages,
			getCheckpoint: ai.getCheckpoint,
		};
	} );
	const { getCurrentTheme, setStyles } = useStyles();
	const {
		modifyGeneratedVariation,
		addCheckpoint,
		removeCheckpoint,
		updateCheckpoint,
	} = useDispatch( aiStore );
	const { replaceInnerBlocks } = useDispatch( blockEditorStore );
	const { editEntityRecord, saveEntityRecord } = useDispatch( coreStore );
	const { undo } = useDispatch( editorStore );
	const { getRootBlocksState, getSectionRootClientId } = useBlocks();

	const { getCurrentColor, getCurrentFont, getCurrentButtonStyle } =
		useSelect( aiStore );
	const {
		currentColor: currentColorMeta,
		currentFont: currentFontMeta,
		currentButtonStyle: currentButtonMeta,
		siteLocation,
	} = useSiteMetadata().getSiteMetadata();
	const { replaceTemplatePart } = useTemplateParts();
	const { setSiteLocation } = useSiteMetadata();
	const { deletePage, renamePage, goBackPage } = usePages();
	const { getColorVariationByTitle } = useVariations();

	// Get global styles ID for theme restoration
	const { globalStylesId } = useSelect( ( select ) => {
		const core = select( coreStore );
		return {
			globalStylesId: core.__experimentalGetCurrentGlobalStylesId(),
		};
	}, [] );

	// Helper function to get the latest user message ID
	const getLatestUserMessageId = useCallback( () => {
		const messages = getMessages();
		const userMessages = messages.filter(
			( message ) => message.role === 'user'
		);
		const latestUserMessage = userMessages[ userMessages.length - 1 ];
		return latestUserMessage?.id;
	}, [ getMessages ] );

	const setCheckpoint = useCallback(
		( id, keys = [] ) => {
			if ( ! id ) {
				return;
			}

			const entityRecord = getEditedEntityRecord(
				'root',
				'site',
				undefined
			);

			// copy the current color theme
			const currentColor = getCurrentColor() || currentColorMeta;
			const currentTheme = JSON.parse(
				JSON.stringify(
					getColorVariationByTitle( currentColor ) ||
						getCurrentTheme()
				)
			);

			// get the blocks
			const currentBlocks = JSON.parse(
				JSON.stringify( getRootBlocksState() )
			);
			// remove any processing state from all the blocks, recursively loop through inner blocks
			const removeProcessingState = ( blocks ) => {
				// Safety check: ensure blocks is an array
				if ( ! Array.isArray( blocks ) ) {
					return;
				}

				blocks.forEach( ( block ) => {
					if (
						block?.innerBlocks &&
						Array.isArray( block.innerBlocks )
					) {
						removeProcessingState( block.innerBlocks );
					}
					// Remove processing-related CSS classes from block attributes
					if ( block?.attributes?.className ) {
						const classes = block.attributes.className.split( ' ' );
						const filteredClasses = classes.filter(
							( className ) =>
								! className.startsWith(
									'big-sky__is-processing'
								) &&
								! className.startsWith(
									'big-sky__has-processed'
								)
						);
						block.attributes.className =
							filteredClasses.join( ' ' );
					}
				} );
			};

			// Process each block array from the root blocks state
			removeProcessingState( currentBlocks.headerBlocks );
			removeProcessingState( currentBlocks.headerHeroBlocks );
			removeProcessingState( currentBlocks.footerBlocks );
			removeProcessingState( currentBlocks.contentBlocks );

			// Get current global styles entity record for theme restoration
			const currentGlobalStyles = getEditedEntityRecord(
				'root',
				'globalStyles',
				globalStylesId
			);
			const globalStylesBeforeUpdate = currentGlobalStyles
				? JSON.parse( JSON.stringify( currentGlobalStyles ) )
				: null;

			const editorState = {
				blocks: currentBlocks,
				color: {
					name: currentColor,
					theme: currentTheme,
				},
				font: getCurrentFont() || currentFontMeta,
				button: getCurrentButtonStyle() || currentButtonMeta,
				siteLocation,
				siteLogo: entityRecord.site_logo,
				checkpointKeys: keys,
				...( globalStylesBeforeUpdate && {
					themeBeforeUpdate: {
						settings: globalStylesBeforeUpdate.settings || {},
						styles: globalStylesBeforeUpdate.styles || {},
					},
				} ),
			};

			// Add checkpoint for the current user message
			addCheckpoint( id, editorState );
		},
		[
			getEditedEntityRecord,
			getCurrentColor,
			currentColorMeta,
			getColorVariationByTitle,
			getCurrentTheme,
			addCheckpoint,
			getRootBlocksState,
			getCurrentFont,
			currentFontMeta,
			getCurrentButtonStyle,
			currentButtonMeta,
			siteLocation,
			globalStylesId,
		]
	);

	const addCheckpointKeys = useCallback(
		( id, keys ) => {
			if ( ! id ) {
				return;
			}
			if ( ! keys ) keys = [];

			const existingCheckpoint = getCheckpoint( id );
			if ( existingCheckpoint ) {
				// Update the existing checkpoint with the new keys
				const updatedEditorState = {
					...existingCheckpoint,
					checkpointKeys: [
						...new Set( [
							...( existingCheckpoint?.checkpointKeys || [] ),
							...keys,
						] ),
					],
				};

				updateCheckpoint( id, updatedEditorState );
			}
		},
		[ getCheckpoint, updateCheckpoint ]
	);

	const addNewPageToCheckpoint = useCallback(
		( pageId ) => {
			const lastEditorState = getLastEditorState();
			if ( lastEditorState ) {
				const updatedEditorState = {
					...lastEditorState,
					newPageId: pageId,
				};
				updateCheckpoint( lastEditorState.id, updatedEditorState );
			}
		},
		[ getLastEditorState, updateCheckpoint ]
	);

	const addPageRenameToCheckpoint = useCallback(
		( pageId, oldTitle, newTitle ) => {
			const lastEditorState = getLastEditorState();
			if ( lastEditorState ) {
				const updatedEditorState = {
					...lastEditorState,
					pageRename: {
						pageId,
						oldTitle,
						newTitle,
					},
				};
				updateCheckpoint( lastEditorState.id, updatedEditorState );
			}
		},
		[ getLastEditorState, updateCheckpoint ]
	);

	const addPageRemovalToCheckpoint = useCallback(
		( pageId, pageTitle, { shouldRestoreNavigation = false } = {} ) => {
			const lastEditorState = getLastEditorState();
			if ( lastEditorState ) {
				const updatedEditorState = {
					...lastEditorState,
					pageRemoval: {
						pageId,
						pageTitle,
						shouldRestoreNavigation,
					},
				};
				updateCheckpoint( lastEditorState.id, updatedEditorState );
			}
		},
		[ getLastEditorState, updateCheckpoint ]
	);

	const restoreCheckpoint = useCallback(
		async ( id ) => {
			const checkpoint = getCheckpoint( id );

			if ( checkpoint ) {
				// just restore all keys no matter what, since these checkpoints persist across requests
				// reset styles

				// Handle page operations restoration
				// Handle page deletion if a new page was created
				if ( checkpoint.newPageId ) {
					deletePage( checkpoint.newPageId );
					goBackPage();
					return;
				}

				// Handle page removal restoration
				if ( checkpoint.pageRemoval ) {
					const { pageId, shouldRestoreNavigation } =
						checkpoint.pageRemoval;

					// Reinstate the Page from Trash.
					saveEntityRecord( 'postType', 'page', {
						id: pageId,
						status: 'publish',
					} );

					// Revert the change to the Navigation Menu.
					if ( shouldRestoreNavigation ) {
						undo();
					}
					return;
				}

				// Restore theme state FIRST if it was stored before theme update
				// This ensures setStyles works with the complete global styles structure
				if ( checkpoint.themeBeforeUpdate && globalStylesId ) {
					// Handle both old format (direct color.palette) and new format (settings.color.palette)
					let settingsToRestore = {};
					let stylesToRestore = {};

					if ( checkpoint.themeBeforeUpdate.settings ) {
						// New format: has settings and styles
						settingsToRestore =
							checkpoint.themeBeforeUpdate.settings;
						stylesToRestore =
							checkpoint.themeBeforeUpdate.styles || {};
					} else if ( checkpoint.themeBeforeUpdate.color ) {
						// Old format: direct color.palette structure
						// Convert to new format
						settingsToRestore = {
							color: {
								palette:
									checkpoint.themeBeforeUpdate.color
										.palette || {},
							},
						};
						stylesToRestore =
							checkpoint.themeBeforeUpdate.styles || {};
					}

					editEntityRecord(
						'root',
						'globalStyles',
						globalStylesId,
						{
							settings: settingsToRestore,
							styles: stylesToRestore,
						},
						{ undoIgnore: true }
					);
				}

				const stylesToRestore = {};
				if ( checkpoint.color ) {
					modifyGeneratedVariation(
						checkpoint.color.name,
						checkpoint.color.theme
					);
					stylesToRestore.color = checkpoint.color.name;
				}
				if ( checkpoint.font ) {
					stylesToRestore.font = checkpoint.font;
				}
				if ( checkpoint.button ) {
					stylesToRestore.button = checkpoint.button;
				}
				setStyles( stylesToRestore );

				// reset blocks
				if ( checkpoint.blocks ) {
					// reset the template parts
					replaceTemplatePart(
						TemplatePartSlug.Header,
						checkpoint?.blocks?.headerBlocks
					);
					// await here since the client ids of the header hero blocks change
					await replaceTemplatePart(
						TemplatePartSlug.HeaderHero,
						checkpoint?.blocks?.headerHeroBlocks
					);
					replaceTemplatePart(
						TemplatePartSlug.Footer,
						checkpoint?.blocks?.footerBlocks
					);

					// reset the content
					replaceInnerBlocks(
						getSectionRootClientId(),
						checkpoint?.blocks?.contentBlocks
					);
				}

				// reset the site location
				// TODO: Remove setSiteLocation usage once checkpoint restoration is migrated
				if ( checkpoint.siteLocation ) {
					setSiteLocation( checkpoint.siteLocation );
				}

				// reset the site logo
				if ( checkpoint.siteLogo ) {
					editEntityRecord( 'root', 'site', undefined, {
						site_logo: checkpoint.siteLogo,
					} );
				}

				// Handle page and navigation rename restoration
				if ( checkpoint.pageRename ) {
					const { pageId, oldTitle } = checkpoint.pageRename;
					renamePage( pageId, oldTitle );
				}

				// Fire the checkpoint restored action after all restoration is complete
				doAction( 'big-sky.checkpoint-restored', {
					checkpointId: id,
					checkpoint,
				} );
			}
		},
		[
			getCheckpoint,
			setStyles,
			modifyGeneratedVariation,
			replaceTemplatePart,
			replaceInnerBlocks,
			getSectionRootClientId,
			setSiteLocation,
			editEntityRecord,
			deletePage,
			goBackPage,
			renamePage,
			saveEntityRecord,
			undo,
			globalStylesId,
		]
	);

	const clearCheckpoint = useCallback(
		( userMessageId ) => {
			removeCheckpoint( userMessageId );
		},
		[ removeCheckpoint ]
	);

	const hasCheckpoint = useCallback(
		( id ) => {
			const checkpoint = getCheckpoint( id );
			return !! checkpoint?.checkpointKeys?.length;
		},
		[ getCheckpoint ]
	);

	return {
		getLastEditorState,
		setCheckpoint,
		addCheckpointKeys,
		restoreCheckpoint,
		addNewPageToCheckpoint,
		addPageRenameToCheckpoint,
		addPageRemovalToCheckpoint,
		getLatestUserMessageId,
		clearCheckpoint,
		hasCheckpoint,
	};
}
