/**
 * WordPress dependencies
 */
import { Button } from '@wordpress/components';
import { dispatch } from '@wordpress/data';
import { store as blockEditorStore } from '@wordpress/block-editor';
import { __ } from '@wordpress/i18n';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import { unlock } from '@utils/lock-unlock';
import { zoomIn as zoomInUtil } from '@utils/canvas-zoom';

const zoomIn = async () => {
	const { resetZoomLevel } = unlock( dispatch( blockEditorStore ) );
	const { __unstableSetEditorMode } = dispatch( blockEditorStore );

	return await zoomInUtil( {
		resetZoomLevel,
		__unstableSetEditorMode,
	} );
};

const NextStepButton = () => {
	const handleNextStep = async () => {
		const { runAgent, deleteMarkedMessages } = dispatch( aiStore );

		await zoomIn();
		runAgent( __( 'Moving to next step', 'big-sky' ) );
		deleteMarkedMessages();
	};

	return (
		<Button
			className="big-sky-next-step-button"
			variant="primary"
			onClick={ handleNextStep }
		>
			{ __( 'Move to next step', 'big-sky' ) }
		</Button>
	);
};

export default NextStepButton;
