import { useDispatch, useSelect } from '@wordpress/data';
import { memo, useEffect, useState } from '@wordpress/element';
import useVariations from '@hooks/use-variations';
import {
	MAX_VARIATIONS_TO_SHOW,
	MAX_VARIATIONS_TO_SHOW_PER_PAGE,
} from '@utils/constants';
import { store as aiStore } from '@store';
import useSiteMetadata from '@hooks/use-site-metadata';
import { calculateFontVariationsToShow } from '@utils/fonts';
import { createDynamicFontVariations } from './dynamic-font-variations';
import { injectFontFamiliesIntoEditorIframe } from '@utils/font-families-to-css';
import FontVariationPicker from '@components/font-variation-picker';

/**
 * Types
 */
interface FontFamilySettings {
	name: string;
	[ key: string ]: unknown;
}

interface FontVariationTypography {
	fontFamily: string;
	fontWeight: string;
	fontStyle: string;
}

interface FontVariationElements {
	heading: {
		typography: FontVariationTypography;
	};
	button: {
		typography: FontVariationTypography;
	};
}

interface FontVariationStyles {
	typography: FontVariationTypography;
	elements: FontVariationElements;
}

interface FontVariationSettings {
	typography: {
		fontFamilies: {
			theme: FontFamilySettings[];
		};
	};
}

interface FontVariation {
	title: string;
	version?: number;
	settings: FontVariationSettings;
	styles: FontVariationStyles;
}

interface GenerateFontVariationsParams {
	keywords?: string[];
	fonts?: string[];
	includeCurrent?: boolean;
	initialGeneration?: boolean;
	currentFontVariation?: FontVariation | null;
	getFontVariations?: () => FontVariation[];
	pushGeneratedVariations: ( variations: FontVariation[] ) => void;
	dynamicFontVariations?: FontVariation[];
}

interface GenerateFontVariationsAsyncParams {
	keywords?: string[];
	fonts?: string[];
	includeCurrent?: boolean;
	initialGeneration?: boolean;
	currentFontVariation?: FontVariation | null;
	getFontVariations?: () => FontVariation[];
	pushGeneratedVariations: ( variations: FontVariation[] ) => void;
}

interface ParseFontVariationsParams {
	themeVariations: FontVariation[];
	dynamicVariations: FontVariation[];
	includeCurrent: boolean;
	currentFontVariation: FontVariation | null;
	initialGeneration: boolean;
	pushGeneratedVariations: ( variations: FontVariation[] ) => void;
}

interface FontPickerProps {
	themeVariations?: FontVariation[];
	dynamicVariations?: FontVariation[];
	keywords?: string[];
	fonts?: string[];
	pairs?: unknown[];
	includeCurrent?: boolean;
	initialGeneration?: boolean;
}

export const generateFontVariations = (
	parameters: GenerateFontVariationsParams
): FontVariation[] => {
	const {
		keywords = [],
		fonts = [],
		includeCurrent = true,
		initialGeneration = false,
		currentFontVariation,
		getFontVariations,
		pushGeneratedVariations,
		dynamicFontVariations = [],
	} = parameters;

	let variations: FontVariation[] = [];

	if ( includeCurrent && currentFontVariation ) {
		variations.push( currentFontVariation );
	}

	const themeVariations = calculateFontVariationsToShow( {
		chosenFonts: fonts,
		keywords,
		getFontVariations,
	} );

	if ( themeVariations.length > 0 ) {
		variations.push( ...themeVariations );
	}

	// If it's not the initial generation, get dynamic font variations
	if ( ! initialGeneration ) {
		let dynamicFontVariationsSlice = dynamicFontVariations;
		if ( variations?.length ) {
			dynamicFontVariationsSlice = dynamicFontVariations.slice(
				0,
				MAX_VARIATIONS_TO_SHOW - variations.length
			);
		}

		variations.push( ...dynamicFontVariationsSlice );
		pushGeneratedVariations( dynamicFontVariationsSlice );

		// Load the font faces from variations as CSS in the editor
		const families = dynamicFontVariationsSlice.flatMap(
			( v ) => v.settings.typography.fontFamilies.theme
		);
		injectFontFamiliesIntoEditorIframe( families );
	}

	if ( includeCurrent && currentFontVariation ) {
		// Avoid showing the current font variation twice, the current font variation is always the first item
		variations = variations.filter(
			( variation, index ) =>
				index === 0 || variation.title !== currentFontVariation.title
		);
	}

	return variations;
};

/**
 * Generates font variations. Will fetch dynamic font variations based on google fonts if needed.
 * @param parameters - The parameters for generating font variations
 */
export const generateFontVariationsAsync = async (
	parameters: GenerateFontVariationsAsyncParams
): Promise< FontVariation[] > => {
	const { initialGeneration = false, fonts = [], keywords = [] } = parameters;

	let dynamicFontVariations: FontVariation[] = [];
	if ( ! initialGeneration ) {
		dynamicFontVariations = await createDynamicFontVariations(
			fonts,
			keywords
		);
	}

	return generateFontVariations( { ...parameters, dynamicFontVariations } );
};

const parseFontVariations = (
	parameters: ParseFontVariationsParams
): FontVariation[] => {
	const {
		themeVariations,
		dynamicVariations,
		includeCurrent,
		currentFontVariation,
		initialGeneration,
		pushGeneratedVariations,
	} = parameters;

	let variations: FontVariation[] = [];

	if ( includeCurrent && currentFontVariation ) {
		variations.push( currentFontVariation );
	}

	if ( themeVariations.length > 0 ) {
		variations.push( ...themeVariations );
	}

	if ( ! initialGeneration ) {
		let dynamicFontVariationsSlice = dynamicVariations;
		if ( variations?.length ) {
			dynamicFontVariationsSlice = dynamicVariations.slice(
				0,
				MAX_VARIATIONS_TO_SHOW - variations.length
			);
		}

		variations.push( ...dynamicFontVariationsSlice );
		pushGeneratedVariations( dynamicFontVariationsSlice );

		// Load the font faces from variations as CSS in the editor
		const families = dynamicFontVariationsSlice.flatMap(
			( v ) => v.settings.typography.fontFamilies.theme
		);
		injectFontFamiliesIntoEditorIframe( families );
	}

	if ( includeCurrent && currentFontVariation ) {
		// Avoid showing the current font variation twice, the current font variation is always the first item
		variations = variations.filter(
			( variation, index ) =>
				index === 0 || variation.title !== currentFontVariation.title
		);
	}

	return variations;
};

/**
 * FontPicker component
 * @param parameters                   - The parameters for the font picker
 * @param parameters.keywords          - The keywords to search for
 * @param parameters.fonts             - The fonts to search for
 * @param parameters.pairs             - The font pairs to use
 * @param parameters.includeCurrent    - Whether to include the current font
 * @param parameters.initialGeneration - Whether to generate the initial variations
 */
const FontPicker = ( parameters: FontPickerProps ): JSX.Element | null => {
	const [ variationsLocalState, setVariationsInLocalState ] = useState<
		FontVariation[]
	>( [] );
	const { getCurrentFont } = useSelect( ( select ) => select( aiStore ), [] );
	const { getFontVariationByTitle } = useVariations();
	const { pushGeneratedVariations } = useDispatch( aiStore );
	const { currentFont: currentFontMeta } =
		useSiteMetadata().getSiteMetadata();

	useEffect( () => {
		if ( ! parameters.themeVariations ) {
			// server did not send the variations, skipping parsing
			return;
		}
		const currentFont = getCurrentFont() || currentFontMeta;

		const args: ParseFontVariationsParams = {
			themeVariations: parameters.themeVariations,
			dynamicVariations: parameters.dynamicVariations || [],
			includeCurrent: true,
			currentFontVariation: getFontVariationByTitle( currentFont ),
			initialGeneration: false,
			pushGeneratedVariations,
		};

		setVariationsInLocalState( parseFontVariations( args ) );
	}, [
		currentFontMeta,
		getCurrentFont,
		getFontVariationByTitle,
		parameters,
		pushGeneratedVariations,
	] );

	if ( variationsLocalState.length === 0 ) {
		return null;
	}

	return (
		<FontVariationPicker
			fontVariations={ variationsLocalState }
			key="font-picker"
			maxFontsToShow={ MAX_VARIATIONS_TO_SHOW_PER_PAGE }
		/>
	);
};

export default memo( FontPicker );
