/**
 * External dependencies
 */
import classnames from 'classnames';

/**
 * WordPress dependencies
 */
import { useSelect } from '@wordpress/data';

import { store as coreStore } from '@wordpress/core-data';
import { store as aiStore } from '@store';
import { useEffect, useMemo, useState } from '@wordpress/element';
import { ENTER } from '@wordpress/keycodes';
import { __experimentalGrid as Grid } from '@wordpress/components';
import { __, sprintf } from '@wordpress/i18n';
import { recordTracksEvent } from '@utils/tracks';

/**
 * Internal dependencies
 */
import StylesPreview from '@components/styles-preview';
import useSiteMetadata from '@hooks/use-site-metadata';
import useStyles from '@hooks/use-styles';

export function Variation( { variation, type } ) {
	const { setStyles } = useStyles();
	const [ isFocused, setIsFocused ] = useState( false );

	const {
		currentColor: storeCurrentColor,
		currentFont: storeCurrentFont,
		currentButtonStyle: storeCurrentButtonStyle,
	} = useSelect( ( select ) => {
		const store = select( aiStore );
		return {
			currentColor: store.getCurrentColor(),
			currentFont: store.getCurrentFont(),
			currentButtonStyle: store.getCurrentButtonStyle(),
		};
	}, [] );

	const siteMetadata = useSiteMetadata().getSiteMetadata();

	// Use aiStore values with fallback to site metadata
	const currentColor = storeCurrentColor || siteMetadata.currentColor;
	const currentFont = storeCurrentFont || siteMetadata.currentFont;
	const currentButtonStyle =
		storeCurrentButtonStyle || siteMetadata.currentButtonStyle;

	const handleSelectVariation = () => {
		if ( type === 'color' ) {
			recordTracksEvent( 'color_variation_click', {
				color: variation.title,
			} );
			setStyles( { color: variation.title } );
		} else if ( type === 'button' ) {
			recordTracksEvent( 'button_variation_click', {
				button: variation.title,
			} );
			setStyles( { button: variation.title } );
		} else if ( type === 'font' ) {
			recordTracksEvent( 'font_variation_click', {
				font: variation.title,
			} );
			setStyles( { font: variation.title } );
		} else {
			// Log unexpected type to help with debugging
			console.warn( `Unexpected variation type: ${ type }` );
		}
	};

	const selectOnEnter = ( event ) => {
		if ( event.keyCode === ENTER ) {
			event.preventDefault();
			handleSelectVariation();
		}
	};

	const [ isActive, setIsActive ] = useState( false );
	useEffect( () => {
		let shouldActivate = false;
		if ( type === 'color' ) {
			shouldActivate = variation?.title === currentColor;
		} else if ( type === 'button' ) {
			shouldActivate = variation?.title === currentButtonStyle;
		} else if ( type === 'font' ) {
			shouldActivate = variation?.title === currentFont;
		}
		setIsActive( shouldActivate );
	}, [
		variation?.title,
		currentColor,
		currentButtonStyle,
		currentFont,
		type,
	] );

	let label = variation?.title;
	if ( variation?.description ) {
		label = sprintf(
			/* translators: %1$s: variation title. %2$s variation description. */
			__( '%1$s (%2$s)', 'big-sky' ),
			variation?.title,
			variation?.description
		);
	}

	return (
		<div
			className={ classnames( 'edit-site-global-styles-variations_item', {
				'is-active': isActive,
			} ) }
			role="button"
			onClick={ handleSelectVariation }
			onKeyDown={ selectOnEnter }
			tabIndex="0"
			aria-label={ label }
			aria-current={ isActive }
			onFocus={ () => setIsFocused( true ) }
			onBlur={ () => setIsFocused( false ) }
		>
			<div className="edit-site-global-styles-variations_item-preview">
				<StylesPreview
					label={ variation?.title }
					isFocused={ isFocused }
					type={ type }
					variation={ variation }
					className="big-sky__styles-preview"
				/>
			</div>
		</div>
	);
}

export function StyleVariationsContainer() {
	const variations = useSelect( ( select ) => {
		return select(
			coreStore
		).__experimentalGetCurrentThemeGlobalStylesVariations();
	}, [] );

	const withEmptyVariation = useMemo( () => {
		return [
			{
				title: __( 'Default', 'big-sky' ),
				settings: {},
				styles: {},
			},
			...( variations ?? [] ).map( ( variation ) => ( {
				...variation,
				settings: variation.settings ?? {},
				styles: variation.styles ?? {},
			} ) ),
		];
	}, [ variations ] );

	return (
		<Grid
			columns={ 2 }
			className="edit-site-global-styles-style-variations-container"
		>
			{ withEmptyVariation.map( ( variation, index ) => (
				<Variation key={ index } variation={ variation } />
			) ) }
		</Grid>
	);
}
