/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';

/**
 * External dependencies
 */
import type { Ability } from '@wordpress/abilities';
import { getAgentManager } from '@automattic/agenttic-client';

/**
 * Navigation state interface
 */
interface NavigateAbilityInput {
	path: string;
	toolCallId?: string;
	toolId?: string;
}

export interface NavigationState {
	destination: string;
	destinationPathname: string;
	timestamp: number;
	sessionId: string;
	toolCallId?: string;
	toolId?: string;
}

/**
 * Storage key for pending navigation
 */
const NAVIGATION_STORAGE_KEY = '_big_sky_pending_navigation';

/**
 * Navigation expiry time (5 minutes)
 */
const NAVIGATION_EXPIRY_MS = 5 * 60 * 1000;

/**
 * Get current session ID.
 *
 * @return Current session ID or empty string if none exists
 */
function getCurrentSessionId(): string {
	// Use AM's `getSessionId` when available (unified chat context)
	const amSessionId = (
		window as any
	 ).__agentsManagerActions?.getSessionId?.();
	if ( amSessionId ) {
		return amSessionId;
	}

	// Standalone Big Sky context
	try {
		const agentManager = getAgentManager();
		// The agent ID for the orchestrator (from src/ai/wp-orchestrator/index.tsx)
		// Must match AGENT_ID constant: 'wp-orchestrator'
		const agentKey = 'wp-orchestrator';

		if ( agentManager.hasAgent( agentKey ) ) {
			const agent = agentManager.getAgent( agentKey );
			return agent?.sessionId || '';
		}

		// Fallback to localStorage if agent doesn't exist yet
		// (e.g., on page load before agent is created)
		const stored = localStorage.getItem(
			'big-sky-orchestrator-session-id'
		);
		if ( stored ) {
			const session = JSON.parse( stored );
			return session.sessionId || '';
		}
	} catch ( error ) {
		console.error(
			'[Big Sky] Error retrieving session ID for navigation:',
			error
		);
	}
	return '';
}

/**
 * Store navigation state in localStorage
 * @param destination - The URL to navigate to
 * @param toolCallId  - The tool call ID from the navigate ability invocation
 * @param toolId      - The tool ID from the navigate ability invocation
 */
function storeNavigationState(
	destination: string,
	toolCallId?: string,
	toolId?: string
): void {
	const state: NavigationState = {
		destination,
		destinationPathname: destination.split( /[?#]/ )[ 0 ],
		timestamp: Date.now(),
		sessionId: getCurrentSessionId(),
		toolCallId,
		toolId,
	};
	localStorage.setItem( NAVIGATION_STORAGE_KEY, JSON.stringify( state ) );
}

/**
 * Retrieve and validate navigation state from localStorage
 * @return Navigation state if valid, null otherwise
 */
export function retrieveNavigationState(): NavigationState | null {
	try {
		const stored = localStorage.getItem( NAVIGATION_STORAGE_KEY );
		if ( ! stored ) {
			return null;
		}

		const state: NavigationState = JSON.parse( stored );

		// Check if navigation has expired
		if ( Date.now() - state.timestamp > NAVIGATION_EXPIRY_MS ) {
			localStorage.removeItem( NAVIGATION_STORAGE_KEY );
			return null;
		}

		return state;
	} catch ( error ) {
		console.error( '[Big Sky] Error retrieving navigation state:', error );
		return null;
	}
}

/**
 * Clear navigation state from localStorage
 */
export function clearNavigationState(): void {
	localStorage.removeItem( NAVIGATION_STORAGE_KEY );
}

/**
 * wp-admin/navigate ability
 *
 * Navigates to a different wp-admin page with full page reload support.
 * After navigation completes, automatically resumes the conversation.
 */
export const wpAdminNavigateAbility: Ability = {
	name: 'wp-admin/navigate',
	label: __( 'Navigate to wp-admin page', 'big-sky' ),
	category: 'big-sky',
	description: __(
		'Navigate the browser to a different wp-admin page. Use this when the user asks to go to a specific admin page (e.g., "go to plugins", "navigate to settings"). The page will reload, but the conversation will automatically continue after navigation completes.',
		'big-sky'
	),
	input_schema: {
		type: 'object',
		properties: {
			path: {
				type: 'string',
				description:
					'The wp-admin path to navigate to (e.g., "/wp-admin/plugins.php", "/wp-admin/options-general.php"). Must be a valid wp-admin path.',
			},
		},
		required: [ 'path' ],
	},
	callback: async ( input: NavigateAbilityInput ) => {
		const { path, toolCallId, toolId } = input;

		// Validate that path starts with /wp-admin/
		if ( ! path.startsWith( '/wp-admin/' ) ) {
			return {
				result: {
					success: false,
					error: 'Path must start with /wp-admin/',
				},
				returnToAgent: true,
			};
		}

		// Build destination URL, preserving unified-agent flag if present
		let destination = path;
		const currentParams = new URLSearchParams( window.location.search );
		if ( currentParams.get( 'flags' ) === 'unified-agent' ) {
			const destUrl = new URL( path, window.location.origin );
			destUrl.searchParams.set( 'flags', 'unified-agent' );
			destination = destUrl.pathname + destUrl.search;
		}

		storeNavigationState( destination, toolCallId, toolId );

		setTimeout( () => {
			window.location.href = destination;
		}, 1000 );

		return {
			result: {
				success: true,
				destination,
				instructions: `Navigating to ${ destination }. The page will reload the conversation will continue automatically. **Important**: Do not reply until you get the continuation message!`,
			},
			returnToAgent: false,
		};
	},
};
