/**
 * WordPress dependencies
 */
import { useCallback, useEffect, useRef } from '@wordpress/element';
import { useDispatch, useSelect } from '@wordpress/data';
import { store as blockEditorStore } from '@wordpress/block-editor';
import { store as aiStore } from '@store';

/**
 * Internal dependencies
 */
import { getCanvasIframeElements } from '@utils/canvas-iframe-elements';
import { recordTracksEvent } from '@utils/tracks';
import { buildAttrToUpdateImage } from '@utils/block-image';

// Hook to create drop zone handlers for a single block
function createBlockDropZoneHandlers( clientId, handlers ) {
	const { updateBlockAttributes } = handlers;
	const { setDraggedImageFile, setIsDraggingOver } = handlers;
	const { getDraggedImageFile } = handlers;
	const { getBlock } = handlers;

	// State management using refs to avoid React Hook rules
	const stateRef = {
		isDraggingOverDocument: false,
		isDraggingOverElement: false,
		isActive: false,
	};

	// Track drag enter/leave counts to handle nested elements properly
	const dragEnterCountRef = { current: 0 };
	const dragLeaveTimeoutRef = { current: null };

	const setState = ( updates ) => {
		Object.assign( stateRef, updates );
		// Trigger class update
		handlers.updateDropZoneClasses();
	};

	const clearDragState = () => {
		if ( dragLeaveTimeoutRef.current ) {
			clearTimeout( dragLeaveTimeoutRef.current );
			dragLeaveTimeoutRef.current = null;
		}
		dragEnterCountRef.current = 0;
		setState( {
			isDraggingOverElement: false,
			isDraggingOverDocument: false,
			isActive: false,
		} );
	};

	const handleDrop = ( event ) => {
		// Clear any pending timeout
		if ( dragLeaveTimeoutRef.current ) {
			clearTimeout( dragLeaveTimeoutRef.current );
			dragLeaveTimeoutRef.current = null;
		}

		const file = getDraggedImageFile();
		if ( ! file ) return;

		// Check if the actual drop target is an image block within this cover block
		const dropTarget = event.target.closest( '[data-type="core/image"]' );
		if (
			dropTarget &&
			dropTarget.closest( `[data-block="${ clientId }"]` )
		) {
			// The drop is actually on an image block within this cover block
			event.preventDefault();
			event.stopPropagation();

			const imageBlockClientId = dropTarget.getAttribute( 'data-block' );
			const attrToUpdate = buildAttrToUpdateImage(
				getBlock( imageBlockClientId ),
				file.url,
				file.alt || ''
			);

			// Update the image block attributes
			updateBlockAttributes( imageBlockClientId, attrToUpdate );

			// Track image drop and replace
			recordTracksEvent( 'image_dropped' );

			// Reset the dragged image file in the custom store
			setDraggedImageFile( null );
			setIsDraggingOver( false );

			// Clear drop zone classes after successful drop
			clearDragState();
			return;
		}

		// Prevent the default drop behavior
		event.preventDefault();
		event.stopPropagation();

		const attrToUpdate = buildAttrToUpdateImage(
			getBlock( clientId ),
			file.url,
			file.alt || ''
		);

		// Update the image block attributes
		updateBlockAttributes( clientId, attrToUpdate );

		// Track image drop and replace
		recordTracksEvent( 'image_dropped' );

		// Reset the dragged image file in the custom store
		setDraggedImageFile( null );
		setIsDraggingOver( false );

		// Clear drop zone classes after successful drop
		clearDragState();
	};

	const handleDragStart = () => {
		setState( { isDraggingOverDocument: true } );

		// Check if we have a dragged image file
		const file = getDraggedImageFile();
		setState( { isActive: !! file } );
	};

	const handleDragEnd = () => {
		// Clear any pending timeout
		if ( dragLeaveTimeoutRef.current ) {
			clearTimeout( dragLeaveTimeoutRef.current );
			dragLeaveTimeoutRef.current = null;
		}
		clearDragState();
	};

	const handleDragEnter = () => {
		// Clear any pending timeout
		if ( dragLeaveTimeoutRef.current ) {
			clearTimeout( dragLeaveTimeoutRef.current );
			dragLeaveTimeoutRef.current = null;
		}

		dragEnterCountRef.current++;

		// Check if we have a dragged image file
		const file = getDraggedImageFile();
		setState( {
			isDraggingOverElement: true,
			isDraggingOverDocument: true,
			isActive: !! file,
		} );
	};

	const handleDragLeave = () => {
		dragEnterCountRef.current--;

		// Only clear state if we've left the element completely (no more drag enters pending)
		if ( dragEnterCountRef.current <= 0 ) {
			// Use a short timeout to handle rapid enter/leave events
			dragLeaveTimeoutRef.current = setTimeout( () => {
				clearDragState();
				dragLeaveTimeoutRef.current = null;
			}, 50 );
		}
	};

	const handleDragOver = ( event ) => {
		// Prevent default to allow drop
		event.preventDefault();

		// Check if we have a dragged image file
		const file = getDraggedImageFile();
		setState( {
			isDraggingOverElement: true,
			isDraggingOverDocument: true,
			isActive: !! file,
		} );
	};

	return {
		onDrop: handleDrop,
		onDragStart: handleDragStart,
		onDragEnd: handleDragEnd,
		onDragEnter: handleDragEnter,
		onDragLeave: handleDragLeave,
		onDragOver: handleDragOver,
		getState: () => stateRef,
		clearDragState,
		cleanup: () => {
			if ( dragLeaveTimeoutRef.current ) {
				clearTimeout( dragLeaveTimeoutRef.current );
				dragLeaveTimeoutRef.current = null;
			}
		},
	};
}

export function useImageDrop() {
	const { updateBlockAttributes } = useDispatch( blockEditorStore );
	const { setDraggedImageFile, setIsDraggingOver } = useDispatch( aiStore );
	const { getDraggedImageFile, isEditorIframeLoaded } = useSelect(
		( select ) => {
			return {
				getDraggedImageFile: select( aiStore ).getDraggedImageFile,
				isEditorIframeLoaded:
					select( aiStore ).getIsEditorIframeLoaded(),
			};
		}
	);
	const { getBlock } = useSelect( blockEditorStore );

	// Use refs to store stable references to avoid dependency changes
	const observerRef = useRef( null );
	const blockDropZonesRef = useRef( new Map() );

	// Store stable references to avoid callback re-creation
	const handlersRef = useRef( {
		updateBlockAttributes,
		setDraggedImageFile,
		setIsDraggingOver,
		getDraggedImageFile,
		getBlock,
	} );

	// Function to update drop zone classes based on block states
	const updateDropZoneClasses = useCallback( () => {
		const file = getDraggedImageFile();
		if ( ! file ) return;

		const { canvasiFrameDocument } = getCanvasIframeElements();
		if ( ! canvasiFrameDocument ) return;

		// Then, apply classes based on block drop zone states
		// Collect all blocks with active states
		const activeBlocks = [];
		blockDropZonesRef.current.forEach( ( dropZone, clientId ) => {
			const block = canvasiFrameDocument.querySelector(
				`[data-block="${ clientId }"]`
			);
			if ( block ) {
				const state = dropZone.getState();
				if (
					state.isActive ||
					state.isDraggingOverElement ||
					state.isDraggingOverDocument
				) {
					activeBlocks.push( { clientId, block, dropZone, state } );
				}
			}
		} );

		// Cache the query for all drop zones
		const allDropZones = canvasiFrameDocument.querySelectorAll(
			'.components-drop-zone'
		);

		// If no active blocks, clear all drop zone classes
		if ( activeBlocks.length === 0 ) {
			allDropZones.forEach( ( dropZone ) => {
				dropZone.classList.remove(
					'is-active',
					'is-dragging-over-document',
					'is-dragging-over-element'
				);
			} );
			return;
		}

		// If only one active block, use it
		if ( activeBlocks.length === 1 ) {
			const block = activeBlocks[ 0 ];
			const dropZone = block.block.querySelector(
				'.components-drop-zone'
			);
			dropZone.classList.toggle( 'is-active', block.state.isActive );
			dropZone.classList.toggle(
				'is-dragging-over-document',
				block.state.isDraggingOverDocument
			);
			dropZone.classList.toggle(
				'is-dragging-over-element',
				block.state.isDraggingOverElement
			);
			return;
		}

		// If multiple active blocks, find the most specific (most nested) block
		let mostSpecificBlock = activeBlocks[ 0 ];
		for ( let i = 1; i < activeBlocks.length; i++ ) {
			const currentBlock = activeBlocks[ i ];

			// If the most specific block is contained within the current block, current block is more specific (parent)
			// If the current block is contained within the most specific block, most specific block stays (child is more specific)
			if (
				mostSpecificBlock.block.closest(
					`[data-block="${ currentBlock.clientId }"]`
				)
			) {
				// mostSpecificBlock is a child of currentBlock, so currentBlock is the parent (less specific)
				// Keep mostSpecificBlock as it's more specific (child)
			} else if (
				currentBlock.block.closest(
					`[data-block="${ mostSpecificBlock.clientId }"]`
				)
			) {
				// currentBlock is a child of mostSpecificBlock, so currentBlock is more specific
				mostSpecificBlock = currentBlock;
			}
			// If neither contains the other, they're unrelated - keep the first one
		}

		// Clear all drop zone classes first to ensure only the most specific block is active
		allDropZones.forEach( ( dropZone ) => {
			dropZone.classList.remove(
				'is-active',
				'is-dragging-over-document',
				'is-dragging-over-element'
			);
		} );

		// Apply classes only to the most specific block
		const dropZonesInBlock = mostSpecificBlock.block.querySelectorAll(
			'.components-drop-zone'
		);
		dropZonesInBlock.forEach( ( dropZoneElement ) => {
			dropZoneElement.classList.toggle(
				'is-active',
				mostSpecificBlock.state.isActive
			);
			dropZoneElement.classList.toggle(
				'is-dragging-over-document',
				mostSpecificBlock.state.isDraggingOverDocument
			);
			dropZoneElement.classList.toggle(
				'is-dragging-over-element',
				mostSpecificBlock.state.isDraggingOverElement
			);
		} );
	}, [ getDraggedImageFile ] );

	// Update refs when dependencies change
	useEffect( () => {
		handlersRef.current = {
			updateBlockAttributes,
			setDraggedImageFile,
			setIsDraggingOver,
			getDraggedImageFile,
			getBlock,
			updateDropZoneClasses,
		};
	}, [
		updateBlockAttributes,
		setDraggedImageFile,
		setIsDraggingOver,
		getDraggedImageFile,
		getBlock,
		updateDropZoneClasses,
	] );

	// Function to add drop listeners to image blocks
	const addDropListeners = ( doc ) => {
		// Find all blocks that should have drop zones
		const blocks = doc.querySelectorAll(
			'[data-type="core/image"], [data-type="core/media-text"], [data-type="core/cover"]'
		);

		// Track which blocks we've already processed
		const processedBlocks = new Set();

		blocks.forEach( ( block ) => {
			const clientId = block.getAttribute( 'data-block' );

			if ( ! clientId ) return;

			// Skip if already has a registered handler
			if ( blockDropZonesRef.current.has( clientId ) ) {
				processedBlocks.add( clientId );
				return;
			}

			// Create drop zone handlers for this block
			const dropZone = createBlockDropZoneHandlers(
				clientId,
				handlersRef.current
			);
			blockDropZonesRef.current.set( clientId, dropZone );

			block.setAttribute( 'data-has-drop-listener', 'true' );
			processedBlocks.add( clientId );
		} );

		// Clean up handlers for blocks that no longer exist
		const existingBlockIds = new Set();
		blocks.forEach( ( block ) => {
			const clientId = block.getAttribute( 'data-block' );
			if ( clientId ) {
				existingBlockIds.add( clientId );
			}
		} );

		// Remove handlers for blocks that no longer exist
		blockDropZonesRef.current.forEach( ( dropZone, clientId ) => {
			if ( ! existingBlockIds.has( clientId ) ) {
				dropZone.cleanup();
				blockDropZonesRef.current.delete( clientId );
			}
		} );

		// Add document-level event delegation listeners
		const handleDocumentDragEnter = ( event ) => {
			// Find all blocks that have registered drop zone handlers, starting from the target
			const allMatchingBlocks = [];
			let currentElement = event.target;

			while ( currentElement && currentElement !== event.currentTarget ) {
				if (
					currentElement.matches &&
					currentElement.matches( '[data-block]' )
				) {
					const clientId =
						currentElement.getAttribute( 'data-block' );
					if (
						clientId &&
						blockDropZonesRef.current.has( clientId )
					) {
						allMatchingBlocks.push( currentElement );
					}
				}
				currentElement = currentElement.parentElement;
			}

			// If no matching blocks found
			if ( allMatchingBlocks.length === 0 ) {
				return;
			}

			// Find the most specific (deepest) block
			const mostSpecificBlock = allMatchingBlocks[ 0 ]; // First one is the deepest

			// Check if there are any nested blocks within the most specific block that should take precedence
			// This handles the case where we're dragging over a nested image inside a cover block
			const mouseX = event.clientX;
			const mouseY = event.clientY;

			// Look for any nested blocks within the most specific block that have drop zone handlers
			const nestedBlocks =
				mostSpecificBlock.querySelectorAll( '[data-block]' );
			let bestNestedBlock = null;

			nestedBlocks.forEach( ( nestedBlock ) => {
				const nestedClientId = nestedBlock.getAttribute( 'data-block' );
				if (
					nestedClientId &&
					blockDropZonesRef.current.has( nestedClientId )
				) {
					const rect = nestedBlock.getBoundingClientRect();
					// Check if the mouse is within this nested block's bounds
					if (
						mouseX >= rect.left &&
						mouseX <= rect.right &&
						mouseY >= rect.top &&
						mouseY <= rect.bottom
					) {
						bestNestedBlock = nestedBlock;
					}
				}
			} );

			// Use the nested block if found, otherwise use the most specific block
			const targetBlock = bestNestedBlock || mostSpecificBlock;
			const targetClientId = targetBlock.getAttribute( 'data-block' );
			if ( ! targetClientId ) return;

			// Find the currently active block (if any)
			let currentlyActiveBlock = null;
			blockDropZonesRef.current.forEach( ( dropZone, clientId ) => {
				const state = dropZone.getState();
				if (
					state.isActive ||
					state.isDraggingOverElement ||
					state.isDraggingOverDocument
				) {
					currentlyActiveBlock = clientId;
				}
			} );

			// Only clear other blocks' states if we're switching to a different block
			if (
				currentlyActiveBlock &&
				currentlyActiveBlock !== targetClientId
			) {
				// Clear drag state from all other blocks that are not the target
				blockDropZonesRef.current.forEach( ( dropZone, clientId ) => {
					if ( clientId !== targetClientId ) {
						// Clear the drag state of this block
						dropZone.clearDragState();
					}
				} );
			}

			const dropZone = blockDropZonesRef.current.get( targetClientId );
			if ( dropZone ) {
				dropZone.onDragEnter( event );
			}
		};

		const handleDocumentDragLeave = ( event ) => {
			// Find all blocks that have registered drop zone handlers, starting from the target
			const allMatchingBlocks = [];
			let currentElement = event.target;

			while ( currentElement && currentElement !== event.currentTarget ) {
				if (
					currentElement.matches &&
					currentElement.matches( '[data-block]' )
				) {
					const clientId =
						currentElement.getAttribute( 'data-block' );
					if (
						clientId &&
						blockDropZonesRef.current.has( clientId )
					) {
						allMatchingBlocks.push( currentElement );
					}
				}
				currentElement = currentElement.parentElement;
			}

			if ( allMatchingBlocks.length === 0 ) return;

			// Find the most specific (deepest) block
			const mostSpecificBlock = allMatchingBlocks[ 0 ];

			// Check if there are any nested blocks within the most specific block that should take precedence
			const mouseX = event.clientX;
			const mouseY = event.clientY;

			// Look for any nested blocks within the most specific block that have drop zone handlers
			const nestedBlocks =
				mostSpecificBlock.querySelectorAll( '[data-block]' );
			let bestNestedBlock = null;

			nestedBlocks.forEach( ( nestedBlock ) => {
				const nestedClientId = nestedBlock.getAttribute( 'data-block' );
				if (
					nestedClientId &&
					blockDropZonesRef.current.has( nestedClientId )
				) {
					const rect = nestedBlock.getBoundingClientRect();
					// Check if the mouse is within this nested block's bounds
					if (
						mouseX >= rect.left &&
						mouseX <= rect.right &&
						mouseY >= rect.top &&
						mouseY <= rect.bottom
					) {
						bestNestedBlock = nestedBlock;
					}
				}
			} );

			// Use the nested block if found, otherwise use the most specific block
			const targetBlock = bestNestedBlock || mostSpecificBlock;
			const clientId = targetBlock.getAttribute( 'data-block' );
			if ( ! clientId ) return;

			const dropZone = blockDropZonesRef.current.get( clientId );
			if ( dropZone ) {
				dropZone.onDragLeave( event );
			}
		};

		const handleDocumentDragOver = ( event ) => {
			// Find all blocks that have registered drop zone handlers, starting from the target
			const allMatchingBlocks = [];
			let currentElement = event.target;

			while ( currentElement && currentElement !== event.currentTarget ) {
				if (
					currentElement.matches &&
					currentElement.matches( '[data-block]' )
				) {
					const clientId =
						currentElement.getAttribute( 'data-block' );
					if (
						clientId &&
						blockDropZonesRef.current.has( clientId )
					) {
						allMatchingBlocks.push( currentElement );
					}
				}
				currentElement = currentElement.parentElement;
			}

			if ( allMatchingBlocks.length === 0 ) return;

			// Find the most specific (deepest) block
			const mostSpecificBlock = allMatchingBlocks[ 0 ];

			// Check if there are any nested blocks within the most specific block that should take precedence
			const mouseX = event.clientX;
			const mouseY = event.clientY;

			// Look for any nested blocks within the most specific block that have drop zone handlers
			const nestedBlocks =
				mostSpecificBlock.querySelectorAll( '[data-block]' );
			let bestNestedBlock = null;

			nestedBlocks.forEach( ( nestedBlock ) => {
				const nestedClientId = nestedBlock.getAttribute( 'data-block' );
				if (
					nestedClientId &&
					blockDropZonesRef.current.has( nestedClientId )
				) {
					const rect = nestedBlock.getBoundingClientRect();
					// Check if the mouse is within this nested block's bounds
					if (
						mouseX >= rect.left &&
						mouseX <= rect.right &&
						mouseY >= rect.top &&
						mouseY <= rect.bottom
					) {
						bestNestedBlock = nestedBlock;
					}
				}
			} );

			// Use the nested block if found, otherwise use the most specific block
			const targetBlock = bestNestedBlock || mostSpecificBlock;
			const clientId = targetBlock.getAttribute( 'data-block' );
			if ( ! clientId ) return;

			const dropZone = blockDropZonesRef.current.get( clientId );
			if ( dropZone ) {
				dropZone.onDragOver( event );
			}
		};

		const handleDocumentDrop = ( event ) => {
			// Find all blocks that have registered drop zone handlers, starting from the target
			const allMatchingBlocks = [];
			let currentElement = event.target;

			while ( currentElement && currentElement !== event.currentTarget ) {
				if (
					currentElement.matches &&
					currentElement.matches( '[data-block]' )
				) {
					const clientId =
						currentElement.getAttribute( 'data-block' );
					if (
						clientId &&
						blockDropZonesRef.current.has( clientId )
					) {
						allMatchingBlocks.push( currentElement );
					}
				}
				currentElement = currentElement.parentElement;
			}

			if ( allMatchingBlocks.length === 0 ) return;

			// Find the most specific (deepest) block
			const mostSpecificBlock = allMatchingBlocks[ 0 ];

			// Check if there are any nested blocks within the most specific block that should take precedence
			const mouseX = event.clientX;
			const mouseY = event.clientY;

			// Look for any nested blocks within the most specific block that have drop zone handlers
			const nestedBlocks =
				mostSpecificBlock.querySelectorAll( '[data-block]' );
			let bestNestedBlock = null;

			nestedBlocks.forEach( ( nestedBlock ) => {
				const nestedClientId = nestedBlock.getAttribute( 'data-block' );
				if (
					nestedClientId &&
					blockDropZonesRef.current.has( nestedClientId )
				) {
					const rect = nestedBlock.getBoundingClientRect();
					// Check if the mouse is within this nested block's bounds
					if (
						mouseX >= rect.left &&
						mouseX <= rect.right &&
						mouseY >= rect.top &&
						mouseY <= rect.bottom
					) {
						bestNestedBlock = nestedBlock;
					}
				}
			} );

			// Use the nested block if found, otherwise use the most specific block
			const targetBlock = bestNestedBlock || mostSpecificBlock;
			const clientId = targetBlock.getAttribute( 'data-block' );
			if ( ! clientId ) return;

			const dropZone = blockDropZonesRef.current.get( clientId );
			if ( dropZone ) {
				dropZone.onDrop( event );
			}
		};

		// Add document-level listeners
		doc.addEventListener( 'dragenter', handleDocumentDragEnter );
		doc.addEventListener( 'dragleave', handleDocumentDragLeave );
		doc.addEventListener( 'dragover', handleDocumentDragOver );
		doc.addEventListener( 'drop', handleDocumentDrop );

		// Store the handlers for cleanup
		doc._bigSkyDragHandlers = {
			dragenter: handleDocumentDragEnter,
			dragleave: handleDocumentDragLeave,
			dragover: handleDocumentDragOver,
			drop: handleDocumentDrop,
		};
	};

	// Function to remove drop listeners
	const removeDropListeners = ( doc ) => {
		// Remove document-level listeners
		if ( doc._bigSkyDragHandlers ) {
			doc.removeEventListener(
				'dragenter',
				doc._bigSkyDragHandlers.dragenter
			);
			doc.removeEventListener(
				'dragleave',
				doc._bigSkyDragHandlers.dragleave
			);
			doc.removeEventListener(
				'dragover',
				doc._bigSkyDragHandlers.dragover
			);
			doc.removeEventListener( 'drop', doc._bigSkyDragHandlers.drop );
			delete doc._bigSkyDragHandlers;
		}

		// Clean up all dropzone timeouts
		blockDropZonesRef.current.forEach( ( dropZone ) => {
			dropZone.cleanup();
		} );

		// Clear the block drop zones map
		blockDropZonesRef.current.clear();

		// Remove data attributes from blocks that have registered drop zone handlers
		blockDropZonesRef.current.forEach( ( dropZone, clientId ) => {
			const block = doc.querySelector( `[data-block="${ clientId }"]` );
			if ( block ) {
				block.removeAttribute( 'data-has-drop-listener' );
			}
		} );
	};

	useEffect( () => {
		if ( ! isEditorIframeLoaded ) {
			return;
		}

		// Capture ref values to avoid React warnings in cleanup
		const blockDropZones = blockDropZonesRef.current;

		// Get the editor iframe
		const { canvasiFrameDocument } = getCanvasIframeElements();
		if ( ! canvasiFrameDocument ) {
			console.error( 'Could not find editor iframe' );
			return;
		}

		// Add initial listeners
		addDropListeners( canvasiFrameDocument );

		// Set up mutation observer to watch for new blocks
		// Use a debounced approach to avoid excessive calls
		let timeoutId = null;

		const debouncedAddListeners = () => {
			if ( timeoutId ) {
				clearTimeout( timeoutId );
			}
			timeoutId = setTimeout( () => {
				addDropListeners( canvasiFrameDocument );
			}, 250 ); // Increased from 100ms to 250ms
		};

		observerRef.current = new window.MutationObserver( ( mutations ) => {
			let hasRelevantChanges = false;

			mutations.forEach( ( mutation ) => {
				// Only trigger for added nodes that might be blocks
				if ( mutation.addedNodes.length ) {
					for ( let i = 0; i < mutation.addedNodes.length; i++ ) {
						const node = mutation.addedNodes[ i ];
						// Only care about element nodes
						if ( node.nodeType === 1 ) {
							// 1 = ELEMENT_NODE
							// Check if this node or its descendants might be blocks we care about
							if (
								node.matches &&
								( node.matches(
									'[data-type="core/image"], [data-type="core/media-text"], [data-type="core/cover"]'
								) ||
									node.querySelector(
										'[data-type="core/image"], [data-type="core/media-text"], [data-type="core/cover"]'
									) )
							) {
								hasRelevantChanges = true;
								break;
							}
						}
					}
				}

				// Also check for removed nodes to clean up handlers
				if ( mutation.removedNodes.length ) {
					for ( let i = 0; i < mutation.removedNodes.length; i++ ) {
						const node = mutation.removedNodes[ i ];
						if ( node.nodeType === 1 ) {
							// 1 = ELEMENT_NODE
							if (
								node.matches &&
								( node.matches(
									'[data-type="core/image"], [data-type="core/media-text"], [data-type="core/cover"]'
								) ||
									node.querySelector(
										'[data-type="core/image"], [data-type="core/media-text"], [data-type="core/cover"]'
									) )
							) {
								hasRelevantChanges = true;
								break;
							}
						}
					}
				}
			} );

			if ( hasRelevantChanges ) {
				debouncedAddListeners();
			}
		} );

		// Start observing the document with the configured parameters
		observerRef.current.observe( canvasiFrameDocument.body, {
			childList: true,
			subtree: true,
		} );

		// Cleanup listeners when the component is unmounted
		return () => {
			if ( timeoutId ) {
				clearTimeout( timeoutId );
			}

			if ( observerRef.current ) {
				observerRef.current.disconnect();
				observerRef.current = null;
			}

			// Clean up all dropzone timeouts using captured value
			blockDropZones.forEach( ( dropZone ) => {
				dropZone.cleanup();
			} );

			if ( canvasiFrameDocument ) {
				removeDropListeners( canvasiFrameDocument );
			}

			// Clear the block drop zones map using captured value
			blockDropZones.clear();
		};
	}, [ isEditorIframeLoaded ] );

	// Effect to update drop zone classes when block states change
	useEffect( () => {
		updateDropZoneClasses();
	}, [ updateDropZoneClasses ] );
}
