/**
 * WordPress dependencies
 */
import { useDispatch } from '@wordpress/data';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import log from '@utils/log-debug.js';
import { INTERNAL_VISION_MODELS } from '@utils/constants';

export default function useAnalyzeImage() {
	const { runChatCompletion } = useDispatch( aiStore );

	const analyzeImage = async ( { imageBase64, mimeType } ) => {
		const languagePrompt =
			typeof window !== 'undefined' &&
			window.bigSkyInitialState?.userLanguage
				? window.bigSkyInitialState.userLanguage
				: 'English (United States)';

		const messages = [
			{
				role: 'user',
				content: [
					{
						type: 'text',
						text: `Define the alt text for the image.
- Keep it concise. No more than 100 characters.
- Return ONLY the alt text with no preamble.

Here is the language you should use for responses unless explicitly instructed otherwise:

<language>
${ languagePrompt }
</language>`,
					},
					{
						type: 'image_url',
						image_url: {
							url: `data:${ mimeType };base64,${ imageBase64 }`,
						},
					},
				],
			},
		];

		try {
			const response = await runChatCompletion(
				INTERNAL_VISION_MODELS.LLAMA3_11B,
				messages
			);
			const content = response?.choices?.[ 0 ]?.message?.content;

			if ( ! content ) {
				log.error( 'No content in model response for image analysis.' );
				return null;
			}

			return content;
		} catch ( error ) {
			log.error( 'Error analyzing image:', error );
			return null;
		}
	};

	return {
		analyzeImage,
	};
}
