/**
 * WordPress dependencies
 */
import { useSelect } from '@wordpress/data';
import { Button } from '@wordpress/components';
import {
	memo,
	useCallback,
	useEffect,
	useMemo,
	useState,
} from '@wordpress/element';
import { store as blockEditorStore } from '@wordpress/block-editor';
import { chevronLeft, chevronRight } from '@wordpress/icons';
import useEmblaCarousel from 'embla-carousel-react';
import { __ } from '@wordpress/i18n';
import { addAction, removeAction } from '@wordpress/hooks';

/**
 * Internal dependencies
 */
import './style.scss';
import ItemPreview from '@components/item-preview';
import { getCanvasIframeElements } from '@utils/canvas-iframe-elements';
import { AskAI } from '@components/icons';
import useBlocks from '@hooks/use-blocks';
import { recordTracksEvent } from '@utils/tracks';
import {
	isTemplatePartPatternSlug,
	TemplatePartPatternSlug,
	TemplatePartSlug,
} from '@utils/template-parts';

const ItemPicker = ( {
	items,
	clientId,
	generateNewItem,
	initialRenderedItems = {},
	isFullLayout = false,
	isHeroPattern = false,
} ) => {
	const [ emblaRef, emblaApi ] = useEmblaCarousel(
		{
			axis: 'x',
			align: 'start',
			containScroll: 'trimSnaps',
			dragFree: false,
			watchDrag: false,
			slidesToScroll: 1,
		},
		[]
	);
	const [ canScrollPrev, setCanScrollPrev ] = useState( false );
	const [ canScrollNext, setCanScrollNext ] = useState( false );
	const [ isScrolling, setIsScrolling ] = useState( false );
	const [ allItemsRendered, setAllItemsRendered ] = useState( false );
	const [ replaceId, setReplaceId ] = useState( clientId );
	const [ renderedItems, setRenderedItems ] =
		useState( initialRenderedItems );
	const [ selectedIndex, setSelectedIndex ] = useState( null );
	const { getTemplatePartClientID } = useBlocks();
	const { getBlocks } = useSelect( blockEditorStore );

	const getAdditionalStyles = useMemo( () => {
		const { canvasiFrameRoot } = getCanvasIframeElements();
		// When switching to a newly generated page, the iframe is sometimes not
		// available early enough when rendering the item picker.
		if ( ! canvasiFrameRoot ) {
			return [];
		}

		const canvasiFrameStyle = window.getComputedStyle( canvasiFrameRoot );
		const stylePropertiesToCopy = [
			'--site-logo-url',
			'--site-logo-object-position',
		];

		const styleProperties = stylePropertiesToCopy.map(
			( styleProperty ) =>
				`${ styleProperty }: ${
					canvasiFrameStyle.getPropertyValue( styleProperty ) || ' '
				};`
		);

		return [
			{
				css: `html { ${ styleProperties.join( ' ' ) } }`,
			},
		];
	}, [] );

	const layoutConfig = useMemo( () => {
		const categories = new Set(
			items.map( ( item ) => item?.patterns?.[ 0 ]?.category )
		);
		let cols = 3;
		let clsName = 'big-sky__layout-variations';
		let vpWidthMax = 1400;

		if ( categories.size === 1 ) {
			const category = [ ...categories.values() ][ 0 ];

			if ( isTemplatePartPatternSlug( category ) ) {
				// Widen the preview by switching from 3 to two columns.
				cols = 2;
				clsName += ' big-sky__layout-variations-wider';
				// "Zoom in" more by making the iframe's viewport narrower.
				vpWidthMax =
					TemplatePartPatternSlug.Header === category ? 700 : 1000;
			}
		}

		return {
			columns: cols,
			className: clsName,
			viewportWidthMax: vpWidthMax,
		};
	}, [ items ] );

	const scrollPrev = useCallback( () => {
		if ( emblaApi && ! isScrolling ) {
			recordTracksEvent( 'item_picker_scroll_prev' );
			setIsScrolling( true );
			emblaApi.scrollPrev();
			const newIndex = emblaApi.selectedScrollSnap();
			setSelectedIndex( newIndex );
		}
	}, [ emblaApi, isScrolling ] );

	const scrollNext = useCallback( () => {
		if ( emblaApi && ! isScrolling ) {
			recordTracksEvent( 'item_picker_scroll_next' );
			setIsScrolling( true );
			emblaApi.scrollNext();
			const newIndex = emblaApi.selectedScrollSnap();
			setSelectedIndex( newIndex );
		}
	}, [ emblaApi, isScrolling ] );

	const onSelect = useCallback( () => {
		if ( ! emblaApi ) return;
		setCanScrollPrev( emblaApi.canScrollPrev() );
		setCanScrollNext( emblaApi.canScrollNext() );
	}, [ emblaApi ] );

	useEffect( () => {
		if ( ! emblaApi ) return;
		onSelect();
		emblaApi.on( 'select', onSelect );
		emblaApi.on( 'reInit', onSelect );
		return () => {
			emblaApi.off( 'select', onSelect );
			emblaApi.off( 'reInit', onSelect );
		};
	}, [ emblaApi, onSelect ] );

	useEffect( () => {
		if ( ! emblaApi ) return;

		const onSettle = () => {
			setIsScrolling( false );
		};

		emblaApi.on( 'settle', onSettle );
		return () => {
			emblaApi.off( 'settle', onSettle );
		};
	}, [ emblaApi ] );

	useEffect( () => {
		const allRendered = items.every( ( item ) => renderedItems[ item.id ] );
		setAllItemsRendered( allRendered );
	}, [ items, renderedItems ] );

	const handleItemRendered = useCallback( ( itemId ) => {
		setRenderedItems( ( prev ) => ( { ...prev, [ itemId ]: true } ) );
	}, [] );

	const generateNewItemClickHandler = useCallback( () => {
		recordTracksEvent( 'item_picker_generate_new_item_click' );
		generateNewItem();
	}, [ generateNewItem ] );

	const handleAfterClick = useCallback( ( id, index ) => {
		setReplaceId( id );
		setSelectedIndex( index );
	}, [] );

	const filteredItems = useMemo( () => {
		return (
			items?.filter(
				( item ) => ! item.isPlaceholder && item.patterns?.length > 0
			) || []
		);
	}, [ items ] );

	// Listen for checkpoint restoration to update clientId
	useEffect( () => {
		const handleCheckpointRestore = () => {
			// Handle checkpoint restoration
			if ( isHeroPattern ) {
				// If the pattern is a hero pattern, the client ID of the cover block within the hero template part changes
				// We need to find the client ID of the cover block and set it as the replace ID.
				const headerHero = getBlocks(
					getTemplatePartClientID( TemplatePartSlug.HeaderHero )
				);
				setReplaceId( headerHero[ 0 ]?.clientId );
			} else {
				// If the pattern is not a hero pattern, we need to set the replace ID to the client ID of the item picker.
				setReplaceId( clientId );
			}
		};

		// Remove any existing handlers first, then add the new one
		removeAction( 'big-sky.checkpoint-restored', 'item-picker-handler' );
		addAction(
			'big-sky.checkpoint-restored',
			'item-picker-handler',
			handleCheckpointRestore
		);

		return () => {
			// Clean up when component unmounts
			removeAction(
				'big-sky.checkpoint-restored',
				'item-picker-handler'
			);
		};
	}, [ clientId, getBlocks, getTemplatePartClientID, isHeroPattern ] );

	return (
		<div className="big-sky__item-picker">
			<div className="embla" ref={ emblaRef }>
				<div
					className={ `embla__container ${ layoutConfig.className }` }
				>
					{ filteredItems.map( ( item, index ) => (
						<div key={ item.id } className="embla__slide">
							<ItemPreview
								index={ index }
								item={ item }
								additionalStyles={ getAdditionalStyles }
								viewportWidthMax={
									layoutConfig.viewportWidthMax
								}
								clientId={ replaceId }
								onRendered={ () =>
									handleItemRendered( item.id )
								}
								onAfterClick={ handleAfterClick }
								isFullLayout={ isFullLayout }
								isSelected={ selectedIndex === index }
							/>
						</div>
					) ) }
					{ generateNewItem && allItemsRendered && (
						<div
							key="generate-new-item"
							className="embla__slide embla__slide--generate-new-item"
						>
							<Button
								onClick={ generateNewItemClickHandler }
								label={ __( 'Generate another', 'big-sky' ) }
							>
								<AskAI />
								{ __( 'Generate another', 'big-sky' ) }
							</Button>
						</div>
					) }
				</div>
			</div>
			<div className="big-sky__item-picker__arrows">
				<Button
					icon={ chevronLeft }
					onClick={ scrollPrev }
					disabled={ ! canScrollPrev || isScrolling }
					size="compact"
				/>
				<div className="big-sky__item-picker__pager">
					{ selectedIndex + 1 }/
					{ filteredItems.length +
						( generateNewItem && allItemsRendered && isFullLayout
							? 1
							: 0 ) }
				</div>
				<Button
					icon={ chevronRight }
					onClick={ scrollNext }
					disabled={ ! canScrollNext || isScrolling }
					size="compact"
				/>
			</div>
		</div>
	);
};

export default memo( ItemPicker );
