/**
 * Types
 */
interface BlockAttributes {
	className?: string;
	url?: string;
	alt?: string;
	id?: number;
	[ key: string ]: unknown;
}

interface BlockData {
	name: string;
	clientId?: string;
	attributes?: BlockAttributes;
	innerBlocks?: BlockData[];
}

interface BlockUpdate extends BlockData {
	clientId: string;
}

interface BlockInsert {
	parentClientId?: string;
	index?: number;
	block: BlockData;
}

type BlockDelete = string;

interface EditResults {
	updates?: BlockUpdate[];
	inserts?: BlockInsert[];
	deletes?: BlockDelete[];
	summary?: string;
}

interface ApplyBlockEditsArgs {
	updates?: BlockUpdate[];
	inserts?: BlockInsert[];
	deletes?: BlockDelete[];
	summary?: string;
	followUpTasks?: boolean;
	reverseMap?: ClientIdMap;
	messageId: string;
	suppressAssistantMessage?: boolean;
	resetBlockProcessingStates?: boolean;
	customCSS?: string;
}

interface BlockType {
	name: string;
	[ key: string ]: unknown;
}

interface Block {
	clientId: string;
	name: string;
	attributes?: BlockAttributes;
	innerBlocks?: Block[];
}

interface BlockDifference {
	from: unknown;
	to: unknown;
}

interface ModifiedBlock {
	clientId: string;
	name: string;
	changes: Record< string, BlockDifference | Record< string, unknown > >;
}

interface BlockStateComparison {
	added: Array< {
		clientId: string;
		name: string;
		attributes?: BlockAttributes;
		innerBlocks: number;
	} >;
	removed: Array< {
		clientId: string;
		name: string;
		attributes?: BlockAttributes;
		innerBlocks: number;
	} >;
	modified: ModifiedBlock[];
}

interface EditorState {
	blocks: any;
}

interface ClientIdMap {
	[ key: string ]: string;
}

interface CachedImage {
	url: string;
	id?: number;
	alt?: string;
}

/**
 * Validates the edit results structure
 *
 * @param {EditResults} results         The edit results to validate
 * @param {string[]}    availableBlocks The available blocks
 * @throws {Error} If the results are invalid
 */
const validateEditResults = (
	results: EditResults,
	availableBlocks: string[]
): void => {
	if (
		! results.updates &&
		! results.inserts &&
		! results.deletes &&
		! results.summary
	) {
		throw new Error(
			'Response must contain either updates, insertions, or deletions, or a summary message'
		);
	}

	/**
	 * Recursively validates that all blocks have valid names
	 *
	 * @param {BlockData} block The block to validate
	 * @throws {Error} If the block name is invalid
	 */
	const validateBlockName = ( block: BlockData ): void => {
		if ( ! block.name && ! block.clientId ) {
			throw new Error( 'Block must have a name property' );
		}

		if ( ! availableBlocks.includes( block.name ) && ! block.clientId ) {
			throw new Error( `Block type "${ block.name }" is not available` );
		}

		// Recursively validate inner blocks
		if ( block.innerBlocks ) {
			for ( const innerBlock of block.innerBlocks ) {
				validateBlockName( innerBlock );
			}
		}
	};

	// filter out null entries from updates, inserts, and deletes
	// unsure why the model is returning null entries in the first place, check BSKY-950
	results.updates = results?.updates?.filter( Boolean ) || [];
	results.inserts = results?.inserts?.filter( Boolean ) || [];
	results.deletes = results?.deletes?.filter( Boolean ) || [];

	// Transform deletes from objects to strings if needed
	// Handles cases where the model returns deletes like this:
	// {
	// 	"deletes": [
	// 		{ "clientId": "block-123" }
	// 	]
	// }
	if ( results.deletes && Array.isArray( results.deletes ) ) {
		results.deletes = results.deletes
			.map( ( item ) =>
				typeof item === 'string' ? item : ( item as any )?.clientId
			)
			.filter( Boolean ) as string[];
	}

	// Validate updates
	if ( results.updates ) {
		for ( const update of results.updates ) {
			if ( ! update.clientId || ! update.name ) {
				throw new Error( 'Updates must contain clientId and name' );
			}
			validateBlockName( update );
		}
	}

	// Validate insertions
	if ( results.inserts ) {
		for ( const insert of results.inserts ) {
			if ( ! insert.block?.name ) {
				throw new Error(
					'Insertions must contain block data with a name'
				);
			}
			validateBlockName( insert.block );
		}
	}

	// Validate deletions
	if ( results.deletes ) {
		if ( ! Array.isArray( results.deletes ) ) {
			throw new Error( 'Deletions must be an array of clientIds' );
		}

		for ( const clientId of results.deletes ) {
			if ( typeof clientId !== 'string' ) {
				throw new Error( 'Each deletion must be a clientId string' );
			}
		}
	}
};

/**
 * Compares two block states and returns the differences
 *
 * @param {Block[]} lastState    The previous state of blocks
 * @param {Block[]} currentState The current state of blocks
 * @return {BlockStateComparison} Object containing detailed differences
 */
const compareBlockStates = (
	lastState: any,
	currentState: any
): BlockStateComparison => {
	// Helper function to flatten blocks from all sections
	const flattenBlocks = ( state: any ): Block[] => {
		const blocks: Block[] = [];
		if ( state.headerBlocks ) blocks.push( ...state.headerBlocks );
		if ( state.footerBlocks ) blocks.push( ...state.footerBlocks );
		if ( state.contentBlocks ) blocks.push( ...state.contentBlocks );
		return blocks;
	};

	// Helper function to find differences between two objects
	const findDifferences = (
		obj1: any,
		obj2: any,
		path = ''
	): Record< string, BlockDifference | Record< string, unknown > > => {
		const differences: Record<
			string,
			BlockDifference | Record< string, unknown >
		> = {};

		// Get all unique keys from both objects
		const allKeys = new Set( [
			...Object.keys( obj1 ),
			...Object.keys( obj2 ),
		] );

		for ( const key of Array.from( allKeys ) ) {
			const currentPath = path ? `${ path }.${ key }` : key;

			// If key exists in both objects
			if ( key in obj1 && key in obj2 ) {
				// If both values are objects (and not null), recursively compare them
				if (
					typeof obj1[ key ] === 'object' &&
					obj1[ key ] !== null &&
					typeof obj2[ key ] === 'object' &&
					obj2[ key ] !== null
				) {
					const nestedDifferences = findDifferences(
						obj1[ key ],
						obj2[ key ],
						currentPath
					);
					if ( Object.keys( nestedDifferences ).length > 0 ) {
						differences[ key ] = nestedDifferences;
					}
				}
				// If values are different, store both values
				else if (
					JSON.stringify( obj1[ key ] ) !==
					JSON.stringify( obj2[ key ] )
				) {
					differences[ key ] = {
						from: obj1[ key ],
						to: obj2[ key ],
					};
				}
			}
			// If key only exists in first object
			else if ( key in obj1 ) {
				differences[ key ] = {
					from: obj1[ key ],
					to: undefined,
				};
			}
			// If key only exists in second object
			else if ( key in obj2 ) {
				differences[ key ] = {
					from: undefined,
					to: obj2[ key ],
				};
			}
		}

		return differences;
	};

	const lastBlocks = flattenBlocks( lastState );
	const currentBlocks = flattenBlocks( currentState );

	// Find added and removed blocks
	const added = currentBlocks.filter(
		( block ) =>
			! lastBlocks.some(
				( lastBlock ) => lastBlock.clientId === block.clientId
			)
	);

	const removed = lastBlocks.filter(
		( block ) =>
			! currentBlocks.some(
				( currentBlock ) => currentBlock.clientId === block.clientId
			)
	);

	// Find modified blocks and their specific changes
	const modified: ModifiedBlock[] = [];
	currentBlocks.forEach( ( currentBlock ) => {
		const lastBlock = lastBlocks.find(
			( block ) => block.clientId === currentBlock.clientId
		);

		if ( lastBlock ) {
			const differences = findDifferences( lastBlock, currentBlock );
			if ( Object.keys( differences ).length > 0 ) {
				modified.push( {
					clientId: currentBlock.clientId,
					name: currentBlock.name,
					changes: differences,
				} );
			}
		}
	} );

	return {
		added: added.map( ( block ) => ( {
			clientId: block.clientId,
			name: block.name,
			attributes: block.attributes,
			innerBlocks: block.innerBlocks?.length || 0,
		} ) ),
		removed: removed.map( ( block ) => ( {
			clientId: block.clientId,
			name: block.name,
			attributes: block.attributes,
			innerBlocks: block.innerBlocks?.length || 0,
		} ) ),
		modified,
	};
};

/**
 * Hook that provides block editing functionality.
 */
export default function useApplyBlockEditsTool(): {
	applyBlockEdits: ( args: ApplyBlockEditsArgs ) => Promise< {
		result: string;
		returnToAgent: boolean;
		agentMessage?: string;
	} >;
} {
	const { setCheckpoint, addCheckpointKeys } = useCheckpoint();

	// Get clientIdMap from store (instead of it being injected via args)
	const clientIdMap = useSelect(
		( select ) =>
			select( aiStore ).getFullPageStructure()?.clientIdMap || {},
		[]
	) as ClientIdMap;

	// Get available blocks
	const blockTypes = useSelect(
		( select ) => ( select( blocksStore ) as any ).getBlockTypes(),
		[]
	) as BlockType[] | undefined;

	const availableBlocks = useMemo(
		() =>
			Array.isArray( blockTypes )
				? blockTypes.map( ( block ) => block.name )
				: [],
		[ blockTypes ]
	);

	const {
		getBlock,
		getBlockParents,
		getGlobalStylesId,
		getEditedEntityRecord,
	} = useSelect(
		( select ) => ( {
			getBlock: ( select( blockEditorStore ) as any ).getBlock,
			getBlockParents: ( select( blockEditorStore ) as any )
				.getBlockParents,
			getGlobalStylesId: () =>
				(
					select( coreStore ) as any
				 ).__experimentalGetCurrentGlobalStylesId(),
			getEditedEntityRecord: ( select( coreStore ) as any )
				.getEditedEntityRecord,
		} ),
		[]
	) as {
		getBlock: ( clientId: string ) => Block | null;
		getBlockParents: ( clientId: string ) => string[];
		getGlobalStylesId: () => string;
		getEditedEntityRecord: (
			kind: string,
			name: string,
			recordId: string
		) => any;
	};

	const {
		setBlockIsProcessing,
		getRootBlocksState,
		getSectionRootClientId,
		resetAllBlockIsProcessing,
	} = useBlocks();
	const {
		deleteMarkedMessages,
		assistantSay,
		addAssistantMessage,
		changeCheckpointId,
		addCachedImage,
	} = useDispatch( aiStore ) as {
		deleteMarkedMessages: () => void;
		assistantSay: (
			message: string
		) => Promise< { message: { id: string } } >;
		addAssistantMessage: ( assistant: string, message: string ) => void;
		changeCheckpointId: ( oldId: string, newId: string ) => void;
		addCachedImage: ( args: {
			cacheKey: string;
			imageData: CachedImage;
		} ) => void;
	};

	const { replaceBlock, insertBlock, removeBlock, updateBlockAttributes } =
		useDispatch( blockEditorStore );
	const { editEntityRecord } = useDispatch( coreStore );
	const { getLastEditorState } = useCheckpoint();

	const aiPromises: Promise< void >[] = [];

	/**
	 * Deep merge utility that recursively merges objects while preserving nested properties
	 *
	 * @param {any} target The target object to merge into
	 * @param {any} source The source object to merge from
	 * @return {any} The deeply merged result
	 */
	const deepMerge = ( target: any, source: any ): any => {
		// Handle undefined case - keep target
		if ( source === undefined ) {
			return target;
		}
		// Handle null case - explicitly set to null (don't preserve target)
		if ( source === null ) {
			return null;
		}
		if ( target === null || target === undefined ) {
			return source;
		}

		// If source is not an object, replace target entirely
		if ( typeof source !== 'object' || Array.isArray( source ) ) {
			return source;
		}

		// If target is not an object, replace with source
		if ( typeof target !== 'object' || Array.isArray( target ) ) {
			return source;
		}

		// Both are objects - merge recursively
		const result = { ...target };

		for ( const key in source ) {
			if ( source.hasOwnProperty( key ) ) {
				const mergedValue = deepMerge( target[ key ], source[ key ] );
				// Only include the property if the merged value is not null
				if ( mergedValue !== null ) {
					result[ key ] = mergedValue;
				} else {
					// Remove the property entirely if the merged value is null
					delete result[ key ];
				}
			}
		}

		return result;
	};

	/**
	 * Recursively merges block data, preserving existing properties that are not overridden by new data
	 *
	 * @param {Block}       originalBlock The original block to preserve properties from
	 * @param {BlockData}   newBlockData  The new block data to apply
	 * @param {ClientIdMap} reverseMap    Mapping of compressed to original IDs
	 * @return {BlockData} Merged block data with preserved properties
	 */
	const mergeBlocksRecursively = (
		originalBlock: Block | null,
		newBlockData: BlockData,
		reverseMap: ClientIdMap
	): BlockData => {
		// If there's no original block, just use the new data
		if ( ! originalBlock ) {
			return newBlockData;
		}

		// Guard against empty arrays or objects in attributes
		// If newBlockData.attributes is [] or {}, preserve original attributes
		const shouldPreserveAttributes =
			Array.isArray( newBlockData.attributes ) ||
			( typeof newBlockData.attributes === 'object' &&
				newBlockData.attributes !== null &&
				Object.keys( newBlockData.attributes ).length === 0 );

		// Start with a merged block that preserves all properties
		const mergedBlock: BlockData = {
			...originalBlock,
			...newBlockData,
			// Deep merge attributes to preserve nested properties
			// If attributes are empty array/object, keep original attributes
			attributes: shouldPreserveAttributes
				? originalBlock.attributes || {}
				: deepMerge(
						originalBlock.attributes || {},
						newBlockData.attributes || {}
				  ),
		};

		// Cache image for image and cover blocks
		const imageBlocks = [
			{ name: 'core/image', cacheKey: imageCacheKeys.IMAGES },
			{ name: 'core/cover', cacheKey: imageCacheKeys.BACKGROUND_IMAGES },
		];
		for ( const { name, cacheKey } of imageBlocks ) {
			if ( mergedBlock.name === name && mergedBlock.attributes?.url ) {
				addCachedImage( {
					cacheKey,
					imageData: {
						url: mergedBlock.attributes.url,
						id: mergedBlock.attributes.id,
						alt: mergedBlock.attributes.alt,
					},
				} );
			}
		}

		// Handle inner blocks recursively if they exist in the new data
		if ( newBlockData.innerBlocks ) {
			mergedBlock.innerBlocks = newBlockData.innerBlocks.map(
				( newInnerBlock ) => {
					const originalClientId = newInnerBlock.clientId
						? reverseMap[ newInnerBlock.clientId ]
						: undefined;
					// Find the corresponding original inner block by clientId
					const originalInnerBlock = originalBlock.innerBlocks?.find(
						( block ) => block.clientId === originalClientId
					);

					// Recursively merge this inner block
					return mergeBlocksRecursively(
						originalInnerBlock || null,
						newInnerBlock,
						reverseMap
					);
				}
			);
		} else {
			// If no new inner blocks specified, preserve the original ones
			mergedBlock.innerBlocks = originalBlock.innerBlocks || [];
		}

		return mergedBlock;
	};

	/**
	 * Creates a block and its inner blocks recursively
	 *
	 * @param {BlockData} blockData Block data including name, attributes, and innerBlocks
	 * @return {Promise<any>} A valid block with all inner blocks properly created
	 */
	const createBlockRecursively = async (
		blockData: BlockData
	): Promise< any > => {
		// Create inner blocks first if they exist
		const processedInnerBlocks = blockData.innerBlocks?.length
			? await Promise.all(
					blockData.innerBlocks.map( createBlockRecursively )
			  )
			: [];

		return createBlock(
			blockData.name,
			blockData.attributes || {},
			processedInnerBlocks
		);
	};

	/**
	 * Deletes blocks based on their clientIds
	 *
	 * @param {string[]}    clientIds  Array of compressed clientIds to delete
	 * @param {ClientIdMap} reverseMap Mapping of compressed to original IDs
	 */
	const deleteBlocks = async (
		clientIds: string[],
		reverseMap: ClientIdMap
	): Promise< void > => {
		if ( ! clientIds?.length ) {
			return;
		}

		for ( const clientId of clientIds ) {
			const originalClientId = reverseMap[ clientId ];

			if ( ! originalClientId ) {
				console.error(
					`[Edit Blockd] Could not map compressed clientId for deletion: ${ clientId }`
				);
				continue;
			}

			const targetBlock = getBlock( originalClientId );

			if ( ! targetBlock ) {
				console.error(
					`[Edit Blocks] Block not found for deletion with clientId: ${ originalClientId }`
				);
				continue;
			}

			// Delete the block
			removeBlock( originalClientId );
		}
	};

	/**
	 * Recursively clears processing state for blocks
	 *
	 * @param {Block[]} blocks The blocks to clear processing state for
	 */
	// eslint-disable-next-line @typescript-eslint/no-unused-vars
	const clearProcessingBlocks = ( blocks: Block[] ): void => {
		blocks.forEach( ( block ) => {
			// Check if this block is in processing state
			if (
				block.attributes?.className?.includes(
					'big-sky__is-processing'
				)
			) {
				setBlockIsProcessing( block, false );
			}

			// Recursively check inner blocks
			if ( block.innerBlocks?.length && block.innerBlocks.length > 0 ) {
				clearProcessingBlocks( block.innerBlocks );
			}
		} );
	};

	/**
	 * Updates cover block overlay color based on background image
	 *
	 * @param {string} clientId - The block client ID
	 * @param {string} url      - The image URL
	 */
	const updateCoverBlockOverlay = async (
		clientId: string,
		url: string | undefined
	) => {
		if ( url ) {
			try {
				const mediaColor = await getMediaColor( url );
				updateBlockAttributes( clientId, {
					overlayColor: undefined,
					customOverlayColor: mediaColor,
					isUserOverlayColor: false,
				} );
			} catch ( error: any ) {
				log.error( 'Error updating cover block overlay color:', error );
			}
		}
	};

	/**
	 * Applies the edit results to the block
	 *
	 * @param {EditResults} editResults              The edit results to apply
	 * @param {ClientIdMap} reverseMap               Mapping of compressed to original IDs
	 * @param {string}      messageId                The message ID from the agent response
	 * @param {string}      summary                  The summary of the edits
	 * @param {boolean}     suppressAssistantMessage Whether to suppress the assistant message
	 */
	const applyEdits = async (
		editResults: EditResults,
		reverseMap: ClientIdMap,
		messageId: string,
		summary?: string,
		suppressAssistantMessage?: boolean
	): Promise< void > => {
		// Handle insertions first to avoid clientId conflicts
		// If we do updates first, clientIds of blocks change and inserts may fail
		if ( editResults.inserts?.length ) {
			for ( const insert of editResults.inserts ) {
				const { parentClientId, index = 0, block } = insert;
				// If no parentClientId is provided, use the section root (e.g., core/post-content)
				// If getSectionRootClientId() returns null (empty post), insertBlock will insert at root level
				const originalParentClientId = parentClientId
					? reverseMap[ parentClientId ]
					: getSectionRootClientId();

				// Only throw if a specific parentClientId was provided but couldn't be mapped
				if ( parentClientId && ! originalParentClientId ) {
					throw new Error(
						`[Edit Pattern] Could not map compressed parent clientId: ${ parentClientId }`
					);
				}

				// Verify parent block exists (only if we have a parent)
				if ( originalParentClientId ) {
					const parentBlock = getBlock( originalParentClientId );

					if ( ! parentBlock ) {
						throw new Error(
							`[Edit Pattern] Parent block not found with clientId: ${ originalParentClientId }`
						);
					}
				}

				// Create a valid block with proper validation
				const validBlock = await createBlockRecursively( block );
				// TODO: Find a better way to ensure innerBlocks are included reliably without this delay - registry.batch maybe?
				await setDelay( 200 );
				// insertBlock accepts null/undefined as rootClientId (inserts at root level for empty posts)
				insertBlock( validBlock, index, originalParentClientId );
				// Clear processing state after insert
				// Use the block's clientId (WordPress may assign a new one, but we'll try the original first)
				const insertedBlock = getBlock( validBlock.clientId );
				if ( insertedBlock ) {
					setBlockIsProcessing( insertedBlock, false );
				}
			}
		}

		// Handle updates
		if ( editResults.updates?.length ) {
			// Do inner updates first. If we do outer updates first,
			// the clientIds of the inner blocks change.
			const clientIdDepth = new Map< string, number >();
			for ( const update of editResults.updates ) {
				const { clientId } = update;
				const originalClientId = reverseMap[ clientId ];
				const depth = getBlockParents( originalClientId )?.length ?? 0;
				clientIdDepth.set( clientId, depth );
			}
			const updates = [ ...editResults.updates ].sort(
				( a, b ) =>
					( clientIdDepth.get( b.clientId ) ?? 0 ) -
					( clientIdDepth.get( a.clientId ) ?? 0 )
			);
			for ( const update of updates ) {
				const { clientId, ...blockData } = update;
				const originalClientId = reverseMap[ clientId ];

				if ( ! originalClientId ) {
					throw new Error(
						`[Edit Blocks] Could not map compressed clientId: ${ clientId }`
					);
				}

				const targetBlock = getBlock( originalClientId );

				if ( ! targetBlock ) {
					throw new Error(
						`[Edit BLocks] Block not found with clientId: ${ originalClientId }`
					);
				}

				// Recursively merge block data to preserve properties at all levels
				const mergedBlockData = mergeBlocksRecursively(
					targetBlock,
					blockData,
					reverseMap
				);

				// Check if this is just an attribute update (no structural changes)
				const hasInnerBlockChanges =
					blockData.innerBlocks && blockData.innerBlocks.length > 0;

				if ( ! hasInnerBlockChanges ) {
					// For attribute-only updates, use updateBlockAttributes
					// This preserves the block instance and properly triggers re-renders
					updateBlockAttributes(
						originalClientId,
						mergedBlockData.attributes
					);

					// For cover blocks with image URL updates, automatically set overlay color
					if ( targetBlock.name === 'core/cover' ) {
						await updateCoverBlockOverlay(
							originalClientId,
							blockData.attributes?.url
						);
					}

					// Clear processing state after update
					const updatedBlock = getBlock( originalClientId );
					if ( updatedBlock ) {
						setBlockIsProcessing( updatedBlock, false );
					}
				} else {
					// For structural changes, we need to replace the entire block
					const validBlock =
						await createBlockRecursively( mergedBlockData );
					replaceBlock( originalClientId, validBlock );
					// Need to update the reverseMap with the new clientId
					reverseMap[ clientId ] = validBlock.clientId;

					// For cover blocks with image URL updates, automatically set overlay color
					if ( validBlock.name === 'core/cover' ) {
						await updateCoverBlockOverlay(
							validBlock.clientId,
							validBlock.attributes?.url
						);
					}

					// Clear processing state after replace
					// Use the new block's clientId in case it changed
					const replacedBlock = getBlock( validBlock.clientId );
					if ( replacedBlock ) {
						setBlockIsProcessing( replacedBlock, false );
					}
				}
			}
		}

		// Handle deletions
		if ( editResults.deletes?.length ) {
			await deleteBlocks( editResults.deletes, reverseMap );
		}

		// Wait for all AI promises to resolve, animations to finish
		await Promise.all( aiPromises );

		deleteMarkedMessages();

		const isUnifiedExperience =
			wpSelect( aiStore ).getIsUnifiedChatEnabled();

		// Unified experience: rendering is handled by `convertToolMessagesToComponents()`
		// in agents-manager, so we skip legacy dock messages (`assistantSay` / `showResponseActions`).
		if ( ! suppressAssistantMessage && ! isUnifiedExperience ) {
			const assistantMessage = await assistantSay(
				summary
					? summary
					: __( 'I have completed the edits.', 'big-sky' )
			);

			const assistantMessageId = assistantMessage?.message?.id;
			changeCheckpointId( messageId, assistantMessageId );
			addCheckpointKeys( assistantMessageId, [ checkpointKeys.BLOCKS ] );
			showResponseActions( assistantMessageId );
		}
	};

	/**
	 * Applies edits to an existing block.
	 *
	 * @param {ApplyBlockEditsArgs} args The arguments for the tool.
	 * @return {Promise<Object>} The edit results.
	 */
	const applyBlockEdits = async (
		args: ApplyBlockEditsArgs
	): Promise< {
		result: string;
		returnToAgent: boolean;
		agentMessage?: string;
	} > => {
		let { reverseMap } = args;
		const {
			updates,
			inserts,
			deletes,
			summary,
			followUpTasks,
			messageId,
			suppressAssistantMessage,
			resetBlockProcessingStates = true,
			customCSS,
		} = args;
		// Use clientIdMap from hook closure as reverseMap
		if ( ! reverseMap ) {
			reverseMap = clientIdMap;
		}

		const applyEditsAction = async () => {
			const editResults: EditResults = { updates, inserts, deletes };

			try {
				setCheckpoint( messageId, [ checkpointKeys.BLOCKS ] );
				// Validate the edit results
				validateEditResults( editResults, availableBlocks );

				// Apply the edits
				await applyEdits(
					editResults,
					reverseMap,
					messageId,
					summary,
					suppressAssistantMessage
				);

				// Replace custom CSS if provided.
				if ( typeof customCSS === 'string' ) {
					const globalStylesId = getGlobalStylesId();
					if ( globalStylesId ) {
						const freshGlobalStyles = getEditedEntityRecord(
							'root',
							'globalStyles',
							globalStylesId
						);
						const updatedGlobalStyles = setStyle(
							freshGlobalStyles,
							'css',
							customCSS
						);
						editEntityRecord(
							'root',
							'globalStyles',
							globalStylesId,
							updatedGlobalStyles
						);
					}
				}

				// check to see if any edits were actually made by comparing the current blocks with the checkpoint
				const lastEditorState = getLastEditorState();
				const lastEditorStateBlocks = lastEditorState?.blocks || [];
				const currentEditorState: EditorState = {
					blocks: getRootBlocksState(),
				};

				if (
					JSON.stringify( lastEditorStateBlocks ) ===
					JSON.stringify( currentEditorState.blocks )
				) {
					return {
						result: __(
							"I was not able to make the changes you requested. Either I don't have the capability to do so or I didn't understand your request. You can ask me to try again or ask me to do something else.",
							'big-sky'
						),
						returnToAgent: !! followUpTasks,
					};
				}

				const differences = compareBlockStates(
					lastEditorStateBlocks,
					currentEditorState.blocks
				);
				log.info( 'Detailed changes:', differences );

				const isUnifiedExperience =
					wpSelect( aiStore ).getIsUnifiedChatEnabled();
				const summaryText =
					summary || __( 'I have completed the edits.', 'big-sky' );

				// return the result
				return {
					result: summaryText,
					returnToAgent: !! followUpTasks,
					agentMessage: isUnifiedExperience
						? JSON.stringify( {
								tool_id: 'big_sky__apply_block_edits',
								data: {
									summary: summaryText,
									calypsoCheckpointId: messageId,
								},
						  } )
						: localToolRunningMessage,
				};
			} catch ( error ) {
				deleteMarkedMessages();
				if ( ! suppressAssistantMessage ) {
					addAssistantMessage(
						ASSISTANTS.BLOCKS,
						__(
							'Something went wrong. Please try again.',
							'big-sky'
						)
					);
				}
				log.error( '[Apply Block Edits] Error:', error );
				throw error;
			} finally {
				if ( resetBlockProcessingStates ) {
					resetAllBlockIsProcessing();
				}
			}
		};

		return await applyEditsAction();
	};

	return {
		applyBlockEdits,
	};
}
