/**
 * WordPress dependencies
 */
import { useEffect } from '@wordpress/element';

// NOTE: Temporary fix to keep the chat above mobile keyboards until a permanent layout solution is implemented
export default function useMobileKeyboardOffset( chatSelector, inputSelector ) {
	useEffect( () => {
		const isTouchDevice =
			( window.matchMedia( '(any-pointer: coarse)' ).matches ||
				window.matchMedia( '(hover: none)' ).matches ) &&
			'ontouchstart' in window;

		if ( ! isTouchDevice ) {
			return;
		}

		const chat = document.querySelector( chatSelector );
		const input = chat?.querySelector( inputSelector );

		if ( ! chat || ! input ) {
			return;
		}

		const originalBottom = chat.style.bottom;
		const originalOffset = parseInt( originalBottom, 10 ) || 0;
		const viewport = window.visualViewport;
		let baseHeight, rafId, blurTimeoutId;

		const updateBottom = () => {
			rafId = window.requestAnimationFrame( () => {
				const viewportHeight = viewport?.height ?? window.innerHeight;
				const keyboardOffset = Math.max(
					0,
					baseHeight - viewportHeight
				);

				chat.style.bottom = `${ keyboardOffset + originalOffset }px`;
			} );
		};

		const handleFocus = () => {
			baseHeight = window.innerHeight;
			updateBottom();
		};

		const handleBlur = () => {
			// Delay to allow click events (e.g., submit button) to fire first
			blurTimeoutId = window.setTimeout( () => {
				window.cancelAnimationFrame( rafId );
				chat.style.bottom = originalBottom;
			}, 100 );
		};

		input.addEventListener( 'focus', handleFocus );
		input.addEventListener( 'blur', handleBlur );
		viewport?.addEventListener( 'resize', updateBottom );

		return () => {
			window.clearTimeout( blurTimeoutId );
			window.cancelAnimationFrame( rafId );
			input.removeEventListener( 'focus', handleFocus );
			input.removeEventListener( 'blur', handleBlur );
			viewport?.removeEventListener( 'resize', updateBottom );
			chat.style.bottom = originalBottom;
		};
	}, [ chatSelector, inputSelector ] );
}
