/**
 * Image Studio utilities for use outside the image-studio bundle.
 *
 * IMPORTANT: This file must NOT import from `image-studio/` to avoid
 * pulling the image-studio store into the main Big Sky bundle.
 * Enum values are duplicated here intentionally — they mirror the
 * canonical definitions in `image-studio/types/index.ts` and
 * `image-studio/store/index.ts`.
 */

import { dispatch } from '@wordpress/data';
import { store as blockEditorStore } from '@wordpress/block-editor';

export const IMAGE_STUDIO_STORE = 'image-studio';

/**
 * Mirror of ImageStudioMode from image-studio/types.
 */
export enum ImageStudioMode {
	Edit = 'edit',
	Generate = 'generate',
}

/**
 * Mirror of ImageStudioEntryPoint from image-studio/store.
 */
export enum ImageStudioEntryPoint {
	MediaLibrary = 'media_library',
	EditorBlock = 'editor_block',
	EditorSidebar = 'editor_sidebar',
	JetpackExternalMediaBlock = 'jetpack_external_media_block',
	JetpackExternalMediaFeaturedImage = 'jetpack_external_media_featured_image',
	JetpackAIFeaturedImage = 'jetpack_ai_featured_image',
	JetpackAISocialMedia = 'jetpack_ai_social_media',
}

interface BlockContext {
	name: string;
	clientId?: string;
	attributes?: Record< string, any >;
	innerBlocks?: BlockContext[];
}

/**
 * Opens Image Studio for a block via the store, without importing the image-studio bundle.
 * @param imageBlock - The image block (or block containing an image) with clientId and attributes
 * @param mode       - The mode to open Image Studio in
 * @param entryPoint - The entry point for tracking
 */
export function openImageStudioForBlock(
	imageBlock: BlockContext,
	mode: ImageStudioMode,
	entryPoint: ImageStudioEntryPoint
): boolean {
	if ( ! imageBlock?.clientId ) {
		return false;
	}

	const { clientId } = imageBlock;
	const attachmentId = imageBlock.attributes?.id;

	const handleClose = ( image: any ) => {
		if ( image === null ) {
			dispatch( blockEditorStore ).updateBlockAttributes( clientId, {
				url: undefined,
				id: undefined,
				alt: '',
				title: '',
				caption: '',
			} );
			return;
		}

		if ( image?.id ) {
			dispatch( blockEditorStore ).updateBlockAttributes( clientId, {
				url: image.url,
				id: image.id,
				alt: image.alt,
			} );
		}
	};

	( dispatch( IMAGE_STUDIO_STORE ) as any ).openImageStudio(
		mode === ImageStudioMode.Edit ? attachmentId : undefined,
		handleClose,
		entryPoint
	);

	return true;
}

export function isImageStudioEnabled(): boolean {
	return (
		( window as any ).bigSkyImageStudio?.enabled === '1' ||
		( window as any ).imageStudioData?.enabled === true
	);
}
