/**
 * WordPress dependencies
 */
import { useCallback, useState } from '@wordpress/element';
import { useSelect, select as wpSelect } from '@wordpress/data';
import apiFetch from '@wordpress/api-fetch';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import { recordTracksEvent } from '@utils/tracks';
import { getIsInternalTester } from '@utils/env';
import logAction from '@utils/log-action';
import log from '@utils/log-debug.js';

/**
 * Custom hook for managing thumbs up/down feedback functionality
 *
 * @param {string} id - The message ID to associate feedback with
 * @return {Object} Feedback state and handlers
 */
export default function useFeedback( id ) {
	const [ selectedFeedback, setSelectedFeedback ] = useState( null );
	const [ showFeedbackInput, setShowFeedbackInput ] = useState( false );
	const isInternalTester = getIsInternalTester();

	const { sessionId } = useSelect( ( select ) => {
		return {
			sessionId: select( aiStore ).getSessionId(),
		};
	}, [] );

	const handleFeedback = useCallback(
		( type ) => {
			recordTracksEvent( `response_action_thumbs_${ type }`, {
				id,
			} );

			apiFetch( {
				path:
					'/wpcom/v2/big-sky/v1/session/' +
					encodeURIComponent( sessionId ) +
					'/rate',
				method: 'POST',
				data: {
					message_id: id,
					rating: type,
					big_sky_version:
						window?.bigSkyInitialState?.bigSkyVersion ?? '0',
				},
			} );
			setSelectedFeedback( type );

			// Show feedback input for internal testers when thumbs down is clicked
			if ( type === 'down' && isInternalTester ) {
				setShowFeedbackInput( true );
			}
		},
		[ id, sessionId, isInternalTester ]
	);

	const handleSubmitFeedback = useCallback(
		async ( feedbackText ) => {
			if ( ! feedbackText.trim() || ! sessionId ) {
				return;
			}
			// Get messages directly from the store inside the callback
			const messages = wpSelect( aiStore ).getMessages();
			const userMessages = messages.filter(
				( msg ) => msg.role === 'user'
			);

			let previousUserMessage = null;
			if ( userMessages.length > 0 ) {
				const lastUserMessage = userMessages[ userMessages.length - 1 ];
				if ( Array.isArray( lastUserMessage.content ) ) {
					const textContent = lastUserMessage.content.find(
						( item ) => item.type === 'text'
					);
					previousUserMessage = textContent?.text || null;
				}
			}

			try {
				await apiFetch( {
					path:
						'/wpcom/v2/big-sky/v1/session/' +
						encodeURIComponent( sessionId ) +
						'/feedback',
					method: 'POST',
					data: {
						message_id: id,
						feedback: feedbackText,
						previous_user_message: previousUserMessage,
						big_sky_version:
							window?.bigSkyInitialState?.bigSkyVersion ?? '0',
					},
				} );

				// Log feedback as a user_feedback message type
				logAction(
					sessionId,
					feedbackText,
					'user_feedback',
					`feedback-${ id }-${ Date.now() }`,
					id
				);
			} catch ( error ) {
				log.error( 'Error submitting feedback:', error );
				throw error;
			}
		},
		[ sessionId, id ]
	);

	const handleCancelFeedback = useCallback( () => {
		setShowFeedbackInput( false );
	}, [] );

	return {
		selectedFeedback,
		showFeedbackInput,
		handleFeedback,
		handleSubmitFeedback,
		handleCancelFeedback,
		isInternalTester,
	};
}
