/* global React */
/**
 * WordPress dependencies
 */

import { store as editorStore } from '@wordpress/editor';
import { store as blockEditorStore } from '@wordpress/block-editor';
import { dispatch, resolveSelect, select } from '@wordpress/data';
import { __ } from '@wordpress/i18n';

/**
 * Internal dependencies
 */
import ButtonVariationPicker from '@components/button-variation-picker';
import NextStepButton from '@components/next-step-button';
import CompletedPlan from '@components/chat/components/completed-plan';
import { store as aiStore } from '@store';
import { checkpointKeys, localToolRunningMessage } from '@utils/constants';
import logger from '@utils/log-debug';
import FontPicker from './font-picker';
import ColorPalette from './color-palette';
import PatternPickerWrapper from './pattern-picker-wrapper';
import { unlock } from '@utils/lock-unlock';
import { zoomOut as zoomOutUtil } from '@utils/canvas-zoom';

type ComponentType =
	| 'button-picker'
	| 'font-picker'
	| 'color-picker'
	| 'pattern-picker';

interface ShowComponentArgs {
	type: ComponentType;
	props?: Record< string, unknown >;
	followUpTasks?: boolean;
	zoomOut?: boolean;
	clientId?: string;
	messageId?: string;
	insertIndex?: number;
	reverseMap?: Record< string, string >;
}

interface CheckpointContext {
	setCheckpoint: ( assistantMessageId: string, keys: string[] ) => void;
	addNewPageToCheckpoint: ( newPageId: string ) => void;
}

interface ShowComponentResult {
	result: string;
	returnToAgent: boolean;
	agentMessage?: string;
}

/**
 * Get the component based on type
 *
 * @param type - The type of component to get
 */
const getComponent = ( type: ComponentType ): React.ComponentType< any > => {
	switch ( type ) {
		case 'button-picker':
			return ButtonVariationPicker;
		case 'font-picker':
			return FontPicker;
		case 'color-picker':
			return ColorPalette;
		case 'pattern-picker':
			return PatternPickerWrapper;
		default:
			throw new Error( `Unknown component type: ${ type }` );
	}
};

const setCheckpointByType = (
	type: ComponentType,
	assistantMessageId: string,
	setCheckpoint: ( assistantMessageId: string, keys: string[] ) => void,
	addNewPageToCheckpoint: ( newPageId: string ) => void,
	newPageId?: string
): void => {
	switch ( type ) {
		case 'button-picker':
			setCheckpoint( assistantMessageId, [ checkpointKeys.BUTTON ] );
			break;
		case 'font-picker':
			setCheckpoint( assistantMessageId, [ checkpointKeys.FONT ] );
			break;
		case 'color-picker':
			setCheckpoint( assistantMessageId, [ checkpointKeys.COLOR ] );
			break;
		case 'pattern-picker':
			if ( newPageId ) {
				setCheckpoint( assistantMessageId, [ checkpointKeys.PAGE ] );
				addNewPageToCheckpoint( newPageId );
			} else {
				setCheckpoint( assistantMessageId, [ checkpointKeys.BLOCKS ] );
			}
			break;
		default:
			// do nothing
			break;
	}
};

/**
 * Helper function to zoom out the editor
 */
const zoomOut = async (): Promise< void > => {
	const { setZoomLevel } = unlock( dispatch( blockEditorStore ) );
	const { __unstableSetEditorMode } = dispatch( blockEditorStore );

	return await zoomOutUtil( {
		setZoomLevel,
		__unstableSetEditorMode,
	} );
};

/**
 * Show a component in the UI with specified props
 *
 * @param args                         - The arguments for the show component tool
 * @param root0                        - Checkpoint context
 * @param root0.setCheckpoint          - Function to set checkpoint
 * @param root0.addNewPageToCheckpoint - Function to add new page to checkpoint
 */
export const showComponent = async (
	args: ShowComponentArgs,
	{ setCheckpoint, addNewPageToCheckpoint }: CheckpointContext
): Promise< ShowComponentResult > => {
	const {
		type,
		props = {},
		followUpTasks,
		zoomOut: shouldZoomOut = false,
		clientId,
		messageId,
		insertIndex,
		reverseMap,
	} = args;
	const {
		addMessageToDelete,
		deleteMarkedMessages,
		assistantSay,
		addMessage,
		setSuppressSuggestions,
	} = dispatch( aiStore );

	try {
		// check if props is object and has properties
		if ( typeof props !== 'object' || Object.keys( props ).length === 0 ) {
			throw new Error( 'Props must be an object with properties' );
		}

		// Zoom out before showing the component if requested
		if ( shouldZoomOut ) {
			await zoomOut();
			setSuppressSuggestions( true );
		}

		// Add clientId and insertIndex to props
		if ( clientId && reverseMap ) {
			props.clientId = reverseMap[ clientId ];
		}
		if ( insertIndex !== undefined && insertIndex >= 0 ) {
			props.insertIndex = insertIndex;
		}

		// get the component and create the element
		const Component = getComponent( type );

		// delete the marked messages
		deleteMarkedMessages();

		// get the current post id
		const currentPostId =
			await resolveSelect( editorStore ).getCurrentPostId();

		const isUnifiedExperience = select( aiStore ).getIsUnifiedChatEnabled();

		// Legacy dock: We inject React components directly via `addMessage()`.
		if ( ! isUnifiedExperience ) {
			const assistantMessage = await addMessage( {
				role: 'assistant',
				postId: currentPostId,
				content: [
					{
						type: 'component',
						component: Component,
						componentProps: { ...props, type },
					},
				],
			} );

			const assistantMessageId = assistantMessage?.message?.id;

			// Legacy response actions (feedback/undo/zoom)
			await addMessage( {
				role: 'assistant',
				postId: currentPostId,
				content: [
					{
						type: 'component',
						component: CompletedPlan,
						componentProps: {
							id: assistantMessageId,
							type: 'response-actions',
						},
					},
				],
			} );

			if ( followUpTasks ) {
				const nextStepButtonMessage = await addMessage( {
					role: 'assistant',
					content: [
						{
							type: 'component',
							component: NextStepButton,
						},
					],
				} );
				addMessageToDelete( {
					id: nextStepButtonMessage?.message?.id,
				} );
			}

			// Add a checkpoint
			if ( assistantMessageId ) {
				setCheckpointByType(
					type,
					assistantMessageId,
					setCheckpoint,
					addNewPageToCheckpoint,
					props?.newPageId as string | undefined
				);
			}
		}

		// Unified experience:
		//   Rendering is handled by `convertToolMessagesToComponents()` in agents-manager,
		//   which converts the JSON `agentMessage` into a React component via `getChatComponent()`.
		//   This ensures the message goes through the normal transform pipeline and gets
		//   action resolution (feedback buttons).
		if ( isUnifiedExperience && messageId ) {
			// Add a checkpoint
			setCheckpointByType(
				type,
				messageId,
				setCheckpoint,
				addNewPageToCheckpoint,
				props?.newPageId as string | undefined
			);
		}

		// return the result
		const returnValue = {
			result: 'Component displayed successfully',
			returnToAgent: false,
			agentMessage: isUnifiedExperience
				? JSON.stringify( {
						tool_id: 'big_sky__show_component',
						data: {
							type,
							props,
							followUpTasks,
							isCurrent: true,
							postId: currentPostId,
							calypsoCheckpointId: messageId,
						},
				  } )
				: localToolRunningMessage,
		};
		return returnValue;
	} catch ( error ) {
		logger.error( `Error showing component ${ type }:`, error );
		deleteMarkedMessages();
		await assistantSay(
			__(
				'There was an error with this request. Please try again.',
				'big-sky'
			)
		);
		return {
			result: `There was an error with this request.`,
			returnToAgent: followUpTasks ?? false,
		};
	}
};
