/**
 * WordPress dependencies
 */
import { addQueryArgs } from '@wordpress/url';

export const getDomainRegistrationLink = ( siteTitle, redirect ) => {
	const siteId =
		window?.JP_CONNECTION_INITIAL_STATE?.userConnectionData?.currentUser
			?.blogId;
	return addQueryArgs(
		'https://wordpress.com/setup/ai-site-builder/domains',
		{
			siteId,
			siteTitle,
			redirect,
		}
	);
};

export const getPlanSelectionLink = ( redirect, siteTitle, flow ) => {
	const siteId =
		window?.JP_CONNECTION_INITIAL_STATE?.userConnectionData?.currentUser
			?.blogId;
	return addQueryArgs( 'https://wordpress.com/setup/ai-site-builder/plans', {
		siteId,
		siteTitle,
		flow,
		redirect,
	} );
};
