/**
 * WordPress dependencies
 */
import { useDispatch } from '@wordpress/data';
import { uploadMedia } from '@wordpress/media-utils';
import { store as blockEditorStore } from '@wordpress/block-editor';
import { store as coreStore } from '@wordpress/core-data';

/**
 * Internal dependencies
 */
import useAnalyzeImage from '@ai/tasks/analyze-image/use-analyze-image';
import useBlocks from '@hooks/use-blocks';
import useLog from '@hooks/use-log';
import { store as aiStore } from '@store';
import { textFromHtml } from '@utils/text-from-html';
import { createScaledImageBase64 } from '@utils/images';

import {
	buildAttrToUpdateImage,
	canUseBackgroundImages,
	getBlockImageData,
	hasBackgroundImage,
} from '@utils/block-image';

/**
 * Custom hook for handling media uploads with AI-powered image analysis.
 *
 * This hook provides functionality to upload images and automatically analyze them
 * to generate alt text descriptions. It also updates existing blocks that use
 * the uploaded images with the generated alt text.
 *
 * @return {Object} Object containing upload functionality with uploadImage function.
 */
export default function useUploadMedia() {
	const { analyzeImage } = useAnalyzeImage();
	const { getRootBlocks } = useBlocks();
	const { logAction, logError } = useLog();
	const { updateBlockAttributes } = useDispatch( blockEditorStore );
	const { addCachedImage } = useDispatch( aiStore );
	const { saveEntityRecord } = useDispatch( coreStore );

	/**
	 * Updates the alt text of blocks that use a specific image URL.
	 *
	 * Recursively traverses through all blocks and their inner blocks to find
	 * image blocks that use the specified URL and updates their alt text attributes.
	 *
	 * @param {Object}  params          - The parameters object.
	 * @param {Array}   params.blocks   - Array of blocks to search through.
	 * @param {string}  params.url      - The image URL to match against.
	 * @param {string}  params.altText  - The alt text to set for matching blocks.
	 * @param {boolean} params.checkUrl - Whether to check the URL of the image.
	 */
	const updateAltTextInImages = ( {
		blocks,
		url,
		altText,
		checkUrl = true,
	} ) => {
		blocks.forEach( ( block ) => {
			const imageData = getBlockImageData( block );
			if ( ! checkUrl || imageData.url === url ) {
				// make sure background supported blocks have a background image before updating it
				if (
					canUseBackgroundImages( block ) &&
					! hasBackgroundImage( block )
				) {
					return;
				}

				const attrUpdate = buildAttrToUpdateImage(
					block,
					url,
					altText
				);
				block.attributes = {
					...block.attributes,
					...attrUpdate,
				};
				updateBlockAttributes( block.clientId, attrUpdate );
			}
			block.innerBlocks.forEach( ( innerBlock ) => {
				updateAltTextInImages( {
					blocks: [ innerBlock ],
					url,
					altText,
					checkUrl,
				} );
			} );
		} );
	};

	/**
	 * Updates the alt text of an attachment in memory and in the database.
	 *
	 * @param {Object} attachment - The attachment object.
	 * @param {string} altText    - The alt text to set for the attachment.
	 */
	const updateAttachmentAltText = async ( attachment, altText ) => {
		attachment.alt = altText;
		if ( attachment.id ) {
			await saveEntityRecord(
				'root',
				'media',
				{
					id: attachment.id,
					alt_text: altText,
				},
				{ throwOnError: true }
			);
			logAction( `Uploaded image, updated alt text to: ${ altText }` );
		}
	};

	/**
	 * Processes image analysis for an uploaded file.
	 *
	 * Creates a scaled version of the image and sends it to the AI analysis service
	 * to generate a description, and updates the attachment's alt text both
	 * in the media library and in any blocks using the image.
	 *
	 * @param {File} file - The file object to analyze.
	 * @return {Promise<void>} Promise that resolves when analysis is complete.
	 */
	const processImageAnalysis = async ( file ) => {
		// Create scaled image and convert to base64
		const base64DataUrl = await createScaledImageBase64( file );

		// Extract the base64 string by removing the data URL prefix
		const base64Image = base64DataUrl.split( ',' )[ 1 ];

		// Analyze the image to get its description
		return analyzeImage( {
			imageBase64: base64Image,
			mimeType: file.type,
		} );
	};

	/**
	 * Sanitizes an image description by removing HTML tags and applying WordPress-style sanitization.
	 *
	 * @param {string} description - The image description to sanitize.
	 * @return {string} The sanitized image description.
	 */
	const sanitizeImageDescription = ( description ) => {
		// Extract text from HTML and sanitize
		let sanitized = textFromHtml( description );

		// Limit length to 125 characters (accessibility best practice)
		// This allows for descriptive alt text while keeping it concise
		if ( sanitized.length > 125 ) {
			sanitized = sanitized.substring( 0, 122 ) + '...';
		}

		return sanitized;
	};

	/**
	 * Generates alt text for an uploaded image.
	 *
	 * @param {File}   file          - The file object to analyze.
	 * @param {Object} attachment    - The WordPress attachment object.
	 * @param {string} cacheKey      - The cache key to use for the image.
	 * @param {number} cachePriority - The cache priority to use for the image.
	 * @param {Object} block         - The block to generate an image for.
	 * @return {Promise<void>} Promise that resolves when alt text is generated.
	 */
	const generateAltText = async (
		file,
		attachment,
		cacheKey,
		cachePriority,
		block = null
	) => {
		try {
			const imageDescription = await processImageAnalysis( file );
			if ( imageDescription?.length ) {
				const sanitizedImageDescription =
					sanitizeImageDescription( imageDescription );

				await updateAttachmentAltText(
					attachment,
					sanitizedImageDescription
				);
				// Update alt text in the specified block or all blocks using this image
				updateAltTextInImages( {
					blocks: block ? [ block ] : getRootBlocks(),
					url: attachment.url,
					altText: sanitizedImageDescription,
					checkUrl: ! block, // Only check URL if we're searching all blocks
				} );
				// Update cached image
				addCachedImage( {
					cacheKey,
					imageData: {
						url: attachment.url,
						alt: sanitizedImageDescription,
						priority: cachePriority,
					},
				} );
			}
		} catch ( error ) {
			logError( `Failed to generate alt text:`, error );
		}
	};

	/**
	 * Uploads an image file with optional AI analysis.
	 *
	 * Uses WordPress's uploadMedia utility to upload the file, then optionally
	 * waits for AI analysis to complete before resolving the promise.
	 * The analysis generates alt text for the image and updates relevant blocks.
	 *
	 * @param {File}   file          - The file to upload.
	 * @param {string} cacheKey      - The cache key to use for the image.
	 * @param {number} cachePriority - The cache priority to use for the image.
	 * @param {Object} block         - The block to generate an image for.
	 * @return {Promise<Array>} Promise that resolves with the uploaded files array.
	 */
	const uploadImage = async (
		file,
		cacheKey,
		cachePriority,
		block = null
	) => {
		return new Promise( ( resolve, reject ) => {
			uploadMedia( {
				filesList: [ file ],
				onFileChange: async ( files ) => {
					// Filter out any files that are still in the process of uploading (blob URLs)
					const finalFiles = files.filter(
						( f ) => f.url && ! f.url.startsWith( 'blob:' )
					);
					if ( finalFiles.length > 0 ) {
						// Generate alt text for the uploaded image
						generateAltText(
							file,
							finalFiles[ 0 ],
							cacheKey,
							cachePriority,
							block
						);

						resolve( finalFiles );
					}
				},
				onError: ( error ) => {
					reject( error );
				},
			} );
		} );
	};

	return {
		uploadImage,
	};
}
