/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';

/**
 * External dependencies
 */
import type { Ability } from '@wordpress/abilities';

/**
 * Apply block edits ability callback type
 */
export type ApplyBlockEditsCallback = ( args: {
	updates?: any[];
	inserts?: any[];
	deletes?: any[];
	summary?: string;
	followUpTasks?: boolean;
	messageId?: string;
	suppressAssistantMessage?: boolean;
	resetBlockProcessingStates?: boolean;
	reverseMap?: any;
	customCSS?: string;
} ) => Promise< {
	result: string;
	returnToAgent: boolean;
	agentMessage?: string;
} >;

/**
 * Apply block edits ability
 *
 * Applies a collection of block edits (updates, insertions, deletions) to the canvas.
 *
 * @param callback - The apply block edits callback function from the hook
 * @return The apply block edits ability definition
 */
export const applyBlockEditsAbility = (
	callback: ApplyBlockEditsCallback
): Ability => ( {
	name: 'big-sky/apply-block-edits',
	label: __( 'Apply Block Edits', 'big-sky' ),
	category: 'big-sky',
	description: __(
		'Applies a collection of block edits to the canvas',
		'big-sky'
	),
	input_schema: {
		type: 'object',
		properties: {
			updates: {
				type: 'array',
				description: 'Array of block updates to apply',
			},
			inserts: {
				type: 'array',
				description: 'Array of block insertions to apply',
			},
			deletes: {
				type: 'array',
				description: 'Array of block deletions (clientIds) to apply',
			},
			summary: {
				type: 'string',
				description: 'Summary message to show to the user',
			},
			followUpTasks: {
				type: 'boolean',
				description:
					'Set to true if the user request has to be broken into multiple steps and other tasks remain to be done after this one.',
			},
			messageId: {
				type: 'string',
				description: 'Optional message ID for context',
			},
			suppressAssistantMessage: {
				type: 'boolean',
				description: 'Whether to suppress assistant message',
			},
			resetBlockProcessingStates: {
				type: 'boolean',
				description: 'Whether to reset block processing states',
			},
			reverseMap: {
				type: 'object',
				description: 'Optional reverse mapping for client IDs',
			},
			customCSS: {
				type: 'string',
				description:
					'Full custom CSS value to replace the site global styles CSS',
			},
		},
	},
	callback: async ( input ) => {
		return await callback( input );
	},
} );
