/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';
import { select } from '@wordpress/data';

/**
 * External dependencies
 */
import type { Ability } from '@wordpress/abilities';

/**
 * Internal dependencies
 */
import { getAssistants } from '@ai/assistants';
import { store as aiStore } from '@store';

/**
 * Client assistants ability callback type
 */
export type ClientAssistantsCallback = ( args: {
	assistantId: string;
	request: string;
	clientId: string;
	progressMessage: string;
	userConfirmed: boolean;
	followUpTasks: boolean;
} ) => Promise< {
	result: any;
	returnToAgent: boolean;
} >;

/**
 * Client assistants ability
 *
 * Executes client-side assistants for various specialized tasks.
 *
 * @param callback - The run assistant callback function from the hook
 * @return The client assistants ability definition
 */
export const clientAssistantsAbility = (
	callback: ClientAssistantsCallback
): Ability => {
	// Get available assistants, filtering out spec assistant
	const assistants = getAssistants().filter(
		( assistant ) => assistant.id !== 'big-sky-spec'
	);

	// Get clientIdMap from store
	const clientIdMap =
		select( aiStore ).getFullPageStructure()?.clientIdMap || {};
	const clientIdEnum = Object.keys( clientIdMap );

	return {
		name: 'big-sky/client-assistants',
		label: __( 'Execute Client Assistant', 'big-sky' ),
		category: 'big-sky',
		description:
			__(
				'Always use this if the user asks for something that requires a client-side assistant. Available assistants:',
				'big-sky'
			) +
			assistants
				.map(
					( assistant ) =>
						`<${ assistant.id }>${ assistant.description }</${ assistant.id }>`
				)
				.join( '\n\n' ),
		meta: {
			instructions: `
			Call this tool when users request a site administrative operation.
			- Only handles site-wide administrative operations.
			- Use this assistant if the request asks to "start over" or "reset their site"
			- Use this assistant if the request asks for things like "design a site", "create a site" or "build a site"
			- Use this assistant if the request contains a detailed description of the site
			`,
		},
		input_schema: {
			type: 'object',
			properties: {
				assistantId: {
					type: 'string',
					description: 'The ID of the specific assistant to execute.',
					enum: assistants.map( ( assistant ) => assistant.id ),
				},
				request: {
					type: 'string',
					description:
						'The specific request from the user related to this assistant, broken out from the original user request.',
				},
				clientId: {
					type: 'string',
					description:
						'The ID of the block that this step is targeting. ALWAYS take this from the page_structure context, unless the request is to add a pattern or section and the location is not specified in which case use the selected_block_client_id.',
					enum: clientIdEnum,
				},
				progressMessage: {
					type: 'string',
					description:
						'A summary of task you are running. This will be displayed to the user as the assistant is running, eg. if the user asked for red palettes, this could be "Generating red palettes". Message must be no more than 2 or 3 words.',
				},
				userConfirmed: {
					type: 'boolean',
					description:
						'Sometimes an assistant will asks for confirmation, if the user has provided this confirmation, set this to true',
				},
				followUpTasks: {
					type: 'boolean',
					description:
						'Set to true if the user request has to be broken into multiple steps and other tasks remain to be done after this one.',
				},
			},
			required: [
				'assistantId',
				'request',
				'clientId',
				'progressMessage',
				'userConfirmed',
				'followUpTasks',
			],
		},
		callback: async ( input ) => {
			const callAssistant = await callback( {
				...input,
				assistantId: input.assistantId,
			} );
			const { result, returnToAgent, agentMessage } = callAssistant;
			return {
				result:
					result?.message ||
					__( 'Assistant completed successfully', 'big-sky' ),
				returnToAgent,
				agentMessage,
			};
		},
	};
};
