/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';

/**
 * Internal dependencies
 */
import { errorCodes } from '@utils/constants';
import log from '@utils/log-debug.js';

/**
 * Centralized error handling for chat operations
 * Enhances the existing setError system with chat-specific error processing
 *
 * @param {Error|string} error - The error to handle
 * @return {Function} Redux thunk action
 */
export const handleChatError =
	( error ) =>
	async ( { dispatch } ) => {
		const errorMessage = typeof error === 'string' ? error : error.message;

		// Log the error for debugging
		log.error( 'Chat error occurred:', error );

		// Set user-friendly error message based on error type
		let userMessage = errorMessage;

		if ( errorMessage === errorCodes.QUOTA_EXCEEDED ) {
			userMessage = __(
				'AI request quota exceeded. Please try again later.',
				'big-sky'
			);
		} else if (
			errorMessage.includes( 'network' ) ||
			errorMessage.includes( 'fetch' )
		) {
			userMessage = __(
				'Network error. Please check your connection and try again.',
				'big-sky'
			);
		} else if ( errorMessage.includes( 'timeout' ) ) {
			userMessage = __(
				'Request timed out. Please try again.',
				'big-sky'
			);
		} else {
			userMessage = __(
				'An error occurred while processing your request.',
				'big-sky'
			);
		}

		// Use existing setError action
		dispatch.setError( userMessage );

		return { error: errorMessage, userMessage };
	};

/**
 * Enhanced userSay action that includes full chat flow
 * This replaces the need for components to manage the chat flow manually
 *
 * @param {string} message - The user message
 * @param {Object} options - Additional options for the chat
 * @return {Function} Redux thunk action
 */
export const userSay =
	( message, options = {} ) =>
	async ( { dispatch } ) => {
		return dispatch.runChat( message, options );
	};

/**
 * Main unified chat action that handles switching between chat implementations internally
 * This is the core action that replaces the useChat hook functionality
 *
 * @param {string} message - The user message
 * @param {Object} options - Additional options for the chat
 * @return {Function} Redux thunk action
 */
export const runChat =
	( message, options = {} ) =>
	async ( { select, dispatch } ) => {
		// Check if site spec is currently showing based on URL routing
		const currentStep = select.getAiStep();
		const showSiteSpec = currentStep === 'spec';

		// Use the agentic chat everywhere except for site spec
		if ( ! showSiteSpec ) {
			// Use existing runAgent action for agentic chat
			// runAgent handles its own user message, thinking state, and message management
			return await dispatch.runAgent( message, options );
		}

		const assistantId = select.getAssistant();
		// For traditional chat, we manage the flow here
		// Add user message to store
		dispatch.addUserMessage( message );

		// Set thinking state and add thinking message
		dispatch.setThinking( true );
		await dispatch.addThinkingMessage( assistantId );

		try {
			// Use new runAssistantChat action for traditional chat
			const response = await dispatch.runAssistantChat(
				message,
				options
			);

			// Add assistant response if we got one
			if ( response ) {
				await dispatch.addAssistantMessage( assistantId, response );
			}

			return response;
		} catch ( error ) {
			// Use centralized error handling
			await dispatch.handleChatError( error );
			throw error;
		} finally {
			dispatch.setThinking( false );
		}
	};

/**
 * Enhanced addAssistantMessage with UI logic
 * Handles long message display and icon assignment
 *
 * @param {string} assistantId - The assistant ID
 * @param {string} message     - The message content
 * @param {Object} props       - Additional message properties
 * @return {Function} Redux thunk action
 */
export const addAssistantMessage =
	( assistantId, message, props = {} ) =>
	async ( { dispatch } ) => {
		return dispatch.assistantSay( message, {
			...props,
		} );
	};
