/**
 * WordPress dependencies
 */
import { ThumbsDownIcon, ThumbsUpIcon } from '@automattic/agenttic-ui';
import { store as blockEditorStore } from '@wordpress/block-editor';
import { Button } from '@wordpress/components';
import { __ } from '@wordpress/i18n';
import { useDispatch, useSelect } from '@wordpress/data';
import { useCallback, useEffect, useState } from '@wordpress/element';
import { square, undo } from '@wordpress/icons';
import { store as commandsStore } from '@wordpress/commands';
import { store as editorStore } from '@wordpress/editor';

/**
 * Internal dependencies
 */
import useCanvas from '@hooks/use-canvas.js';
import useCheckpoint from '@hooks/use-checkpoint';
import useFeedback from '@hooks/use-feedback.js';
import { store as aiStore } from '@store';
import { recordTracksEvent } from '@utils/tracks';
import useLog from '@hooks/use-log';
import { unlock } from '@utils/lock-unlock';
import { FeedbackInput } from './feedback-input.js';
import log from '@utils/log-debug.js';

import './style.scss';

export default function CompletedPlan( {
	onAfterRestoreCheckpoint = () => {},
	id,
} ) {
	const [ isInitiallyZoomedOut, setIsInitiallyZoomedOut ] = useState( false );
	const { zoomIn, zoomOut } = useCanvas();
	const {
		selectedFeedback,
		showFeedbackInput,
		handleFeedback,
		handleSubmitFeedback,
		handleCancelFeedback,
		isInternalTester,
	} = useFeedback( id );
	const { assistantSay } = useDispatch( aiStore );
	const { restoreCheckpoint } = useCheckpoint();
	const { logResponseAction } = useLog();
	const { close } = useDispatch( commandsStore );

	const { isInMosaicView } = useSelect( ( select ) => ( {
		isInMosaicView:
			select( commandsStore ).isOpen() &&
			select( editorStore ).getCurrentPostType() === 'page',
	} ) );

	const { isThinking } = useSelect( ( select ) => {
		return {
			isThinking: select( aiStore ).getIsThinking(),
		};
	}, [] );
	const zoomLevel = useSelect(
		( select ) => unlock( select( blockEditorStore ) ).getZoomLevel(),
		[]
	);

	const handleRestoreCheckpoint = useCallback( async () => {
		recordTracksEvent( 'restore_checkpoint_action', {
			id,
		} );

		logResponseAction( `Restore Checkpoint`, id );

		try {
			await restoreCheckpoint( id );

			try {
				// Handle callback even if async.
				await Promise.resolve( onAfterRestoreCheckpoint() );
			} catch ( error ) {
				// Avoid non-critical error from triggering false information
				// message.
				log.error( 'onAfterRestoreCheckpoint callback failed:', error );
			}
			// await assistantSay( __( "Ok, I've undone that.", 'big-sky' ) );
		} catch ( error ) {
			log.error( 'Failed to restore checkpoint:', error );
			assistantSay(
				__(
					"Sorry, I wasn't able to restore this checkpoint.",
					'big-sky'
				)
			);
		}
	}, [
		id,
		logResponseAction,
		restoreCheckpoint,
		onAfterRestoreCheckpoint,
		assistantSay,
	] );

	useEffect( () => {
		setIsInitiallyZoomedOut( zoomLevel < 1 );
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [] );

	const isZoomedOut = zoomLevel < 1;

	const showRestoreCheckpoint = useSelect(
		( select ) => {
			const checkpoint = select( aiStore ).getCheckpoint( id );
			return checkpoint?.checkpointKeys?.length > 0;
		},
		[ id ]
	);

	return (
		<>
			<div className="big-sky__completed-plan">
				{ showRestoreCheckpoint && (
					<Button
						label={ __( 'Restore to this point', 'big-sky' ) }
						icon={ undo }
						disabled={ isThinking }
						onClick={ handleRestoreCheckpoint }
						size="compact"
					/>
				) }
				<Button
					label={ __( 'Good response', 'big-sky' ) }
					icon={ ThumbsUpIcon }
					onClick={ () => handleFeedback( 'up' ) }
					disabled={ selectedFeedback === 'down' }
					isPressed={ selectedFeedback === 'up' }
					size="compact"
				/>
				<Button
					label={ __( 'Bad response', 'big-sky' ) }
					icon={ ThumbsDownIcon }
					onClick={ () => handleFeedback( 'down' ) }
					disabled={ selectedFeedback === 'up' }
					isPressed={ selectedFeedback === 'down' }
					size="compact"
				/>
				{ isInitiallyZoomedOut && (
					<Button
						label={
							isZoomedOut
								? __( 'Zoom in', 'big-sky' )
								: __( 'Zoom out', 'big-sky' )
						}
						icon={ square }
						onClick={ () => {
							if ( isZoomedOut ) {
								if ( isInMosaicView ) {
									close();
								}
								zoomIn();
							} else {
								zoomOut();
							}
						} }
						isPressed={ isZoomedOut }
						size="compact"
					/>
				) }
			</div>
			{ showFeedbackInput && isInternalTester && (
				<FeedbackInput
					onSubmit={ handleSubmitFeedback }
					onCancel={ handleCancelFeedback }
				/>
			) }
		</>
	);
}
