const isPickerComponent = ( componentProps ) => {
	return (
		componentProps?.type === 'site-layout-picker' ||
		componentProps?.type === 'pattern-picker' ||
		componentProps?.type === 'color-picker' ||
		componentProps?.type === 'font-picker' ||
		componentProps?.type === 'layout-picker'
	);
};

const isResponseActionsComponent = ( component ) => {
	return component?.type === 'response-actions';
};

/**
 * Check if a message contains a picker component
 *
 * @param {Object} message - The message object to check
 * @return {boolean} True if the message contains a picker component, false otherwise
 */
export const hasPickerComponent = ( message ) => {
	return (
		Array.isArray( message.content ) &&
		message.content.some( ( item ) => {
			if ( item.type !== 'component' ) return false;

			return isPickerComponent( item.componentProps );
		} )
	);
};

/**
 * Check if a message contains components that should be disabled on page change
 *
 * @param {Object} message - The message object to check
 * @return {boolean} True if the message contains components that should be disabled on page change
 */
export const isComponentToDisableOnPageChange = ( message ) => {
	if ( ! Array.isArray( message.content ) ) return false;

	return message.content.some( ( item ) => {
		if ( item.type !== 'component' ) return false;

		// Check if the component is a layout or pattern picker
		return (
			isPickerComponent( item.componentProps ) ||
			isResponseActionsComponent( item.componentProps )
		);
	} );
};

export const hasComponentInContent = ( content, component ) =>
	Array.isArray( content ) &&
	content.some(
		( item ) => item.type === 'component' && item.component === component
	);

/**
 * Merges consecutive picker + CompletedPlan message pairs into a single message.
 *
 * When a picker component (color-picker, font-picker, etc.) is immediately followed
 * by a CompletedPlan component, they are combined into one message to avoid
 * showing two separate bubbles. The merged message keeps the picker message's
 * id and timestamp.
 *
 * @param {Array}  messages               Array of message objects
 * @param {string} completedPlanComponent The CompletedPlan component name to match
 * @return {Array} Messages with picker + CompletedPlan pairs merged
 */
export const maybeMergeCompletedPlanMessage = (
	messages,
	completedPlanComponent
) => {
	const result = [];

	for ( let i = 0; i < messages.length; i++ ) {
		const msg = messages[ i ];
		const nextMsg = messages[ i + 1 ];

		if (
			hasPickerComponent( msg ) &&
			nextMsg &&
			hasComponentInContent( nextMsg.content, completedPlanComponent )
		) {
			// Merge the two messages: keep picker's id/timestamp, combine content
			result.push( {
				...msg,
				content: [ ...msg.content, ...nextMsg.content ],
			} );
			// Skip the CompletedPlan message since it's been merged
			i++;
		} else {
			result.push( msg );
		}
	}

	return result;
};
