/**
 * Agenttic UI Tracking Wrappers
 *
 * These functions wrap agenttic-ui callback props to add tracking events
 * while preserving the original functionality.
 */

import { recordTracksEvent } from '@utils/tracks';

/**
 * Wraps the onSubmit callback to track message submissions
 * @param {Function} originalOnSubmit - Original submit handler
 * @return {Function} Wrapped submit handler with tracking
 */
export function trackSubmit( originalOnSubmit ) {
	return ( message, options = {} ) => {
		recordTracksEvent( 'chat_input_send_message', {
			message_length: message?.length || 0,
			has_images: options?.images?.length > 0 || false,
		} );

		// Call the original handler
		return originalOnSubmit( message, options );
	};
}

/**
 * Formats suggestion IDs as a pipe-delimited string
 * @param {Array} suggestions - Array of suggestions with id property
 * @return {string} Pipe-delimited string of suggestion IDs (e.g., '|id1|id2|id3|')
 */
export function formatSuggestionIds( suggestions ) {
	return '|' + suggestions.map( ( s ) => s.id ).join( '|' ) + '|';
}

export function trackSuggestionsRendered( suggestions ) {
	recordTracksEvent( 'chat_suggestions_rendered', {
		suggestions: formatSuggestionIds( suggestions ),
	} );
}
/**
 * Tracks when a suggestion is clicked
 * @return {Function} Wrapped handler with tracking
 */
export function trackSuggestionClick() {
	return ( selectedSuggestion, availableSuggestions ) => {
		recordTracksEvent( 'chat_suggestion_click', {
			suggestion_text: selectedSuggestion.prompt || '',
			suggestion_id: selectedSuggestion.id || '',
			available_suggestions: formatSuggestionIds( availableSuggestions ),
		} );
	};
}

/**
 * Wraps the onClose callback to track chat close events
 * @param {Function} originalOnClose - Original close handler
 * @return {Function} Wrapped handler with tracking
 */
export function trackClose( originalOnClose ) {
	return () => {
		recordTracksEvent( 'dock_back_button_click' );
		return originalOnClose();
	};
}

