/**
 * Adds tracking to message actions
 * @param {Array} messages - Array of messages
 * @return {Array} Messages with tracking added to actions
 */
export function trackMessageActions( messages ) {
	return messages.map( ( message ) => {
		if ( ! message.actions || ! Array.isArray( message.actions ) ) {
			return message;
		}

		const trackedActions = message.actions.map( ( action ) => ( {
			...action,
			onClick: ( msg ) => {
				// Track the action click
				if ( action.type === 'thumbs-up' ) {
					recordTracksEvent( 'response_action_thumbs_up', {
						message_id: msg.id,
					} );
				} else if ( action.type === 'thumbs-down' ) {
					recordTracksEvent( 'response_action_thumbs_down', {
						message_id: msg.id,
					} );
				} else if ( action.type === 'restore-checkpoint' ) {
					recordTracksEvent( 'restore_checkpoint_action', {
						id: msg.id,
					} );
				} else {
					recordTracksEvent( 'chat_action_click', {
						action_type: action.type,
						action_id: action.id,
						message_id: msg.id,
					} );
				}

				// Call the original action
				return action.onClick( msg );
			},
		} ) );

		return {
			...message,
			actions: trackedActions,
		};
	} );
}

/**
 * Tracks input length errors (when message is too long)
 * @param {string} value     - Current input value
 * @param {number} maxLength - Maximum allowed length
 */
export function trackInputLengthError( value, maxLength ) {
	if ( value.length > maxLength ) {
		recordTracksEvent( 'chat_input_message_too_long', {
			message_length: value.length,
			max_length: maxLength,
		} );
	}
}

/**
 * Tracks error dismissal
 */
export function trackErrorDismissed() {
	recordTracksEvent( 'error_dismissed' );
}

/**
 * Tracks rate limit events
 */
export function trackRateLimit() {
	recordTracksEvent( 'rate_limit_show_exceeded_message' );
}

/**
 * Tracks rate limit plan selection
 */
export function trackRateLimitPlanClick() {
	recordTracksEvent( 'rate_limit_pick_plan' );
}
