/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';

/**
 * External dependencies
 */
import type { Ability } from '@wordpress/abilities';

/**
 * Set processing state ability callback type
 */
export type SetProcessingStateCallback = ( args: {
	clientId?: string;
	isNewPage?: boolean;
} ) => Promise< {
	result: string;
	returnToAgent: boolean;
} >;

/**
 * Set processing state ability
 *
 * Sets the processing state on a block and scrolls to it.
 * Used to indicate that a block is being actively processed/modified.
 *
 * @param callback - The set processing state callback function from the hook
 * @return The set processing state ability definition
 */
export const setProcessingStateAbility = (
	callback: SetProcessingStateCallback
): Ability => ( {
	name: 'big-sky/set-processing-state',
	label: __( 'Set Processing State', 'big-sky' ),
	category: 'big-sky',
	description: __(
		'Sets the processing state on a block and scrolls to it to indicate active processing',
		'big-sky'
	),
	input_schema: {
		type: 'object',
		properties: {
			clientId: {
				type: 'string',
				description:
					'The compressed client ID of the block to set processing state on',
			},
			isNewPage: {
				type: 'boolean',
				description:
					'Whether this is a new page (sets processing on core/post-content block)',
			},
			followUpTasks: {
				type: 'boolean',
				description:
					'Set to true if the user request has to be broken into multiple steps and other tasks remain to be done after this one.',
			},
		},
	},
	callback: async ( input ) => {
		return await callback( input );
	},
} );
