/**
 * WordPress dependencies
 */
import { close, moreVertical } from '@wordpress/icons';
import { __ } from '@wordpress/i18n';
import { Button, DropdownMenu } from '@wordpress/components';
import { Path, SVG } from '@wordpress/primitives';

/**
 * Internal dependencies
 */
import './style.scss';

const historyIcon = (
	<SVG
		xmlns="http://www.w3.org/2000/svg"
		width="15"
		height="15"
		viewBox="0 0 15 15"
		fill="none"
	>
		<Path d="M1.25 0C1.59518 0 1.875 0.279822 1.875 0.625L1.875 2.618C3.20897 1.13913 5.14168 0.208333 7.29167 0.208333C11.3187 0.208333 14.5833 3.47292 14.5833 7.5C14.5833 11.5271 11.3187 14.7917 7.29167 14.7917C3.26459 14.7917 0 11.5271 0 7.5C1.61065e-07 7.15482 0.279822 6.875 0.625 6.875C0.970178 6.875 1.25 7.15482 1.25 7.5C1.25 10.8367 3.95495 13.5417 7.29167 13.5417C10.6284 13.5417 13.3333 10.8367 13.3333 7.5C13.3333 4.16328 10.6284 1.45833 7.29167 1.45833C5.37238 1.45833 3.66206 2.35292 2.55452 3.75L5 3.75C5.34518 3.75 5.625 4.02982 5.625 4.375C5.625 4.72018 5.34518 5 5 5H0.625L0.625 0.625C0.625 0.279822 0.904822 0 1.25 0Z" />
		<Path d="M7.29167 4.16667C7.63684 4.16667 7.91667 4.44649 7.91667 4.79167L7.91667 7.35352L9.69645 8.42204C9.99236 8.59958 10.0887 8.98383 9.91129 9.27979C9.73375 9.57569 9.3495 9.67203 9.05355 9.49463L6.66667 8.06234L6.66667 4.79167C6.66667 4.44649 6.94649 4.16667 7.29167 4.16667Z" />
	</SVG>
);

const ChatHeader = ( {
	isChatDocked,
	onClose,
	options,
	onHistoryToggle,
	viewState,
	title,
	supportsHistory = true,
} ) => {
	return (
		<div className="big-sky-chat-header">
			{ title && (
				<div className="big-sky-chat-header__title">{ title }</div>
			) }
			<div className="big-sky-chat-header__actions">
				<DropdownMenu
					className="big-sky-chat-header__more-options"
					controls={ options }
					icon={ moreVertical }
					label={ __( 'More Options', 'big-sky' ) }
					toggleProps={ {
						size: ! isChatDocked ? 'small' : undefined,
					} }
				/>
				{ supportsHistory && onHistoryToggle && (
					<Button
						className="big-sky-chat-header__history-btn"
						icon={ historyIcon }
						onClick={ onHistoryToggle }
						label={
							viewState === 'history'
								? __( 'Back to chat', 'big-sky' )
								: __( 'View history', 'big-sky' )
						}
						size={ ! isChatDocked ? 'small' : undefined }
					/>
				) }
				<Button
					className="big-sky-chat-header__close-btn"
					icon={ close }
					onClick={ onClose }
					label={ __( 'Close', 'big-sky' ) }
					size={ ! isChatDocked ? 'small' : undefined }
				/>
			</div>
		</div>
	);
};

export default ChatHeader;
