/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';

/**
 * External dependencies
 */
import type { Ability } from '@wordpress/abilities';

/**
 * Navigate ability callback type
 */
export type NavigateCallback = ( args: {
	path: string;
	followUpTasks?: boolean;
} ) => Promise< {
	result: string;
	returnToAgent: boolean;
} >;

/**
 * Navigate ability
 *
 * Saves everything and navigates to the specified path.
 * Can also be used to navigate to a view that shows all the site's pages.
 *
 * @param callback - The navigate callback function from the hook
 * @return The navigate ability definition
 */
export const editorNavigateAbility = (
	callback: NavigateCallback
): Ability => ( {
	name: 'big-sky/editor-navigate',
	label: __( 'Navigate', 'big-sky' ),
	category: 'big-sky',
	description: __(
		'Saves everything and navigates to the specified path in the editor. Also be used to navigate to a view that shows all the sites pages so use this tool if the user asks to view all their pages.',
		'big-sky'
	),
	input_schema: {
		type: 'object',
		properties: {
			path: {
				type: 'string',
				description:
					'The path to navigate to (e.g., "/page/123", "/", "/page/contact"). If user asks to see all their pages set path to "all-pages"',
			},
			followUpTasks: {
				type: 'boolean',
				description:
					'Set to true if the user request has to be broken into multiple steps and other tasks remain to be done after this one.',
			},
		},
		required: [ 'path' ],
	},
	callback: async ( input ) => {
		return await callback( input );
	},
} );
