/**
 * WordPress dependencies
 */
import { useEffect, useRef, useState } from '@wordpress/element';
import {
	__unstableAnimatePresence as AnimatePresence,
	__unstableMotion as motion,
} from '@wordpress/components';

/**
 * Reusable animated text component for cycling through text content
 *
 * @param {Object}   props           - Component props
 * @param {Array}    props.texts     - Array of text strings to cycle through
 * @param {number}   props.interval  - Time in milliseconds between text changes (default: 3000)
 * @param {string}   props.className - CSS class name
 * @param {string}   props.element   - HTML element type (default: 'span')
 * @param {string}   props.animation - Animation preset: 'fade' or 'blur' (default: 'fade')
 * @param {Function} props.condition - Optional condition function to control when to show text
 */
export default function AnimatedText( {
	texts = [],
	interval = 3000,
	className = '',
	element = 'span',
	animation = 'fade',
	condition = () => true,
} ) {
	const [ currentIndex, setCurrentIndex ] = useState( 0 );
	const conditionRef = useRef( condition );

	conditionRef.current = condition;

	// Animation configurations
	const animationConfigs = {
		fade: {
			initial: { opacity: 0, y: 8 },
			animate: { opacity: 1, y: 0 },
			exit: { opacity: 0, y: -8 },
			transition: {
				duration: 0.3,
				ease: 'easeInOut',
			},
		},
		blur: {
			initial: { opacity: 0, y: 8, filter: 'blur(6px)' },
			animate: { opacity: 1, y: 0, filter: 'blur(0px)' },
			exit: { opacity: 0, y: -8, filter: 'blur(6px)' },
			transition: {
				duration: 0.4,
				ease: 'easeInOut',
				exit: {
					ease: 'easeInOut',
					filter: {
						delay: 0.5,
					},
				},
			},
		},
	};

	const currentAnimation =
		animationConfigs[ animation ] || animationConfigs.fade;

	useEffect( () => {
		if ( texts.length <= 1 ) return;

		const intervalId = setInterval( () => {
			if ( conditionRef.current() ) {
				setCurrentIndex(
					( prevIndex ) => ( prevIndex + 1 ) % texts.length
				);
			}
		}, interval );

		return () => clearInterval( intervalId );
	}, [ texts.length, interval ] );

	if ( ! condition() || texts.length === 0 ) {
		return null;
	}

	const MotionElement = motion[ element ];

	return (
		<AnimatePresence mode="wait">
			<MotionElement
				key={ currentIndex }
				className={ className }
				initial={ currentAnimation.initial }
				animate={ currentAnimation.animate }
				exit={ currentAnimation.exit }
				transition={ currentAnimation.transition }
			>
				{ texts[ currentIndex ] }
			</MotionElement>
		</AnimatePresence>
	);
}
