/**
 * WordPress dependencies
 */
import { useDispatch, useSelect } from '@wordpress/data';
import { store as blockEditorStore } from '@wordpress/block-editor';
import { memo, useCallback, useEffect } from '@wordpress/element';

/**
 * Internal dependencies
 */
import PatternPickerMenu from './pattern-picker';
import { createBlockRecursively } from '../apply-block-edits/utils';
import usePatterns from '@hooks/use-patterns';
import useBlocks from '@hooks/use-blocks';
import { TemplatePartPatternSlug } from '@utils/template-parts';

interface BlockData {
	name: string;
	attributes?: Record< string, unknown >;
	innerBlocks?: BlockData[];
	clientId?: string;
}

interface Pattern {
	blocks: BlockData[];
	category?: string;
}

interface Layout {
	id: string;
	patterns: Pattern[];
}

// Caches processed layouts across remounts (required for past conversations in the Calypso AI chat)
// Cache size is limited to prevent unbounded memory growth
const MAX_CACHE_SIZE = 30;
const layoutsCache = new Map< string, Layout[] >();

interface PatternPickerWrapperProps {
	layouts?: Layout[];
	clientId?: string;
	insertIndex?: number | null;
	isFullLayout?: boolean;
	newPageId?: string;
}

const PatternPickerWrapper = ( {
	layouts = [],
	clientId,
	insertIndex = null,
	isFullLayout,
	newPageId,
}: PatternPickerWrapperProps ): JSX.Element => {
	const { getBlock, getBlocksByName } = useSelect(
		( select ) => select( blockEditorStore ),
		[]
	);
	const { insertBlock } = useDispatch( blockEditorStore );
	const { insertPatterns } = usePatterns();
	const { setBlockIsProcessing, resetAllBlockIsProcessing } = useBlocks();

	const cacheKey = layouts[ 0 ]?.id ?? '';

	// Process all layouts and patterns concurrently
	const processLayouts = useCallback( async () => {
		// Process all layouts concurrently
		await Promise.all(
			layouts.map( async ( layout ) => {
				// Process all patterns in each layout concurrently
				await Promise.all(
					layout.patterns.map( async ( pattern ) => {
						// Process each block in the pattern
						const processedBlocks = await Promise.all(
							pattern.blocks.map( ( blockData ) =>
								createBlockRecursively( blockData )
							)
						);
						pattern.blocks = processedBlocks;
					} )
				);
			} )
		);

		// Clear processing state BEFORE inserting patterns
		// This ensures the first layout doesn't appear in processing state
		if ( newPageId ) {
			// Set the block processing state of the core/post-content block to false
			const postContentBlock = getBlocksByName( 'core/post-content' );
			if ( postContentBlock ) {
				setBlockIsProcessing(
					getBlock( postContentBlock[ 0 ] ),
					false
				);
			}
			// This is a full page layout, so we need to update the selected item with all patterns on canvas.
			insertPatterns( layouts[ 0 ].patterns, null, 'replace', false );
		} else if ( clientId && insertIndex !== null ) {
			// Clear processing state before inserting
			resetAllBlockIsProcessing();
			insertBlock(
				layouts[ 0 ].patterns[ 0 ].blocks[ 0 ],
				insertIndex,
				clientId
			);
		} else {
			setBlockIsProcessing( getBlock( clientId ), false );
		}
	}, [
		layouts,
		newPageId,
		clientId,
		insertIndex,
		setBlockIsProcessing,
		getBlock,
		insertPatterns,
		getBlocksByName,
		insertBlock,
		resetAllBlockIsProcessing,
	] );

	// Process layouts once and cache the result
	useEffect( () => {
		// Skip if already cached
		if ( cacheKey && layoutsCache.has( cacheKey ) ) {
			return;
		}

		// Always process layouts (even without a cache key)
		processLayouts();

		// Only cache if we have a valid cache key
		if ( cacheKey ) {
			// Evict oldest entry if cache is full (FIFO)
			if ( layoutsCache.size >= MAX_CACHE_SIZE ) {
				const oldestKey = layoutsCache.keys().next().value as string;
				layoutsCache.delete( oldestKey );
			}

			// `layouts` is mutated in place by `processLayouts()`, so the cache will contain processed layouts.
			layoutsCache.set( cacheKey, layouts );
		}
	}, [ cacheKey, layouts, processLayouts ] );

	// Clear processing state from target block after picker component mounts
	useEffect( () => {
		// Small delay to ensure the picker has fully rendered
		const timer = setTimeout( () => {
			if ( newPageId ) {
				const postContentBlock = getBlocksByName( 'core/post-content' );
				if ( postContentBlock?.[ 0 ] ) {
					const block = getBlock( postContentBlock[ 0 ] );
					if ( block ) {
						setBlockIsProcessing( block, false );
					}
				}
			} else if ( clientId ) {
				const block = getBlock( clientId );
				if ( block ) {
					setBlockIsProcessing( block, false );
				}
			}
		}, 100 );

		return () => clearTimeout( timer );
	}, [
		newPageId,
		clientId,
		getBlock,
		getBlocksByName,
		setBlockIsProcessing,
	] );

	// Use cached layouts (with WordPress block objects) for rendering
	const cachedLayouts = layoutsCache.get( cacheKey ) ?? layouts;
	const firstPattern = cachedLayouts[ 0 ]?.patterns[ 0 ] ?? {};

	return (
		<PatternPickerMenu
			key="pattern-picker"
			patterns={ cachedLayouts }
			clientId={
				insertIndex !== null
					? firstPattern.blocks?.[ 0 ]?.clientId
					: clientId
			}
			isHeroPattern={
				TemplatePartPatternSlug.HeaderHero === firstPattern.category
			}
			isFullLayout={ isFullLayout }
		/>
	);
};

export default memo( PatternPickerWrapper );
