export function getIsDevMode() {
	return (
		( typeof window !== 'undefined' &&
			!! window?.bigSkyInitialState?.isDevMode ) ||
		false
	);
}

export function getIsInternalTester() {
	return (
		( typeof window !== 'undefined' &&
			!! window?.bigSkyInitialState?.isInternalTester ) ||
		false
	);
}

export function getCurrentScreenContext() {
	if ( typeof window === 'undefined' ) {
		return null;
	}
	return window?.bigSkyInitialState?.currentScreen;
}

export function getIsFreeTrial() {
	if ( typeof window === 'undefined' ) {
		return false;
	}
	return window?.bigSkyInitialState?.isFreeTrial;
}

export function getSiteCount() {
	if ( typeof window === 'undefined' ) {
		return 1;
	}
	return window?.bigSkyInitialState?.siteCount || 1;
}
