/**
 * WordPress dependencies
 */
import { select } from '@wordpress/data';
import { createBlock } from '@wordpress/blocks';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store/index.js';
import placeholderImage from '@assets/placeholder.jpg';
import { imageCacheKeys } from '@utils/constants';

/**
 * Types
 */
interface BlockAttributes {
	className?: string;
	url?: string;
	alt?: string;
	[ key: string ]: unknown;
}

interface BlockData {
	name: string;
	attributes?: BlockAttributes;
	innerBlocks?: BlockData[];
}

interface CachedImage {
	url: string;
	alt?: string;
}

interface CachedContent {
	[ imageCacheKeys.IMAGES ]?: CachedImage[];
}

/**
 * Removes processing-related classes from a className string
 *
 * @param {string} className The className string to clean
 * @return {string} The cleaned className string
 */
const cleanProcessingClasses = ( className?: string ): string => {
	if ( ! className ) {
		return '';
	}
	return className
		.split( ' ' )
		.filter(
			( cn ) =>
				! cn.startsWith( 'big-sky__is-processing' ) &&
				! cn.startsWith( 'big-sky__has-processed' )
		)
		.join( ' ' );
};

/**
 * Creates a block and its inner blocks recursively
 *
 * @param {BlockData} blockData Block data including name, attributes, and innerBlocks
 * @return {Promise<Object>} A valid block with all inner blocks properly created
 */
export const createBlockRecursively = async (
	blockData: BlockData
): Promise< any > => {
	const cachedContent = select( aiStore ).getCachedContent() as
		| CachedContent
		| undefined;
	const cachedImages = cachedContent?.[ imageCacheKeys.IMAGES ] || [];

	// Create inner blocks first if they exist
	const processedInnerBlocks = blockData.innerBlocks?.length
		? await Promise.all(
				blockData.innerBlocks.map( createBlockRecursively )
		  )
		: [];

	// Clean any processing classes from the attributes before creating the block
	const cleanedAttributes: BlockAttributes = {
		...( blockData.attributes || {} ),
	};
	if ( cleanedAttributes.className ) {
		cleanedAttributes.className = cleanProcessingClasses(
			cleanedAttributes.className
		);
	}

	// Create the block with cleaned attributes
	const block = createBlock(
		blockData.name,
		cleanedAttributes,
		processedInnerBlocks
	);

	// Handle custom AI image generation for core/image blocks
	if (
		blockData.name === 'core/image' &&
		blockData.attributes?.url?.startsWith( 'ai-img-' )
	) {
		// Check if we have cached images available, and user hasn't asked for specific image.
		if (
			cachedImages.length > 0 &&
			cachedImages[ 0 ].url &&
			blockData.attributes?.url !== 'ai-img-n'
		) {
			const cachedImage = cachedImages[ 0 ];
			block.attributes.url = cachedImage.url;
			block.attributes.alt = cachedImage.alt || '';

			// Remove the cached image from the arrays so it's not reused
			if ( cachedImages.length > 0 ) {
				cachedImages.shift();
			}
		} else {
			// No cached images available, use placeholder
			block.attributes.url = placeholderImage;
		}
	}

	return block;
};
