/**
 * WordPress dependencies
 */
import { useDispatch, useSelect } from '@wordpress/data';
import { useEffect } from '@wordpress/element';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import useIsThinking from '@hooks/use-is-thinking';

import {
	createSuggestionClickHandler,
	formatSuggestionAction,
	useSuggestionManagement,
} from '@hooks/use-suggestion-management.js';
import ChatActionsView from '@components/chat/actions/chat-actions-view';

export function ChatSuggestions( { args, respond } ) {
	const { suggestions: storeSuggestions } = useSelect( ( select ) => ( {
		suggestions: select( aiStore ).getSuggestions(),
	} ) );
	const { clearSuggestions, setHasRetriedChatRequest, logUserChoice } =
		useSuggestionManagement();
	const { assistantSay, userSay } = useDispatch( aiStore );
	const { isThinking = false } = useIsThinking() || {};

	// Use args if provided, otherwise use suggestions from store
	const suggestions = args || storeSuggestions;

	useEffect( () => {
		const message = args?.message || suggestions?.message;
		if ( message ) {
			assistantSay( suggestions.message );
		}
	}, [ assistantSay, suggestions, args ] );

	if (
		isThinking ||
		! suggestions?.actions ||
		suggestions.actions.length === 0
	) {
		return null;
	}

	const actionsToUse = suggestions.actions.map( ( action ) => {
		const formattedAction = formatSuggestionAction( action );
		return {
			...formattedAction,
			onClick:
				action.onClick ||
				createSuggestionClickHandler( {
					logUserChoice,
					clearSuggestions,
					setHasRetried: setHasRetriedChatRequest,
					respond,
					userSay,
					action: formattedAction,
					shouldClear: ! args,
				} ),
		};
	} );

	return (
		<ChatActionsView
			key={ actionsToUse.map( ( action ) => action.key ).join( '-' ) }
			actions={ actionsToUse }
			animationVariants={ {
				initial: { opacity: 0, y: 0 },
				animate: { opacity: 1, y: 0 },
				exit: { opacity: 0, y: 10 },
				transition: {
					ease: [ 0.42, 0.24, 0.02, 1 ],
					duration: 1,
					delay: 0.05,
				},
			} }
		/>
	);
}
