/**
 * External dependencies
 */
import classnames from 'classnames';
import { __ } from '@wordpress/i18n';
import ProgressBar from '@components/onboarding/progress-bar/index.js';
import { useMemo } from '@wordpress/element';
import { useSelect } from '@wordpress/data';
import { store as aiStore } from '@store';
import BigSkyIcon from '@components/big-sky-icon';

/**
 * Internal dependencies
 */
import AnimatedText from '@components/animated-text';
import './style.scss';

export default function OnboardingBuildingView( { isCiab } ) {
	const tips = useMemo(
		() => [
			__( 'Use a modern font', 'big-sky' ),
			__( 'Refine the typography to feel more professional', 'big-sky' ),
			__( 'Show me earthy colors', 'big-sky' ),
			__( 'Add a contact page', 'big-sky' ),
			__( 'Add testimonials to the page', 'big-sky' ),
			__( 'Link my Instagram feed', 'big-sky' ),
			__( 'Create an ‘About’ page', 'big-sky' ),
			__( 'Add a map with my address', 'big-sky' ),
		],
		[]
	);

	const buildProgress = useSelect( ( select ) =>
		select( aiStore ).getBuildProgress()
	);

	// Create all possible texts based on build progress
	const allTexts = useMemo( () => {
		return tips.map( ( tip ) => `"${ tip }"` );
	}, [ tips ] );

	return (
		<div
			className={ classnames( 'big-sky-onboarding__building-view', {
				'big-sky-onboarding__building-view--ciab': isCiab,
			} ) }
		>
			<div className="big-sky-onboarding__building-content">
				{ ! isCiab && (
					<div className="big-sky-onboarding__ai-icon">
						<BigSkyIcon width={ 64 } height={ 64 } color="white" />
					</div>
				) }
				<div className="big-sky-onboarding__title">
					{ isCiab
						? __(
								'Please wait, we are setting up your store',
								'big-sky'
						  )
						: __( 'Please wait, your site is brewing', 'big-sky' ) }
				</div>
				<div className="big-sky-onboarding__progress-container">
					<ProgressBar value={ buildProgress } compact />
				</div>
				<div className="big-sky-onboarding__helper-text">
					{ __(
						'Here are examples you can ask the assistant…',
						'big-sky'
					) }
				</div>
				<AnimatedText
					texts={ allTexts }
					className="big-sky-onboarding__placeholder"
					animation="blur"
					interval={ 4000 }
				/>
			</div>
		</div>
	);
}
