import { PureComponent } from '@wordpress/element';

import './style.scss';

export default class ProgressBar extends PureComponent {
	static defaultProps = {
		total: 100,
		compact: false,
		isPulsing: false,
		canGoBackwards: false,
	};

	static getDerivedStateFromProps( props, state ) {
		return {
			allTimeMax: Math.max( state.allTimeMax, props.value ),
		};
	}

	state = {
		allTimeMax: this.props.value,
	};

	getCompletionPercentage() {
		const percentage = Math.ceil(
			( ( this.props.canGoBackwards
				? this.props.value
				: this.state.allTimeMax ) /
				this.props.total ) *
				100
		);

		// The percentage should not be allowed to be more than 100
		return Math.min( percentage, 100 );
	}

	renderBar() {
		const { color, title, total, value, style } = this.props;

		let styles = {
			width: this.getCompletionPercentage() + '%',
		};
		if ( color ) {
			styles.backgroundColor = color;
		}
		if ( style ) {
			styles = { ...styles, ...style };
		}

		return (
			<div
				aria-valuemax={ total }
				aria-valuemin={ 0 }
				aria-valuenow={ value }
				aria-label="progress bar"
				className="progress-bar__progress"
				role="progressbar"
				style={ styles }
			>
				{ title }
			</div>
		);
	}

	render() {
		const className = [ 'progress-bar' ];

		if ( this.props.className ) {
			className.push( this.props.className );
		}
		if ( this.props.compact ) {
			className.push( 'is-compact' );
		}
		if ( this.props.isPulsing ) {
			className.push( 'is-pulsing' );
		}

		return (
			<div className={ className.join( ' ' ) }>{ this.renderBar() }</div>
		);
	}
}
