/**
 * External dependencies
 */
import deepmerge from 'deepmerge';

/**
 * WordPress dependencies
 */
import { useCallback } from '@wordpress/element';
import { useDispatch, useRegistry, useSelect } from '@wordpress/data';
import { store as coreStore } from '@wordpress/core-data';

/**
 * Internal dependencies
 */
// @TODO: move the constant prefix here after cleaning up the custom color variations code
import { BIG_SKY_CUSTOM_THEME_PREFIX } from '@utils/custom-color-variations/constants';
import { store as aiStore } from '@store/index.js';

/**
 * Normalizes a value to a plain object.
 * Guards against arrays or non-object types that would break deepmerge.
 *
 * @param {*} value - The value to normalize
 * @return {Object|undefined} A plain object, or undefined if the input was falsy
 */
function normalizeToObject( value ) {
	if ( ! value ) {
		return undefined;
	}
	if ( Array.isArray( value ) || typeof value !== 'object' ) {
		return {};
	}
	return value;
}

/**
 * Merges a theme update with the current theme
 * @param {Object} currentTheme - The current theme object
 * @param {Object} themeUpdate  - The theme update to merge
 * @return {Object} The merged theme object
 */
function mergeThemeUpdate( currentTheme, themeUpdate ) {
	// Convert flat color palette to proper WordPress structure if needed
	const normalizedThemeUpdate = { ...themeUpdate };
	if (
		themeUpdate.settings?.color?.palette &&
		Array.isArray( themeUpdate.settings.color.palette )
	) {
		// Convert flat palette array to WordPress Global Styles structure
		normalizedThemeUpdate.settings = {
			...themeUpdate.settings,
			color: {
				...themeUpdate.settings.color,
				palette: {
					custom: themeUpdate.settings.color.palette,
				},
			},
		};
	}

	// Smart merge strategy for color palettes - merge by slug, preserve existing colors
	const mergeOptions = {
		arrayMerge: ( destinationArray, sourceArray ) => {
			// For color palettes, merge by slug - update existing or add new
			if ( sourceArray?.[ 0 ]?.slug && sourceArray?.[ 0 ]?.color ) {
				const result = [ ...destinationArray ];
				sourceArray.forEach( ( newColor ) => {
					const existingIndex = result.findIndex(
						( existing ) => existing.slug === newColor.slug
					);
					if ( existingIndex >= 0 ) {
						// Update existing color
						result[ existingIndex ] = newColor;
					} else {
						// Add new color
						result.push( newColor );
					}
				} );
				return result;
			}
			// For non-color arrays, use simple replacement
			return sourceArray;
		},
	};

	// Deep merge the theme update with the current theme
	const mergedTheme = deepmerge(
		currentTheme || {},
		normalizedThemeUpdate,
		mergeOptions
	);

	// Ensure variations are preserved if they exist
	if (
		currentTheme?.styles?.blocks?.[ 'core/group' ]?.variations &&
		! normalizedThemeUpdate.styles?.variations
	) {
		mergedTheme.styles = mergedTheme.styles || {};
		mergedTheme.styles.variations =
			currentTheme.styles.blocks[ 'core/group' ].variations;
	}

	return mergedTheme;
}

/**
 * Helper function to get flattened color palette from WordPress Global Styles structure
 * @param {Object} palette - The palette object with theme/custom/core structure
 * @return {Array} Flattened array of color objects
 */
function getFlattenedPalette( palette ) {
	if ( Array.isArray( palette ) ) {
		return palette;
	}

	if ( typeof palette === 'object' && palette ) {
		const colors = [];
		// Collect colors from all categories in order: theme, custom, core
		if ( palette.theme ) colors.push( ...palette.theme );
		if ( palette.custom ) colors.push( ...palette.custom );
		if ( palette.core ) colors.push( ...palette.core );
		return colors;
	}

	return [];
}

/**
 * Hook that provides theme updating functionality
 *
 * @return {Function} updateTheme function that accepts theme update objects
 */
export function useUpdateTheme() {
	// Get all necessary dependencies internally
	const registry = useRegistry();
	const { pushGeneratedVariations, setCurrentPaletteColors } =
		useDispatch( aiStore );
	const { editEntityRecord } = useDispatch( coreStore );

	const { globalStylesId, getEditedEntityRecord } = useSelect( ( select ) => {
		const core = select( coreStore );
		return {
			globalStylesId: core.__experimentalGetCurrentGlobalStylesId(),
			getEditedEntityRecord: core.getEditedEntityRecord,
		};
	}, [] );

	const getCurrentTheme = useCallback( () => {
		return getEditedEntityRecord( 'root', 'globalStyles', globalStylesId );
	}, [ getEditedEntityRecord, globalStylesId ] );

	/**
	 * Updates theme with provided theme update object
	 *
	 * @param {Object} themeUpdate          - Object containing settings and/or styles to merge
	 * @param {Object} themeUpdate.settings - Theme settings to merge (optional)
	 * @param {Object} themeUpdate.styles   - Theme styles to merge (optional)
	 * @return {Promise<boolean>} Promise that resolves to true if theme is updated, false if validation fails
	 */
	const updateTheme = async ( themeUpdate ) => {
		// Validate that themeUpdate has at least one of the required keys
		if (
			! themeUpdate ||
			( ! themeUpdate.settings && ! themeUpdate.styles )
		) {
			return false;
		}

		// Normalize settings and styles to plain objects.
		// The backend may send an empty array [] instead of an object {},
		// which causes deepmerge to replace the entire settings object.
		themeUpdate.settings = normalizeToObject( themeUpdate.settings );
		themeUpdate.styles = normalizeToObject( themeUpdate.styles );

		// Re-validate after normalization (both could have been non-object truthy values)
		if ( ! themeUpdate.settings && ! themeUpdate.styles ) {
			return false;
		}

		// Get current theme from edited entity record (includes all session changes)
		// This preserves previously added colors that haven't been saved yet
		const currentTheme = JSON.parse(
			JSON.stringify( getCurrentTheme() || {} )
		);

		// Merge the theme update with the current session theme
		const mergedTheme = mergeThemeUpdate( currentTheme, themeUpdate );

		registry.batch( () => {
			// Set the theme title to make it a custom variation
			mergedTheme.title = BIG_SKY_CUSTOM_THEME_PREFIX;

			// Update entity record with merged theme
			editEntityRecord(
				'root',
				'globalStyles',
				globalStylesId,
				{
					title: BIG_SKY_CUSTOM_THEME_PREFIX,
					settings: mergedTheme.settings || {},
					styles: mergedTheme.styles || {},
				},
				{ undoIgnore: true }
			);

			// Add the custom variation to the generated variations (session-only)
			pushGeneratedVariations( [ mergedTheme ] );

			// Update current palette colors in the store for immediate UI refresh
			if ( mergedTheme?.settings?.color?.palette ) {
				// Get flattened palette array for store update
				const flattenedPalette = getFlattenedPalette(
					mergedTheme.settings.color.palette
				);
				setCurrentPaletteColors( flattenedPalette );
			}
		} );

		return true;
	};

	return updateTheme;
}
