/**
 * WordPress dependencies
 */
import { useEffect, useState } from '@wordpress/element';
import { useSelect } from '@wordpress/data';
import { __ } from '@wordpress/i18n';
import { Button, ExternalLink, Modal } from '@wordpress/components';
import { privateApis as routerPrivateApis } from '@wordpress/router';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import { getIsFreeTrial } from '@utils/env';
import { getPlanSelectionLink } from '@utils/links';
import { recordTracksEvent } from '@utils/tracks';
import { FREE_TRIAL_UPGRADE_REASON } from '@utils/constants';
import { unlock } from '@utils/lock-unlock';
import useSiteMetadata from '@hooks/use-site-metadata';
import useSaveEverything, {
	useIsSavingEverything,
} from '@hooks/use-save-everything';
import {
	CircleCheck as CircleCheckIcon,
	WordPressDotCom as WordPressDotComIcon,
} from '@components/icons';
import './style.scss';

const { useHistory } = unlock( routerPrivateApis );

// This hook injects the launch button after the publish button.
function useInjectFreeTrialLaunchButton( { setIsModalOpen, setReason } ) {
	const saveEverything = useSaveEverything();
	const isFreeTrial = getIsFreeTrial();
	const isEditorIframeLoaded = useSelect(
		( select ) => select( aiStore ).getIsEditorIframeLoaded(),
		[]
	);
	useEffect( () => {
		if ( ! isFreeTrial || ! isEditorIframeLoaded ) {
			return;
		}
		// add a launch button after a specific element in the DOM
		const element = document.querySelector( '.editor-post-publish-button' );
		// don't append to the element, but insert it after it
		if ( element ) {
			// Remove is-primary class from publish button
			element.classList.remove( 'is-primary' );
			element.classList.add( 'is-secondary' );

			const launchButton = document.createElement( 'button' );
			launchButton.classList.add(
				'components-button',
				'editor-post-launch-button',
				'is-primary',
				'is-compact'
			);
			launchButton.textContent = __( 'Launch', 'big-sky' );
			launchButton.addEventListener( 'click', () => {
				saveEverything();
				setIsModalOpen( true );
				setReason( FREE_TRIAL_UPGRADE_REASON.LAUNCH_BUTTON_CLICK );
				recordTracksEvent( 'show_free_trial_paywall', {
					reason: FREE_TRIAL_UPGRADE_REASON.LAUNCH_BUTTON_CLICK,
				} );
			} );
			element.parentNode.insertBefore(
				launchButton,
				element.nextSibling
			);
			return () => {
				launchButton.remove();
			};
		}
	}, [
		isFreeTrial,
		isEditorIframeLoaded,
		setIsModalOpen,
		setReason,
		saveEverything,
	] );
}

export default function Paywall() {
	const history = useHistory();
	const isSaving = useIsSavingEverything();
	const { getSiteMetadata } = useSiteMetadata();
	const [ isModalOpen, setIsModalOpen ] = useState( false );
	// Track how the paywall was triggered
	const [ reason, setReason ] = useState( null );

	const isRedirectGate = reason === FREE_TRIAL_UPGRADE_REASON.REDIRECTED;
	const isLaunch = reason === FREE_TRIAL_UPGRADE_REASON.LAUNCH_BUTTON_CLICK;

	useInjectFreeTrialLaunchButton( { setIsModalOpen, setReason } );

	// Check for URL parameter and initialize paywall if needed
	useEffect( () => {
		const urlParams = new URLSearchParams( window.location.search );
		const hasTrialParam = urlParams.has( 'ai-website-builder-trial' );

		if ( hasTrialParam ) {
			setIsModalOpen( true );
			setReason( FREE_TRIAL_UPGRADE_REASON.REDIRECTED );
			recordTracksEvent( 'show_free_trial_paywall', {
				reason: FREE_TRIAL_UPGRADE_REASON.REDIRECTED,
			} );
		}
	}, [ setIsModalOpen ] );

	// Handle modal close
	const handleRequestClose = async () => {
		setIsModalOpen( false );
		recordTracksEvent( 'paywall_dismiss', {
			reason,
		} );
		setReason( null );

		// Clean up URL parameter if present
		if ( reason === FREE_TRIAL_UPGRADE_REASON.REDIRECTED ) {
			const url = new URL( window.location );
			url.searchParams.delete( 'ai-website-builder-trial' );

			const next = url.toString();
			const prev = window.location.href;

			// This should always be true, but just to be safe.
			if ( next !== prev ) {
				// Replace the current history entry so the back button doesn't return to the paywall state. Still leaves an extra entry in the history.
				window.history.replaceState( {}, '', url );

				// Use WordPress router to navigate to the clean URL so the site editor behaves correctly.
				await history.navigate( url.pathname + url.search + url.hash );
			}
		}
	};

	const handleCtaClick = () => {
		recordTracksEvent( 'paywall_upgrade', {
			reason,
			target_page: 'domains',
		} );

		const redirectTo = isLaunch ? 'site-launch' : undefined;
		const siteTitle =
			getSiteMetadata().siteTitle || __( 'Your Site', 'big-sky' );
		const flow = isRedirectGate ? undefined : 'plan-domain';

		window.location.href = getPlanSelectionLink(
			redirectTo,
			siteTitle,
			flow
		);
	};

	const handleManageSitesClick = () => {
		recordTracksEvent( 'paywall_sites', { reason } );
	};

	// Early return if paywall shouldn't be shown
	if ( ! getIsFreeTrial() || ! isModalOpen ) {
		return null;
	}

	const modalTitle = isRedirectGate
		? __( 'Get full access', 'big-sky' )
		: __( 'Launch your site', 'big-sky' );

	const subtitle = isRedirectGate
		? __(
				'Upgrade to access all publishing, growth, and support tools.',
				'big-sky'
		  )
		: __(
				'Choose a plan to go live and share your website. Edit anytime.',
				'big-sky'
		  );

	const planBenefits = [
		! isRedirectGate && {
			title: __( 'Public and shareable instantly', 'big-sky' ),
		},
		{ title: __( 'Free domain for one year', 'big-sky' ) },
		{ title: __( 'Unlimited AI edits', 'big-sky' ) },
		{ title: __( 'Install plugins', 'big-sky' ) },
		{ title: __( 'Expert customer support', 'big-sky' ) },
	].filter( Boolean );

	return (
		<Modal
			contentLabel={ modalTitle } // For a11y
			onRequestClose={ handleRequestClose }
			className="big-sky-paywall-modal"
			isDismissible
			shouldCloseOnClickOutside={ false }
			size="small"
		>
			<div className="big-sky-paywall-modal__content">
				<WordPressDotComIcon aria-hidden="true" />
				<h2 className="big-sky-paywall-modal__title">{ modalTitle }</h2>
				<p className="big-sky-paywall-modal__subtitle">{ subtitle }</p>
				<ul className="big-sky-paywall-modal__plan-benefit-list">
					{ planBenefits.map( ( benefit, idx ) => (
						<li
							key={ idx }
							className="big-sky-paywall-modal__plan-benefit-item"
						>
							<CircleCheckIcon
								className="big-sky-paywall-modal__circle-check-icon"
								aria-hidden="true"
							/>
							<span className="big-sky-paywall-modal__plan-benefit-title">
								{ benefit.title }
							</span>
						</li>
					) ) }
				</ul>
				<div className="big-sky-paywall-modal__actions">
					<Button
						className="big-sky-paywall-modal__cta"
						variant="primary"
						onClick={ handleCtaClick }
						disabled={ isSaving }
						accessibleWhenDisabled
						data-testid="big-sky-paywall-modal-cta"
					>
						{ __( 'Choose a plan', 'big-sky' ) }
					</Button>
					<ExternalLink
						className="big-sky-paywall-modal__manage-sites"
						href="https://wordpress.com/sites"
						onClick={ handleManageSitesClick }
					>
						{ __( 'Manage sites', 'big-sky' ) }
					</ExternalLink>
				</div>
			</div>
		</Modal>
	);
}
