import type { Ability } from '@wordpress/abilities';

/**
 * Edit entity record ability callback type
 */
export type EditEntityRecordCallback = ( args: {
	addEntities?: Array< {
		entityType: string;
		entityName: string;
		record: Record< string, any >;
		options?: Record< string, any >;
	} >;
	editEntities?: Array< {
		entityType: string;
		entityName: string;
		recordId: number | string;
		record: Record< string, any >;
		options?: Record< string, any >;
	} >;
	deleteEntities?: Array< {
		entityType: string;
		entityName: string;
		recordId: number | string;
		options?: Record< string, any >;
	} >;
	confirmationMessage?: string | null;
} ) => Promise< {
	result: string;
	returnToAgent: boolean;
} >;

