/**
 * Internal dependencies
 */
import './style.scss';
import ActionCarousel from './action-carousel.js';

export default function ChatActionsView( {
	actions = [],
	animationVariants = {},
	showSpotlight = false,
} ) {
	if ( ! actions?.length ) {
		return null;
	}

	return (
		<ActionCarousel
			key={ actions[ 0 ]?.key }
			actions={ actions }
			animationVariants={ animationVariants }
			showSpotlight={ showSpotlight }
		/>
	);
}
