/**
 * Feedback Input Component
 * Allows internal testers to submit feedback messages after clicking thumbs down
 */

import { useEffect, useRef, useState } from '@wordpress/element';
import { __ } from '@wordpress/i18n';
import { Button, Spinner, TextareaControl } from '@wordpress/components';
import log from '@utils/log-debug.js';
import './feedback-input.scss';

export function FeedbackInput( { onSubmit, onCancel } ) {
	const [ feedbackText, setFeedbackText ] = useState( '' );
	const [ isSubmitting, setIsSubmitting ] = useState( false );
	const [ submitSuccess, setSubmitSuccess ] = useState( false );
	const [ submitError, setSubmitError ] = useState( null );
	const timeoutRef = useRef( null );

	// Cleanup timeout on unmount
	useEffect( () => {
		return () => {
			if ( timeoutRef.current ) {
				clearTimeout( timeoutRef.current );
			}
		};
	}, [] );

	const handleSubmit = async () => {
		if ( ! feedbackText.trim() ) {
			return;
		}

		setIsSubmitting( true );

		try {
			await onSubmit( feedbackText.trim() );
			setFeedbackText( '' );
			setSubmitSuccess( true );

			// Hide form after showing success message for 2 seconds
			timeoutRef.current = setTimeout( () => {
				onCancel();
			}, 2000 );
		} catch ( error ) {
			log.error( 'Error submitting feedback:', error );
			setSubmitError(
				__( 'Failed to submit feedback. Please try again.', 'big-sky' )
			);

			// Hide form after showing error message for 2 seconds
			timeoutRef.current = setTimeout( () => {
				onCancel();
			}, 2000 );
		} finally {
			setIsSubmitting( false );
		}
	};

	const handleKeyDown = ( event ) => {
		// Submit on Cmd/Ctrl + Enter
		if (
			( event.metaKey || event.ctrlKey ) &&
			event.key === 'Enter' &&
			! event.shiftKey
		) {
			event.preventDefault();
			handleSubmit();
		}
		// Cancel on Escape
		if ( event.key === 'Escape' ) {
			onCancel();
		}
	};

	// Show success message
	if ( submitSuccess ) {
		return (
			<div className="orchestrator-feedback-input-container">
				<div className="orchestrator-feedback-input">
					<div className="orchestrator-feedback-input__success">
						{ __( 'Feedback submitted successfully!', 'big-sky' ) }
					</div>
				</div>
			</div>
		);
	}

	// Show error message
	if ( submitError ) {
		return (
			<div className="orchestrator-feedback-input-container">
				<div className="orchestrator-feedback-input">
					<div className="orchestrator-feedback-input__error">
						{ submitError }
					</div>
				</div>
			</div>
		);
	}

	// Show form
	return (
		<div className="orchestrator-feedback-input-container">
			<div className="orchestrator-feedback-input">
				<TextareaControl
					label={ __(
						'What could be improved? (A12s only)',
						'big-sky'
					) }
					value={ feedbackText }
					onChange={ ( value ) => setFeedbackText( value ) }
					onKeyDown={ handleKeyDown }
					placeholder={ __(
						'Help us understand what you expected or what went wrong.',
						'big-sky'
					) }
					rows={ 3 }
					disabled={ isSubmitting }
				/>
				<div className="orchestrator-feedback-input__actions">
					<Button
						variant="tertiary"
						onClick={ onCancel }
						disabled={ isSubmitting }
					>
						{ __( 'Cancel', 'big-sky' ) }
					</Button>
					<Button
						variant="primary"
						onClick={ handleSubmit }
						disabled={ ! feedbackText.trim() || isSubmitting }
					>
						{ isSubmitting && (
							<Spinner
								style={ {
									height: '16px',
									width: '16px',
								} }
							/>
						) }
						{ isSubmitting
							? __( 'Submitting…', 'big-sky' )
							: __( 'Submit', 'big-sky' ) }
					</Button>
				</div>
			</div>
		</div>
	);
}
