/**
 * WordPress dependencies
 */
import { useSelect, select as wpSelect } from '@wordpress/data';
import { store as blockEditorStore } from '@wordpress/block-editor';

/**
 * Internal dependencies
 */
import useBlocks from '@hooks/use-blocks.js';
import { scrollToBlock } from '@utils/block-dom';
import { localToolRunningMessage } from '@utils/constants';
import { store as aiStore } from '@store';

/**
 * Types
 */
interface SetProcessingStateArgs {
	clientId?: string;
	isNewPage?: boolean;
}

interface SetProcessingStateResult {
	result: string;
	returnToAgent: boolean;
	agentMessage?: string;
}

interface ClientIdMap {
	[ key: string ]: string;
}

interface Block {
	clientId: string;
	name: string;
	[ key: string ]: unknown;
}

export default function useSetProcessingStateTool() {
	const { setBlockIsProcessing } = useBlocks();
	const { getBlock, getBlocksByName } = useSelect(
		( select ) => select( blockEditorStore ),
		[]
	) as {
		getBlock: ( clientId: string ) => Block | null;
		getBlocksByName: ( blockName: string ) => string[];
	};

	// Get clientIdMap from store (instead of it being injected via args)
	const clientIdMap = useSelect(
		( select ) =>
			select( aiStore ).getFullPageStructure()?.clientIdMap || {},
		[]
	) as ClientIdMap;

	const setProcessingState = async (
		args: SetProcessingStateArgs
	): Promise< SetProcessingStateResult > => {
		const { clientId, isNewPage } = args;

		// Use clientIdMap from hook closure as reverseMap
		const reverseMap = clientIdMap;

		let blockClientId: string | undefined;
		if ( isNewPage ) {
			// set processing state on the core/post-content block
			const postContentBlock = getBlocksByName( 'core/post-content' );
			blockClientId = postContentBlock[ 0 ];
		} else {
			blockClientId = clientId ? reverseMap[ clientId ] : undefined;
		}

		// Hidden from the chat UI by Agents Manager.
		const isUnifiedExperience =
			wpSelect( aiStore ).getIsUnifiedChatEnabled();
		const agentMessage = isUnifiedExperience
			? localToolRunningMessage
			: undefined;

		// get the block from the reverseMap
		if ( ! blockClientId ) {
			return {
				result: 'Block could not be found, but continue with the request.',
				returnToAgent: true,
				agentMessage,
			};
		}

		// get the block
		const block = getBlock( blockClientId );
		if ( ! block ) {
			return {
				result: 'Block could not be found, but continue with the request.',
				returnToAgent: true,
				agentMessage,
			};
		}

		// scroll to the block
		scrollToBlock( blockClientId, 'start', false, 50 );

		// set the processing state of the block
		setBlockIsProcessing( block, true );

		// return the result
		return {
			result: 'Processing state has been set, continue with the request.',
			returnToAgent: true,
			agentMessage,
		};
	};

	return {
		setProcessingState,
	};
}
