/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';
import { useDispatch } from '@wordpress/data';

/**
 * Internal dependencies
 */
import { useUpdateTheme } from '@hooks/use-update-theme';
import { store as aiStore } from '@store';
import useCheckpoint from '@hooks/use-checkpoint';
import { checkpointKeys } from '@utils/constants';
import showResponseActions from '@utils/show-completed-plan';
import uuidv4 from '@utils/uuid';

/**
 * Types
 */
interface ColorPaletteItem {
	color: string;
	name: string;
	slug: string;
}

interface FontFamily {
	fontFamily: string;
	name: string;
	slug: string;
}

interface FontSize {
	size: string;
	name: string;
	slug: string;
}

interface ThemeSettings {
	color?: {
		palette?: ColorPaletteItem[];
		[ key: string ]: unknown;
	};
	typography?: {
		fontFamilies?: FontFamily[];
		fontSizes?: FontSize[];
		[ key: string ]: unknown;
	};
	[ key: string ]: unknown;
}

interface ThemeStyles {
	[ key: string ]: unknown;
}

interface UpdateThemeArgs {
	settings?: ThemeSettings;
	styles?: ThemeStyles;
	followUpTasks?: boolean;
}

interface UpdateThemeResult {
	result: string;
	returnToAgent: boolean;
}

interface ThemeUpdate {
	settings?: ThemeSettings;
	styles?: ThemeStyles;
}

export default function useUpdateThemeTool(): {
	updateTheme: ( args: UpdateThemeArgs ) => Promise< UpdateThemeResult >;
} {
	const updateTheme = useUpdateTheme();
	const { setCheckpoint, getLatestUserMessageId, addCheckpointKeys } =
		useCheckpoint();
	const { assistantSay, changeCheckpointId } = useDispatch( aiStore ) as {
		assistantSay: (
			message: string
		) => Promise< { message: { id: string } } >;
		changeCheckpointId: ( oldId: string, newId: string ) => void;
	};

	const updateThemeSettings = async (
		args: UpdateThemeArgs
	): Promise< UpdateThemeResult > => {
		const { settings, styles, followUpTasks } = args || {};
		const failMessage = __(
			'Failed to make the theme update. Please try again.',
			'big-sky'
		);

		// Validate that at least one of settings or styles is provided
		if ( ! settings && ! styles ) {
			assistantSay( failMessage );
			return {
				result: __(
					'Invalid arguments. Provide either settings or styles to update the theme.',
					'big-sky'
				),
				returnToAgent: followUpTasks ?? false,
			};
		}

		// Validate settings structure if provided
		if ( settings && typeof settings !== 'object' ) {
			assistantSay( failMessage );
			return {
				result: __(
					'Invalid settings format. Settings must be an object.',
					'big-sky'
				),
				returnToAgent: followUpTasks ?? false,
			};
		}

		// Validate styles structure if provided
		if ( styles && typeof styles !== 'object' ) {
			assistantSay( failMessage );
			return {
				result: __(
					'Invalid styles format. Styles must be an object.',
					'big-sky'
				),
				returnToAgent: followUpTasks ?? false,
			};
		}

		try {
			// Create a checkpoint before theme changes for undo support
			// Use the latest user message ID if available, otherwise generate a unique ID
			const messageId = getLatestUserMessageId();
			const checkpointId = messageId || `theme-update-${ uuidv4() }`;
			setCheckpoint( checkpointId, [ checkpointKeys.COLOR ] );

			// Create the theme update object
			const themeUpdate: ThemeUpdate = {};
			if ( settings ) {
				themeUpdate.settings = settings;
			}
			if ( styles ) {
				themeUpdate.styles = styles;
			}

			// Call the updateTheme function
			const success = await updateTheme( themeUpdate );

			const successMessage = __(
				'Theme updated successfully',
				'big-sky'
			);
			if ( success ) {
				// Create assistant message and associate checkpoint with it
				// This ensures the restore button appears in CompletedPlan component
				const assistantMessage = await assistantSay( successMessage );
				const assistantMessageId = assistantMessage?.message?.id;
				if ( assistantMessageId ) {
					changeCheckpointId( checkpointId, assistantMessageId );
					addCheckpointKeys( assistantMessageId, [
						checkpointKeys.COLOR,
					] );
					showResponseActions( assistantMessageId );
				}

				return {
					result: successMessage,
					returnToAgent: followUpTasks ?? false,
				};
			}

			return {
				result: failMessage,
				returnToAgent: followUpTasks ?? false,
			};
		} catch ( error ) {
			return {
				result: failMessage,
				returnToAgent: followUpTasks ?? false,
			};
		}
	};

	return {
		updateTheme: updateThemeSettings,
	};
}
