/**
 * WordPress dependencies
 */
import {
	resolveSelect,
	useDispatch,
	useRegistry,
	useSelect,
} from '@wordpress/data';
import { store as blockEditorStore } from '@wordpress/block-editor';
import { store as editorStore } from '@wordpress/editor';
import { __ } from '@wordpress/i18n';

/**
 * Internal dependencies
 */
import useBlocks from '@hooks/use-blocks';
import useCheckpoint from '@hooks/use-checkpoint';
import { store as aiStore } from '@store';
import { checkpointKeys } from '@utils/constants';
import logger from '@utils/log-debug';
import showResponseActions from '@utils/show-completed-plan';
import { setSiteLogoCore } from '@utils/set-site-logo-core';

/**
 * Types
 */
interface FileObj {
	url: string;
	attachment_id: number;
}

interface SetSiteLogoArgs {
	fileObj: FileObj;
	clientId: string;
	followUpTasks?: boolean;
	messageId: string;
}

interface SetSiteLogoResult {
	result: string;
	returnToAgent?: boolean;
}

interface ClientIdMap {
	[ key: string ]: string;
}

interface Block {
	clientId: string;
	name: string;
	attributes?: Record< string, unknown >;
	innerBlocks?: Block[];
}

interface AssistantMessage {
	message: {
		id: string;
	};
}

export const useSetSiteLogo = (): {
	setSiteLogo: ( args: SetSiteLogoArgs ) => Promise< SetSiteLogoResult >;
} => {
	const { deleteMarkedMessages, assistantSay, changeCheckpointId } =
		useDispatch( aiStore ) as {
			deleteMarkedMessages: () => void;
			assistantSay: (
				message: string,
				options?: any
			) => Promise< AssistantMessage >;
			changeCheckpointId: ( oldId: string, newId: string ) => void;
		};
	const registry = useRegistry();
	const { setCheckpoint } = useCheckpoint();
	const { getBlock } = useSelect(
		( select ) => ( {
			getBlock: ( select( blockEditorStore ) as any ).getBlock,
		} ),
		[]
	) as {
		getBlock: ( clientId: string ) => Block | null;
	};
	const { setBlockIsProcessing } = useBlocks();

	// Get clientIdMap from store (instead of it being injected via args)
	const clientIdMap = useSelect(
		( select ) =>
			select( aiStore ).getFullPageStructure()?.clientIdMap || {},
		[]
	) as ClientIdMap;

	/**
	 * Set the site logo in the editor
	 *
	 * @param {SetSiteLogoArgs} args               - The arguments for the set site logo tool
	 * @param {FileObj}         args.fileObj       - The site logo as a file object
	 * @param {string}          args.clientId      - The client ID of the block that is being processed
	 * @param {boolean}         args.followUpTasks - Whether to return to the agent after the logo is set
	 * @param {string}          args.messageId     - The message ID from the agent response
	 * @return {Promise<SetSiteLogoResult>} The result of the set site logo tool
	 */
	const setSiteLogo = async ( {
		fileObj,
		clientId,
		followUpTasks,
		messageId,
	}: SetSiteLogoArgs ): Promise< SetSiteLogoResult > => {
		// Use clientIdMap from hook closure as reverseMap
		const reverseMap = clientIdMap;
		try {
			// add a checkpoint
			setCheckpoint( messageId, [ checkpointKeys.LOGO ] );

			// Use the core utility function to set the logo
			const result = await setSiteLogoCore( {
				attachmentId: fileObj.attachment_id,
				logoUrl: fileObj.url,
				registry,
			} );

			if ( ! result.success ) {
				throw new Error( result.error || 'Failed to set logo' );
			}

			// delete the marked messages
			deleteMarkedMessages();

			// get the current post id
			const currentPostId =
				await resolveSelect( editorStore ).getCurrentPostId();

			// send the component to the assistant
			const assistantMessage = await assistantSay(
				'Generated site logo',
				{
					postId: currentPostId,
				}
			);

			// show the response actions
			const assistantMessageId = assistantMessage?.message?.id;
			changeCheckpointId( messageId, assistantMessageId );
			showResponseActions( assistantMessageId );

			// return the result
			return {
				result: 'Logo set successfully',
				returnToAgent: followUpTasks,
			};
		} catch ( error ) {
			logger.error( `Error setting site logo:`, error );
			deleteMarkedMessages();
			await assistantSay(
				__(
					'There was an error with this request. Please try again.',
					'big-sky'
				)
			);
			return {
				result: `There was an error with this request.`,
				returnToAgent: followUpTasks,
			};
		} finally {
			// reset the block processing state
			const originalClientId = reverseMap[ clientId ];
			const block = getBlock( originalClientId );
			if ( block ) setBlockIsProcessing( block, false );
		}
	};

	return { setSiteLogo };
};
