/**
 * WordPress dependencies
 */
import { dispatch, select } from '@wordpress/data';
import { store as editorStore } from '@wordpress/editor';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import CompletedPlan from '@components/chat/components/completed-plan';

/**
 * Shows a completed plan component in the chat interface.
 * This function consolidates the common pattern of displaying a CompletedPlan
 * component with the appropriate message role and post ID.
 *
 * @param {string}   assistantMessageId               - The ID of the assistant message to associate with the completed plan
 * @param {Object}   options                          - Additional options for the completed plan
 * @param {Function} options.onAfterRestoreCheckpoint - Callback function to execute after restoring a checkpoint
 * @param {string}   options.key                      - React key for the component (defaults to "response-actions")
 * @return {Promise<Object>} The result of the assistantSay call
 */
export const showResponseActions = async (
	assistantMessageId,
	options = {}
) => {
	const { addMessage } = dispatch( aiStore );
	const { getCurrentPostId } = select( editorStore );

	const { onAfterRestoreCheckpoint = () => {} } = options;
	return addMessage( {
		role: 'assistant',
		postId: getCurrentPostId(),
		content: [
			{
				type: 'component',
				component: CompletedPlan,
				componentProps: {
					id: assistantMessageId,
					onAfterRestoreCheckpoint,
				},
			},
		],
	} );
};

export default showResponseActions;
