/**
 * WordPress dependencies
 */
import { select } from '@wordpress/data';
import { store as blocksStore } from '@wordpress/blocks';

/**
 * Checks if a block is a direct image block (like core/image).
 * @param {Object} block The block to check
 * @return {boolean} Whether the block directly handles images
 */
export const isDirectImageBlock = ( block ) => {
	if ( ! block ) {
		return false;
	}
	const directImageBlocks = [
		'core/image',
		'core/site-logo',
		'core/media-text',
	];
	return directImageBlocks.includes( block.name );
};

/**
 * Checks if a block supports background images.
 * @param {Object} block The block to check
 * @return {boolean} Whether the block supports background images
 */
export const supportsBackgroundImage = ( block ) => {
	if ( ! block ) {
		return false;
	}
	const getBlockSupport = select( blocksStore ).getBlockSupport;
	return !! getBlockSupport( block.name, 'background.backgroundImage' );
};

/**
 * Checks if a block can use background images (either as a cover block or by supporting background images).
 * @param {Object} block The block to check
 * @return {boolean} Whether the block can use background images
 */
export const canUseBackgroundImages = ( block ) => {
	if ( ! block ) {
		return false;
	}
	return block.name === 'core/cover' || supportsBackgroundImage( block );
};

/**
 * Builds the attributes object to update a block with an image.
 *
 * @param {Object} block       The block to update
 * @param {string} imageUrl    The URL of the image to set
 * @param {string} description The alt text/description for the image
 * @return {Object} Object containing attributes to update
 */
export const buildAttrToUpdateImage = ( block, imageUrl, description ) => {
	// Core blocks that should always handle images via URL
	const urlBasedBlocks = [
		'core/image',
		'core/cover',
		'core/site-logo',
		'core/media-text',
	];

	// If it's a URL-based block, handle it directly
	if ( urlBasedBlocks.includes( block.name ) ) {
		const attrToUpdate = {};

		// Media text is an edge case.
		if ( block.name === 'core/media-text' ) {
			attrToUpdate.mediaUrl = imageUrl || '';
			attrToUpdate.mediaAlt = description || '';
		} else {
			attrToUpdate.url = imageUrl || '';
			attrToUpdate.alt = description || '';
		}

		// Special handling for cover block opacity
		if (
			block.name === 'core/cover' &&
			block.attributes.dimRatio === 100
		) {
			attrToUpdate.dimRatio = 50;
		}
		return attrToUpdate;
	}

	// For other blocks, check background image support
	const { getBlockSupport } = select( blocksStore );
	const hasBackgroundImageSupport = getBlockSupport(
		block.name,
		'background.backgroundImage',
		false
	);

	if ( hasBackgroundImageSupport ) {
		return {
			style: {
				...block.attributes.style,
				background: {
					...block.attributes.style?.background,
					backgroundImage: imageUrl
						? {
								source: 'file',
								url: decodeURIComponent( imageUrl ),
						  }
						: undefined,
				},
			},
		};
	}

	return {};
};

/**
 * Gets the current image URL and alt text from a block.
 *
 * @param {Object} block The block to get image data from
 * @return {Object} Object containing the current url and alt values
 */
export const getBlockImageData = ( block ) => {
	if ( ! block ) {
		return { url: null, alt: null };
	}

	// Core blocks that should always handle images via URL
	const urlBasedBlocks = [
		'core/image',
		'core/cover',
		'core/site-logo',
		'core/media-text',
	];

	// If it's a URL-based block, handle it directly
	if ( urlBasedBlocks.includes( block.name ) ) {
		// Media text is an edge case - it uses mediaUrl instead of url
		if ( block.name === 'core/media-text' ) {
			return {
				url: block.attributes?.mediaUrl || null,
				alt: block.attributes?.mediaAlt || null,
			};
		}

		return {
			url: block.attributes?.url || null,
			alt: block.attributes?.alt || null,
		};
	}

	// For other blocks, check background image support
	const { getBlockSupport } = select( blocksStore );
	const hasBackgroundImageSupport = getBlockSupport(
		block.name,
		'background.backgroundImage',
		false
	);

	if ( hasBackgroundImageSupport ) {
		return {
			url:
				block.attributes?.style?.background?.backgroundImage?.url ||
				null,
			alt: null, // Background images typically don't have alt text
		};
	}

	return { url: null, alt: null };
};

/**
 * Checks if a block has a background image already set.
 * @param {any} block The block to check
 * @return {boolean} Whether the block has a background image
 */
export const hasBackgroundImage = ( block ) => {
	if ( ! block ) {
		return false;
	}
	if ( block.name === 'core/cover' ) {
		return !! block.attributes?.url;
	}
	return !! block.attributes?.style?.background?.backgroundImage?.url;
};
