/**
 * External dependencies
 */
import { __ } from '@wordpress/i18n';

/**
 * Internal dependencies
 */
import './style.scss';

/**
 * Extracts text content from a message object
 *
 * @param {Object} message The message object
 * @return {string} The text content
 */
const getMessageText = ( message ) => {
	if ( ! message?.content ) {
		return '';
	}

	// Handle string content directly
	if ( typeof message.content === 'string' ) {
		return message.content;
	}

	// Handle array content
	const content = Array.isArray( message.content )
		? message.content
		: [ message.content ];

	// Look for text block
	const textBlock = content.find(
		( block ) => block.type === 'text' && block.text
	);
	if ( textBlock?.text ) {
		return textBlock.text;
	}

	// Fallback: try to get text from first block
	if ( content[ 0 ]?.text ) {
		return content[ 0 ].text;
	}

	return '';
};

/**
 * Returns the CSS class for the indicator based on item state
 *
 * @param {Object} item The item object
 * @return {string} The CSS class name
 */
const getIndicatorClass = ( item ) => {
	if ( item.completed ) {
		return 'site-build-progress__indicator--completed';
	}
	return 'site-build-progress__indicator--loading';
};

/**
 * Checkmark icon for completed items
 */
const CheckmarkIcon = (
	<svg
		width="12"
		height="12"
		viewBox="0 0 12 12"
		fill="none"
		xmlns="http://www.w3.org/2000/svg"
	>
		<path
			d="M10 3L4.5 8.5L2 6"
			stroke="currentColor"
			strokeWidth="2"
			strokeLinecap="round"
			strokeLinejoin="round"
		/>
	</svg>
);

/**
 * SiteBuildProgress component displays site build progress messages
 * in a grouped card format with checkmarks and connecting lines.
 *
 * @param {Object}   props                 Component props
 * @param {Object[]} props.messages        Array of message objects with context: 'site-build-completed'
 * @param {string}   props.thinkingMessage Current thinking/progress message (shown as in-progress item)
 * @return {JSX.Element} The rendered component
 */
export default function SiteBuildProgress( { messages, thinkingMessage } ) {
	const hasMessages = messages && messages.length > 0;
	const hasThinkingMessage = Boolean( thinkingMessage );

	if ( ! hasMessages && ! hasThinkingMessage ) {
		return null;
	}

	const completedItems = hasMessages
		? messages.map( ( message ) => ( {
				id: message.id,
				text: getMessageText( message ),
				completed: true,
		  } ) )
		: [];

	// Add in-progress item if building
	const allItems = hasThinkingMessage
		? [
				...completedItems,
				{
					id: 'thinking',
					text: thinkingMessage,
					completed: false,
				},
		  ]
		: completedItems;

	return (
		<div className="site-build-progress">
			<div className="site-build-progress__header">
				<span className="site-build-progress__title">
					{ __( 'Generating your site', 'big-sky' ) }
				</span>
			</div>
			<ul className="site-build-progress__list">
				{ allItems.map( ( item, index ) => (
					<li
						key={ item.id }
						className={ `site-build-progress__item ${
							! item.completed
								? 'site-build-progress__item--in-progress'
								: ''
						}` }
						data-last={ index === allItems.length - 1 }
					>
						<div
							className={ `site-build-progress__indicator ${ getIndicatorClass(
								item
							) }` }
						>
							{ item.completed ? (
								CheckmarkIcon
							) : (
								<div className="site-build-progress__spinner" />
							) }
						</div>
						<span className="site-build-progress__text">
							{ item.text }
						</span>
					</li>
				) ) }
			</ul>
		</div>
	);
}
