import * as Sentry from '@sentry/react';
import { store as aiStore } from '@store';

if ( ! process.env.DEBUG || process.env.DEBUG === 'false' ) {
	// Get session ID from store - safely handle cases where store isn't available yet
	let sessionId, userId, blogId;
	try {
		const store = aiStore.instantiate().store;
		const state = store.getState();
		sessionId = state.sessionId;
		userId = state.userId;
		blogId = state.blogId;
	} catch ( error ) {
		// Store not available yet, initialize without user context
		sessionId = null;
		userId = null;
		blogId = null;
	}

	Sentry.init( {
		dsn: 'https://1d0b238bf1772be224eb4bd9e3914625@o248881.ingest.us.sentry.io/4507058275876864',
		sampleRate: 1.0,
		tracesSampleRate: 0.1,
		profilesSampleRate: 0.1, // this is a fraction of the tracesSampleRate
		denyUrls: [
			// Matches browser extension URLs, like "moz-extension://..." or "safari-web-extension://..."
			/^[a-z]+(-[a-z]+)?-extension:\/\/\//i,
		],
		integrations: [
			Sentry.browserProfilingIntegration(),
			Sentry.browserTracingIntegration(),
			Sentry.replayIntegration( {
				maskAllText: true,
				blockAllMedia: true,
			} ),
			// enable if you want to record canvas elements
			// Sentry.replayCanvasIntegration(),
		],

		tracePropagationTargets: [
			'localhost',
			/^https:\/\/.*.jurassic.tube\//,
			/^https:\/\/.*.jurassic.ninja\//,
			/^https:\/\/.*.wpcomstaging.com.com\//,
			// when uncommented, this line messes with CORS. It should only be enabled when the origin is *.wordpress.com
			// /^https:\/\/.*.wordpress.com\//,
		],

		replaysSessionSampleRate: 0.1,
		replaysOnErrorSampleRate: 1.0,

		// Add user context
		initialScope: ( scope ) => {
			if ( userId ) {
				scope.setUser( {
					id: userId,
				} );
			}
			if ( sessionId ) {
				scope.setTag( 'session_id', sessionId );
			}
			if ( blogId ) {
				scope.setTag( 'blog_id', blogId );
			}
			return scope;
		},
	} );
}

export default Sentry;
